  [54, \"gb3\", 53, 55],\r\n    [57, \"a3\", 56, 58],\r\n    [60, \"c4\", 59, 61],\r\n    [63, \"eb4\", 62, 64],\r\n    [66, \"gb4\", 65, 67],\r\n    [69, \"a4\", 68, 70],\r\n    [72, \"c5\", 71, 73],\r\n    [75, \"eb5\", 74, 76],\r\n    [78, \"gb5\", 77, 79],\r\n    [81, \"a5\", 80, 82],\r\n    [84, \"c6\", 83, 91]\r\n];\r\nfn electric_takes(takes) = electric_roots\r\n    .map(\r\n        fn(z) => range(3)\r\n            .map(\r\n                fn(v) => takes.map(fn(take) => {\r\n                    path: format(\"assets/guitar/Samples/electric/{}_vl{}_rr{}_2.wav\", [\r\n                        z[1],\r\n                        v + 2,\r\n                        take\r\n                    ]),\r\n                    root: z[0],\r\n                    keys: [z[2], z[3]],\r\n                    velocity: [[0, 64.5 / 127], [64.5 / 127, 96.5 / 127], [96.5 / 127, 1]][v]\r\n                })\r\n            )\r\n            .fold([], fn(a, b) => a + b)\r\n    )\r\n    .fold([], fn(a, b) => a + b);\r\nlet electric_left_zones = electric_takes([1, 3]);\r\nlet electric_right_zones = electric_takes([2, 4]);\r\nlet electric_release_zones = electric_roots\r\n    .map(\r\n        fn(z) => [1, 2].map(fn(take) => {\r\n            path: format(\"assets/guitar/Samples/electric/{}_release_rr{}_2.wav\", [z[1], take]),\r\n            root: z[0],\r\n            keys: [z[2], z[3]]\r\n        })\r\n    )\r\n    .fold([], fn(a, b) => a + b);\r\n\r\n// Builders: a function body evaluates in its defining module, so these calls\r\n// stamp this pack's directory as the asset root. Calling sample() from a piece\r\n// instead would resolve the zone paths against that piece's directory.\r\nfn acoustic(options = {}) = sample(acoustic_zones, options);\r\nfn electric(options = {}) = sample(electric_zones, options);\r\nfn electric_left(options = {}) = sample(electric_left_zones, options);\r\nfn electric_right(options = {}) = sample(electric_right_zones, options);\r\nfn electric_release(options = {}) = sample(electric_release_zones, options);\r\n// Build an adjusted zone table (a different take selection or register) while\r\n// keeping this pack as the asset root.\r\nfn instrument(zones, options = {}) = sample(zones, options);\r\n","contrib/karoryfer/performance.muz":"// Optional source arrangements over the existing maps. No pedal/choke inference.\r\nuse \"guitar.muz\" as guitar;\r\nuse \"std/instrument\" as instrument;\r\nfn electric_with_releases(id, pattern, options = {}, release_options = {}, timing = {}) = [\r\n    track(id, pattern, guitar.electric(merge({one_shot: false}, options))),\r\n    track(\r\n        id + \"-release\",\r\n        instrument.releases(pattern, 100ms, timing),\r\n        guitar.electric_release(merge({one_shot: true}, release_options))\r\n    )\r\n];\r\n\r\n// Opt-in note-local brightness, preserving the pack's recording calibration.\r\nuse \"std/signal\" as s;\r\nfn expressive(zones, keys, tone = 6000Hz, options = {}, sample_budget_frames = 8388608) {\r\n    assert(len(keys) == 2 && keys[0] <= keys[1], \"keys must be [low, high]\");\r\n    let selected = map(\r\n        filter(zones, fn(z) => z.keys[0] <= keys[1] && z.keys[1] >= keys[0]),\r\n        fn(z) => merge(z, {keys: [max(z.keys[0], keys[0]), min(z.keys[1], keys[1])]})\r\n    );\r\n    instrument.sampled(\r\n        guitar.instrument(selected, options),\r\n        s.octaves(s.param(\"tone\", tone, 100Hz, 12000Hz), s.expression(\"pressure\")),\r\n        {sample_budget_frames: sample_budget_frames}\r\n    )\r\n};\r\n","contrib/karoryfer/sfz.muz":"// Original SFZ programs. Install sfz-complete assets before use.\r\n// Catalog IDs and paths are recorded in sfz-catalog.json.\r\nfn program(path, options = {}) = sfz(path, options);\r\n\r\nfn shinyguitar(options = {}) = sfz(\"assets/guitar/Programs/main.sfz\", merge({defines: {sample_dir: \"../Samples\"}}, merge({sample_budget_frames: 154140672}, options)));\r\nfn program_01_darkblack_keysw(options = {}) = sfz(\"assets/bass/Programs/01-darkblack_keysw.sfz\", merge({sample_budget_frames: 230686720}, options));\r\nfn program_02_darkblack_keysw_warm(options = {}) = sfz(\"assets/bass/Programs/02-darkblack_keysw_warm.sfz\", merge({sample_budget_frames: 96468992}, options));\r\nfn program_03_babyblue_all(options = {}) = sfz(\"assets/bass/Programs/03-babyblue_all.sfz\", merge({sample_budget_frames: 146800640}, options));\r\nfn program_04_babyblue_warm(options = {}) = sfz(\"assets/bass/Programs/04-babyblue_warm.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_05_darkblack_pluck(options = {}) = sfz(\"assets/bass/Programs/05-darkblack_pluck.sfz\", merge({sample_budget_frames: 158334976}, options));\r\nfn program_06_darkblack_pluck_warm(options = {}) = sfz(\"assets/bass/Programs/06-darkblack_pluck_warm.sfz\", merge({sample_budget_frames: 83886080}, options));\r\nfn program_07_darkblack_ghost(options = {}) = sfz(\"assets/bass/Programs/07-darkblack_ghost.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_08_darkblack_ghost_warm(options = {}) = sfz(\"assets/bass/Programs/08-darkblack_ghost_warm.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_09_darkblack_stac(options = {}) = sfz(\"assets/bass/Programs/09-darkblack_stac.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_10_darkblack_btb(options = {}) = sfz(\"assets/bass/Programs/10-darkblack_btb.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_11_darkblack_btb_open(options = {}) = sfz(\"assets/bass/Programs/11-darkblack_btb_open.sfz\", merge({sample_budget_frames: 67108864}, options));\r\n","contrib/plugins/README.md":"# Shared plugin recipes\r\n\r\nReusable settings for VST3/CLAP instruments and effects, plus helpers for JUCE\r\npreset containers. Install plugins from their publishers and configure local\r\naliases before using these modules. This pack ships no plugin binaries or preset\r\nstate dumps; project-specific state belongs with the project that owns the sound.\r\n\r\n[All packs](../../contrib/README.md) · [Instrument guide](../../docs/instruments.md)\r\n\r\nRun shell commands from the `muz-core` checkout unless stated otherwise.\r\nFor the installed CLI, run these utilities from the installed contrib copy\r\ncreated by `./install.sh`; see the [pack setup guide](../../contrib/README.md#install-and-import).\r\n\r\n## Contents\r\n\r\n- [Install and configure aliases](#install-and-configure-aliases)\r\n- [Use the modules](#use-the-modules)\r\n- [Create or inspect state files](#create-or-inspect-state-files)\r\n- [OrbitCab](#orbitcab)\r\n- [CHOWTapeModel](#chowtapemodel)\r\n- [Surge XT](#surge-xt)\r\n- [Pianoteq](#pianoteq)\r\n- [Pack maintenance](#pack-maintenance)\r\n\r\n## Install and configure aliases\r\n\r\nInstall the plugin you need; versions, formats, and licenses are listed below.\r\nOrbitCab has a pinned installer:\r\n\r\n```sh\r\npython3 contrib/plugins/orbitcab-install.py\r\n```\r\n\r\nThe command verifies the download and extracted binary and refuses to replace a\r\ndifferent build. Add `--dest DIR` for another plugin directory or `--check` to\r\nverify an existing install. Other plugins are installed separately.\r\n\r\nMachine paths and plugin class identifiers live in\r\n`$XDG_CONFIG_HOME/muz/plugins.json` (normally `~/.config/muz/plugins.json`);\r\n`MUZ_PLUGIN_CONFIG` selects another file. These are example paths; replace them\r\nwith your installed binaries and inspected class IDs. Use only the aliases you need:\r\n\r\n```json\r\n{\r\n  \"default\": {\"path\": \"/opt/pianoteq/Pianoteq 9.vst3\", \"class\": \"the-class-from-muz-devices-inspect\"},\r\n  \"orbitcab\": {\"path\": \"/usr/lib/clap/OrbitCab.clap\", \"class\": \"com.darwinscat.orbitcab\"},\r\n  \"chowtape\": {\"path\": \"/usr/lib/clap/CHOWTapeModel.clap\", \"class\": \"org.chowdsp.CHOWTapeModel\"},\r\n  \"surge\": {\"path\": \"/usr/lib/clap/Surge XT.clap\", \"class\": \"org.surge-synth-team.surge-xt\"}\r\n}\r\n```\r\n\r\nTo add an alias: run `muz devices inspect <installed plugin path>`, copy its\r\n`id` into `class`, point `path` at the installed binary, and give it the alias\r\nname a module expects. Relative `path` values resolve against the configuration\r\nfile's directory; an absolute path is the usual choice. A `plugin()` or `piano()`\r\nthat names an alias missing from this file fails with the alias named. An alias\r\nsupplies `path` and, when the source sets no `class`, its `class`; other keys are\r\nignored, and an explicit source field overrides the alias.\r\n\r\n## Use the modules\r\n\r\n```muz\r\nuse \"contrib/plugins/chowtape\" as tape;\r\nuse \"contrib/plugins/orbitcab\" as amp;\r\nuse \"contrib/plugins/surge-xt\" as surge;\r\nuse \"contrib/plugins/pianoteq\" as ptq;\r\n```\r\n\r\nEach module is also importable on its own; the pack has no shared index.\r\n\r\n### Why the device call stays in your module\r\n\r\nA device's `state:` path resolves against the `.muz` file that declares it, and a\r\nfunction body evaluates in its defining module. A wrapper defined here would\r\ntherefore resolve a project-relative state path against `contrib/plugins/`. The\r\nmodules above consequently export the *settings record* and document the call\r\nsite; the `plugin()`/`piano()` call, and the path, stay in your own source:\r\n\r\n```muz\r\nlet guitar = plugin(\"orbitcab\", amp.settings(\"assets/amp/sheriff-greenback.state\"));\r\nlet bass = plugin(\"surge\", surge.settings(\"assets/surge/piston-bass.state\"));\r\nlet keys = piano(\"default\", ptq.settings(\"assets/piano/bechstein-warm.state\"));\r\n```\r\n\r\n`chowtape.muz` is the exception: its recipe carries no file paths, so\r\n`tape.tape(mix)` builds the whole insert. For example, after configuring `chowtape`,\r\nthis complete song processes a native synth through it:\r\n\r\n```muz\r\nuse \"contrib/plugins/chowtape\" as tape;\r\nsong({tracks: [track(\"lead\", phrase(\"C4:q E4:q G4:h\"), synth(\"glass-lead\"), {\r\n    chain: [tape.tape(0.32)]\r\n})]})\r\n```\r\n\r\n## Create or inspect state files\r\n\r\n`.state` files belong to the composer's project; this library never ships them.\r\nBuild one from an editable XML payload with the helper in this directory:\r\n\r\n```sh\r\npython3 contrib/plugins/juce_state.py --wrap preset.xml --state preset.state\r\npython3 contrib/plugins/juce_state.py --check preset.state --xml preset.xml\r\npython3 contrib/plugins/juce_state.py --unwrap preset.state --payload preset.xml\r\n```\r\n\r\n`--check` decodes a stored state, re-encodes it and reports whether the bytes\r\nmatch, so a generated container can be proven byte-identical before it is\r\ncommitted to a project. `--template` reuses a stored container's header and\r\ntrailing block when a plugin's state is more than payload plus wrapper.\r\n\r\n## OrbitCab\r\n\r\n- Upstream: OrbitCab by Darwin's Cat - <https://github.com/darwinscat/orbitcab>\r\n  (homepage <https://darwinscat.com/orbitcab>), version 2.5.0.\r\n- Format: CLAP (upstream also builds VST3 and AU). Installed as\r\n  `OrbitCab.clap` on a CLAP search path such as `~/.clap` or `/usr/lib/clap`.\r\n- License: AGPL-3.0. The plugin's bundled preamp captures and cabinet impulse\r\n  responses are content owned by its publisher; we redistribute none of them.\r\n- Alias this pack expects: `orbitcab`, class id `com.darwinscat.orbitcab`.\r\n- Install the pinned build with `python3 contrib/plugins/orbitcab-install.py`\r\n  (add `--dest <dir>` for another plugin directory, `--check` to verify only).\r\n  It refuses to replace a different build and verifies the release archive and\r\n  the extracted binary against `orbitcab-manifest.json`.\r\n- State convention: the plugin's tone - preamp capture, power stage, cabinet IR -\r\n  lives in a JUCE `VC2!` container. Keep the XML source for it in your project\r\n  and rebuild the container with `juce_state.py`; do not copy a state file out of\r\n  another project and do not commit one here.\r\n- Module: `orbitcab.muz` exports `settings(state, overrides = {})`. Two\r\n  independent mono instances panned after the plugin give the doubled width.\r\n\r\n## CHOWTapeModel\r\n\r\n- Upstream: CHOWTapeModel by Chowdhury DSP (Jatin Chowdhury) -\r\n  <https://github.com/jatinchowdhury18/AnalogTapeModel>, version 2.11.4.\r\n- Format: CLAP. Installed as `CHOWTapeModel.clap` on a CLAP search path.\r\n- License: GPL-3.0.\r\n- Alias this pack expects: `chowtape`, class id `org.chowdsp.CHOWTapeModel`.\r\n- State convention: none. The module is a pure parameter recipe, so it has no\r\n  preset state to keep; every setting it writes is named and commented in\r\n  `chowtape.muz`.\r\n- Module: `chowtape.muz` exports `tape(mix, drive, saturation)` (and the harder\r\n  `driven(mix)`). Both use 4x oversampling on the live and render paths with tone\r\n  processing, head-loss coloration and wow/flutter switched off.\r\n\r\n## Surge XT\r\n\r\n- Upstream: Surge XT by the Surge Synth Team -\r\n  <https://github.com/surge-synthesizer/surge> (downloads at\r\n  <https://surge-synthesizer.github.io>), version 1.3.4.\r\n- Format: CLAP (upstream also builds VST3 and AU/standalone).\r\n- License: GPL-3.0. Factory patches are content of that project; we\r\n  redistribute none of them.\r\n- Alias this pack expects: `surge`, class id `org.surge-synth-team.surge-xt`.\r\n- State convention: patches are `.state` files authored from an editable XML with\r\n  `juce_state.py`. Surge's container is the 32-byte `sub3` form, which also\r\n  carries a trailing block after the XML payload; build it with\r\n  `--magic sub3 --template original.state` so the header and trailing block are\r\n  preserved. Your project keeps the XML and the `.state` it builds.\r\n- Module: `surge-xt.muz` exports `settings(state, overrides = {})`.\r\n\r\n## Pianoteq\r\n\r\n- Upstream: Pianoteq by Modartt - <https://www.modartt.com/pianoteq>, version 9\r\n  (the composer's installed build).\r\n- Format: VST3 (also AU/AAX/standalone). The builtin `piano()` resolves the\r\n  `default` alias unless the source names another plugin.\r\n- License: proprietary, commercial. Editions and instrument packs are licensed\r\n  per user; the instrument a state refers to must be owned by whoever renders it.\r\n- Alias this pack expects: `default`.\r\n- State convention: project-owned component state, captured from the installed\r\n  instrument. The library ships no instrument, license, or state assets;\r\n  `pianoteq.muz` pins no engine parameters.\r\n- Module: `pianoteq.muz` exports `settings(state, overrides = {})`.\r\n- MIDI mapping: `pianoteq/classical-guitar.ptm` is a six-string guitar workflow\r\n  mapping - channels 0-5 carry the strings, channel 15 carries technique keys,\r\n  and controllers 64/66/67/69 drive the instrument's `Pdl[4]/[3]/[1]/[2]`\r\n  pedals. Install it as `~/.local/share/Modartt/Pianoteq/MidiMappings/<name>.ptm`\r\n  on Linux and select it in the instrument's MIDI settings; a preset that refers\r\n  to a mapping by name mis-routes silently while that mapping is absent.\r\n\r\n### Headless factory-preset capture (Linux 9.2.4)\r\n\r\n```sh\r\npython3 contrib/plugins/pianoteq-state.py \\\r\n  --preset 'C. Bechstein DG Warm' --output state/bechstein-dg-warm.state\r\n```\r\n\r\n`--preset` is an exact, case-sensitive factory name, not a filename or fuzzy\r\nsearch. The required `--output`/`-o` belongs to the consuming project. Use\r\n`piano(\"default\", {state: \"state/bechstein-dg-warm.state\", reverb_switch: 0})`\r\nto load it and apply composition-owned overrides afterward. Capture leaves\r\nfactory reverb, resonance, dynamics, and pedal settings unchanged.\r\n\r\nThe helper defaults to the `default` alias and `muz` on `PATH`. `--plugin`\r\naccepts an existing VST3 path or an alias from `MUZ_PLUGIN_CONFIG`, otherwise\r\n`$XDG_CONFIG_HOME/muz/plugins.json` (normally `~/.config/muz/plugins.json`).\r\nRelative alias paths resolve against that config's directory; the alias's class\r\nis retained unless `--class ID` overrides it. `--muz PATH` selects another host\r\nbinary. `--pianoteq PATH` selects the matching standalone; by default it is the\r\nresolved plugin path with `.vst3` removed, without searching other installs.\r\n\r\nReadable, already-activated preferences and the requested licensed instrument\r\npack are prerequisites. `--prefs PATH` overrides the original configuration\r\nroot's `Modartt/Pianoteq92.prefs`. Preferences are copied with mode 0600 into a\r\nprivate temporary configuration root on the destination filesystem. All child\r\nprocesses use that root, and the standalone receives the copied `--prefs` path.\r\nThe user's data-root environment remains available for installed instruments\r\nand MIDI mappings; original preferences and the parent environment are not\r\nmodified. The helper neither activates an installation nor creates empty\r\nactivation preferences.\r\n\r\nVerified compatibility: Linux Pianoteq **9.2.4**. Its standalone\r\n`--export-vst3-presets DIR --export-presets-filter builtin` emitted 800 standard\r\nVST3 presets in the installed build; the exact Warm preset loaded/resaved through\r\nmuz and retained its identity. The shared helper also captured the Bechstein DG,\r\nSteingraeber, and YC5 Felt I presets, and the Warm state passed an isolated tiny\r\nrender. This is muz-maintained compatibility tooling, not a vendor-endorsed\r\ncomponent-format contract. Other platforms or versions fail explicitly rather\r\nthan guessing a layout or preferences filename.\r\n\r\nCapture uses native VST3 export only: validate containers and the version-specific\r\ncomponent framing, select exactly one preset by its length-prefixed UTF-8\r\nidentity, load/resave through the installed plugin, and verify that identity\r\ninside the selected component payload. No LV2 decoding, private bank mutation,\r\nlast-used-state fallback, borrowed template, or GUI step is involved. Only the\r\nplugin's accepted/resaved component is atomically published. Missing/ambiguous\r\npresets, malformed state, export/load failures, and publication failures leave\r\nan existing destination untouched; destinations resolving to capture inputs\r\nare rejected.\r\n\r\n\r\n## Pack maintenance\r\n\r\n| File | What it owns |\r\n| --- | --- |\r\n| `orbitcab.muz` | alias + settings record for the OrbitCab amp/cabinet insert |\r\n| `orbitcab-manifest.json` | pinned OrbitCab release: URL, archive and binary SHA-256 |\r\n| `orbitcab-install.py` | installs/verifies that build in the user plugin directory |\r\n| `chowtape.muz` | tape insert recipe (parameter ids, oversampling policy, switches) |\r\n| `surge-xt.muz` | alias + settings record for a Surge XT instrument instance |\r\n| `pianoteq.muz` | alias + settings record over the builtin `piano(\"default\", …)` convention |\r\n| `pianoteq-state.py` | isolated native factory-preset capture for Linux Pianoteq 9.2.4 |\r\n| `pianoteq/classical-guitar.ptm` | Pianoteq MIDI mapping for a six-string guitar workflow |\r\n| `juce_state.py` | wrap/unwrap the `VC2!`, `VstW`/`sub3` and raw-XML state forms |\r\n\r\nThe following checks are useful when editing pack source or the state helper:\r\n\r\n```sh\r\n./target/release/muz fmt --check contrib/plugins/*.muz\r\npython3 -m py_compile contrib/plugins/juce_state.py\r\npython3 -B contrib/plugins/test-pianoteq-state.py\r\n```\r\n","contrib/plugins/chowtape.muz":"// CHOWTapeModel tape insert for the shared plugin pack. This module owns the\r\n// tape recipe: the plugin's integer CLAP parameter ids, the 4x-oversampling\r\n// policy, and the switches that keep the stage free of playback-head\r\n// coloration. The recipe carries no file paths, so `tape(mix)` can build the\r\n// whole device.\r\n//\r\n// Alias: `chowtape` -> CHOWTapeModel.clap in plugins.json (see README.md).\r\n// Upstream: CHOWTapeModel 2.11.4, GPL-3.0, class org.chowdsp.CHOWTapeModel.\r\n//\r\n// Names below are the plugin's own controls, read from the running build with\r\n// `muz devices inspect`.\r\nfn tape(mix = 0.32, drive = 0.20, saturation = 0.30) = plugin(\"chowtape\", {\r\n    // Dry/Wet: blend of the processed tape return against the dry signal.\r\n    p2971918811: mix,\r\n    // Tape Drive: level into the tape transfer curve, the head-bump and\r\n    // soft-compression region of the machine.\r\n    p95852938: drive,\r\n    // Tape Saturation: magnetic saturation depth, the softer counterpart to\r\n    // the drive control.\r\n    p113638: saturation,\r\n    // Tone On/Off: 0 leaves the input band untouched.\r\n    p620121635: 0,\r\n    // Loss On/Off: 0 disables head-loss coloration.\r\n    p1856496404: 0,\r\n    // Wow/Flutter On/Off: 0 disables pitch wander.\r\n    p1723790669: 0,\r\n    // Oversampling Factor: 2 selects 4x for live playback.\r\n    p1222066186: 2,\r\n    // Oversampling Factor (render): 2 selects 4x for offline renders.\r\n    p3117129981: 2\r\n});\r\n\r\n// The harder drive/saturation pair: same switches and oversampling, more\r\n// record-head level. `mix` stays a caller decision.\r\nfn driven(mix = 0.35) = tape(mix, 0.42, 0.48);\r\n","contrib/plugins/orbitcab.muz":"// OrbitCab amp/cabinet insert for the shared plugin pack. This module owns the\r\n// alias the pack expects and the alias-backed settings record; every tone\r\n// decision (preamp capture, power stage, cabinet IR) lives in the plugin's JUCE\r\n// state, so no engine parameters are pinned here beyond `state:`.\r\n//\r\n// Alias: `orbitcab` -> the installed OrbitCab CLAP in plugins.json (see\r\n// README.md). Upstream: OrbitCab 2.5.0, AGPL-3.0, class com.darwinscat.orbitcab.\r\n//\r\n// A device's `state:` path resolves against the .muz file that declares it, and a\r\n// function body evaluates in its defining module, so keep the plugin() call and\r\n// the path in your own module. A wrapper here would resolve against this\r\n// directory:\r\n//\r\n//     chain: [plugin(\"orbitcab\", amp.settings(\"assets/amp/sheriff-greenback.state\"))]\r\n//\r\n// Two independent mono instances panned after the plugin give the doubled-guitar\r\n// width; the engine parameter record below is what each instance needs.\r\nlet alias = \"orbitcab\";\r\n\r\nfn settings(state, overrides = {}) = merge({state: state}, overrides);\r\n","contrib/plugins/pianoteq.muz":"// Pianoteq 9 piano adapter for the shared plugin pack, a thin layer over the\r\n// builtin `piano(\"default\", {...})` convention. This module owns the alias the\r\n// builtin resolves and the alias-backed settings record. The instrument, its\r\n// license and the `.state` dump belong to the composer; this library ships\r\n// neither plugin binaries nor preset state.\r\n//\r\n// Alias: `default` -> the installed Pianoteq VST3 in plugins.json; `piano()`\r\n// uses it unless the source names another plugin. Upstream: Pianoteq 9,\r\n// proprietary (Modartt), sold per edition and instrument pack.\r\n//\r\n// A device's `state:` path resolves against the .muz file that declares it, and a\r\n// function body evaluates in its defining module, so keep the piano() call and\r\n// the path in your own module:\r\n//\r\n//     piano(\"default\", pianoteq.settings(\"assets/piano/bechstein-warm.state\"))\r\nlet alias = \"default\";\r\n\r\nfn settings(state, overrides = {}) = merge({state: state}, overrides);\r\n","contrib/plugins/surge-xt.muz":"// Surge XT instrument adapter for the shared plugin pack. This module owns the\r\n// alias the pack expects and the alias-backed settings record for one Surge XT\r\n// instance. Patches are `.state` files authored from an editable XML with\r\n// juce_state.py (`sub3` container); no engine parameters are pinned here.\r\n//\r\n// Alias: `surge` -> the installed Surge XT CLAP in plugins.json (see README.md).\r\n// Upstream: Surge XT 1.3.4, GPL-3.0, class org.surge-synth-team.surge-xt.\r\n//\r\n// A device's `state:` path resolves against the .muz file that declares it, and a\r\n// function body evaluates in its defining module, so keep the plugin() call and\r\n// the path in your own module:\r\n//\r\n//     let bass = plugin(\"surge\", surge.settings(\"assets/surge/piston-bass.state\"));\r\nlet alias = \"surge\";\r\n\r\nfn settings(state, overrides = {}) = merge({state: state}, overrides);\r\n","contrib/sonatina/CATALOG.md":"# Sonatina 4.0 patch catalog\r\n\r\nGenerated by `python3 contrib/sonatina/export-catalog.py` from the pinned upstream SFZs.\r\n\r\nAll **557 playable patches** are included. SFZ include fragments are implementation details, not additional instruments.\r\n\r\nPaths are relative to `assets/sso/Sonatina Symphonic Orchestra/`. Use the exact ID with the pack's state setup tool. MIDI key numbers avoid octave-name differences between hosts.\r\n\r\n\r\n## Brass - Notation\r\n\r\n| Patch ID | SFZ | Keyswitches (MIDI number: articulation) | Labeled / initialized CCs |\r\n| --- | --- | --- | --- |\r\n| `brass-notation-all-brass-ks` | All Brass KS.sfz | 12: Sustain; 14: Marcato; 16: Staccato | 1 Marcato Attack (default 0) |\r\n| `brass-notation-all-brass-marcato` | All Brass Marcato.sfz | — | 1 Marcato Attack (default 0) |\r\n| `brass-notation-all-brass-staccato` | All Brass Staccato.sfz | — | — |\r\n| `brass-notation-all-brass-sustain` | All Brass Sustain.sfz | — | — |\r\n| `brass-notation-bass-trombone-solo-ks` | Bass Trombone Solo KS.sfz | 84: Sustain (non-looped); 85: Sustain (looped); 86: Sustain (looped, decay); 87: Legato; 88: Marcato (non-looped); 89: Marcato (looped); 90: Marcato (looped, decay); 91: Staccato | 1 Marcato Attack (default 0) |\r\n| `brass-notation-bass-trombone-solo-legato` | Bass Trombone Solo Legato.sfz | — | — |\r\n| `brass-notation-bass-trombone-solo-marcato-looped` | Bass Trombone Solo Marcato (looped).sfz | — | 1 Marcato Attack (default 0) |\r\n| `brass-notation-bass-trombone-solo-marcato-looped-decay` | Bass Trombone Solo Marcato (looped, decay).sfz | — | 1 Marcato Attack (default 0) |\r\n| `brass-notation-bass-trombone-solo-marcato` | Bass Trombone Solo Marcato.sfz | — | 1 Marcato Attack 