: \"assets/gtx-mono/release-45-3-1.flac\", root: 45, keys: [43, 47]},\r\n    {path: \"assets/gtx-mono/release-45-4-1.flac\", root: 45, keys: [43, 47]},\r\n    {path: \"assets/gtx-mono/release-35-1-1.flac\", root: 35, keys: [34, 37]},\r\n    {path: \"assets/gtx-mono/release-35-2-1.flac\", root: 35, keys: [34, 37]},\r\n    {path: \"assets/gtx-mono/release-35-3-1.flac\", root: 35, keys: [34, 37]},\r\n    {path: \"assets/gtx-mono/release-35-4-1.flac\", root: 35, keys: [34, 37]},\r\n    {path: \"assets/gtx-mono/release-50-1-1.flac\", root: 50, keys: [48, 52]},\r\n    {path: \"assets/gtx-mono/release-50-2-1.flac\", root: 50, keys: [48, 52]},\r\n    {path: \"assets/gtx-mono/release-50-3-1.flac\", root: 50, keys: [48, 52]},\r\n    {path: \"assets/gtx-mono/release-50-4-1.flac\", root: 50, keys: [48, 52]},\r\n    {path: \"assets/gtx-mono/release-40-1-1.flac\", root: 40, keys: [38, 42]},\r\n    {path: \"assets/gtx-mono/release-40-2-1.flac\", root: 40, keys: [38, 42]},\r\n    {path: \"assets/gtx-mono/release-40-3-1.flac\", root: 40, keys: [38, 42]},\r\n    {path: \"assets/gtx-mono/release-40-4-1.flac\", root: 40, keys: [38, 42]},\r\n    {path: \"assets/gtx-mono/release-32-1-1.flac\", root: 32, keys: [30, 33]},\r\n    {path: \"assets/gtx-mono/release-32-2-1.flac\", root: 32, keys: [30, 33]},\r\n    {path: \"assets/gtx-mono/release-32-3-1.flac\", root: 32, keys: [30, 33]},\r\n    {path: \"assets/gtx-mono/release-32-4-1.flac\", root: 32, keys: [30, 33]},\r\n    {path: \"assets/gtx-mono/release-55-1-1.flac\", root: 55, keys: [53, 57]},\r\n    {path: \"assets/gtx-mono/release-55-2-1.flac\", root: 55, keys: [53, 57]},\r\n    {path: \"assets/gtx-mono/release-55-3-1.flac\", root: 55, keys: [53, 57]},\r\n    {path: \"assets/gtx-mono/release-55-4-1.flac\", root: 55, keys: [53, 57]},\r\n];\r\nlet release_1 = sample(release_1_zones, {\r\n    attack_ms: 0.3,\r\n    release_ms: 55,\r\n    velocity_track: 1,\r\n    gain_db: -28,\r\n    one_shot: true\r\n});\r\n\r\n// Builders. sample() resolves zone paths against the module that calls it, so a caller\r\n// building these zones in another file would look for them beside that file. Build here\r\n// instead, which keeps the pack's gitignored assets/ as the root:\r\n//     let rhythm = gtx.instrument(gtx.palm_down_1_zones, {gain_db: -4});\r\n// The preconfigured samples above already use the recorded articulation settings.\r\nfn instrument(zones, options = {}) = sample(zones, options);\r\n","contrib/unreal/metal-gtx/performance.muz":"// Kept separate from the generated articulation table.\r\nuse \"metal-gtx.muz\" as gtx;\r\nuse \"std/instrument\" as instrument;\r\nfn with_releases(\r\n    id,\r\n    pattern,\r\n    voice = gtx.sustain_down_0,\r\n    side = 0,\r\n    release_options = {},\r\n    timing = {}\r\n) {\r\n    assert(side == 0 || side == 1, \"release side must be 0 or 1\");\r\n    let zones = if side == 0 { gtx.release_0_zones } else { gtx.release_1_zones };\r\n    [\r\n        track(id, pattern, voice),\r\n        track(\r\n            id + \"-release\",\r\n            instrument.releases(pattern, 100ms, timing),\r\n            gtx.instrument(\r\n                zones,\r\n                merge({\r\n                    one_shot: true,\r\n                    attack_ms: 0.3,\r\n                    release_ms: 55,\r\n                    velocity_track: 1,\r\n                    gain_db: -28\r\n                }, release_options)\r\n            )\r\n        )\r\n    ]\r\n};\r\n","contrib/unreal/metal-gtx/sfz.muz":"// Original SFZ programs. Install sfz-complete assets before use.\r\n// Catalog IDs and paths are recorded in sfz-catalog.json.\r\nfn program(path, options = {}) {\r\n    let linked = merge({embed_assets: false}, options);\r\n    assert(!linked.embed_assets, \"Unreal publisher recordings cannot be embedded for redistribution; use linked assets\");\r\n    sfz(path, linked)\r\n}\r\n\r\nfn program_01_metal_gtx_full(options = {}) = program(\"assets/metal-gtx/UI_METAL-GTX/Programs/01-METAL-GTX Full.sfz\", merge({sample_budget_frames: 479199232}, options));\r\nfn program_02_metal_gtx_lite(options = {}) = program(\"assets/metal-gtx/UI_METAL-GTX/Programs/02-METAL-GTX Lite.sfz\", merge({sample_budget_frames: 149946368}, options));\r\nfn program_03_metal_gtx_xtracking(options = {}) = program(\"assets/metal-gtx/UI_METAL-GTX/Programs/03-METAL-GTX XTracking.sfz\", merge({sample_budget_frames: 479199232}, options));\r\nfn program_04_guitar_chord_central(options = {}) = program(\"assets/metal-gtx/UI_METAL-GTX/Programs/04-Guitar Chord Central.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_05_simple_arpeggio(options = {}) = program(\"assets/metal-gtx/UI_METAL-GTX/Programs/05-Simple Arpeggio.sfz\", merge({sample_budget_frames: 67108864}, options));\r\n","contrib/unreal/standard-guitar/README.md":"# Unreal Instruments Standard Guitar\r\n\r\nNative sustain and mute maps for Standard Guitar. The publisher permits commercial\r\nmusic but prohibits redistribution of the library. The installer restores the\r\noriginal recordings under ignored `assets/`; this pack ships no audio.\r\n\r\n[All packs](../../../contrib/README.md) · [Instrument guide](../../../docs/instruments.md)\r\n\r\nRun shell commands from the `muz-core` checkout unless stated otherwise.\r\nFor the installed CLI, run these utilities from the installed contrib copy\r\ncreated by `./install.sh`; see the [pack setup guide](../../../contrib/README.md#install-and-import).\r\n\r\n## Contents\r\n\r\n- [Install](#install)\r\n- [Use an instrument](#use-an-instrument)\r\n- [Mapping and options](#mapping-and-options)\r\n- [Asset layout](#asset-layout)\r\n- [Upstream and license](#upstream-and-license)\r\n- [Pins and manual installation](#pins-and-manual-installation)\r\n\r\n## Install\r\n\r\nRequires Python 3.11 or newer (standard library only) and the `unrar` command on\r\nPATH.\r\n\r\n```sh\r\npython3 contrib/unreal/standard-guitar/install.py\r\n```\r\n\r\nThe installer:\r\n\r\n1. verifies all 400 mapped recordings and exits immediately when they are\r\n   already intact — re-running is cheap and idempotent;\r\n2. downloads the publisher archive to `assets/.downloads/standard-guitar.rar`,\r\n   keeps it as a cache, and checks it against the pinned SHA-256;\r\n3. rejects archive members with absolute or `..` paths before extraction;\r\n4. extracts into `assets/standard-guitar/` with `unrar x -idq -o- -p-`;\r\n5. verifies every mapped recording by size and SHA-256 and reports the total.\r\n\r\nA file that differs from its pin aborts the run with the offending path: the\r\nsupplied recordings are never overwritten, and neither is a cached archive that\r\nfails the pin. Nothing in the library is renamed, re-encoded or altered.\r\n\r\n## Use an instrument\r\n\r\nThis song uses the sustain articulation and follows written note releases:\r\n\r\n```muz\r\nuse \"contrib/unreal/standard-guitar/standard-guitar\" as guitar;\r\nsong({tracks: [track(\"guitar\", phrase(\"E2:q G2:q B2:h\"),\r\n    guitar.voice(\"Sus_Down\", {one_shot: false, release_ms: 95}))]})\r\n```\r\n\r\n`voice(\"Mute_Down\", options)` selects the mute map. The `instrument` export is a\r\nready-made kit with `sustain` and `mute` voices. Use the pack's builder for custom\r\noptions so sample paths resolve inside the pack.\r\n\r\n## Mapping and options\r\n\r\n- 25 chromatic roots, E2–E4 (MIDI 40–64), eight recorded takes per root and\r\n  articulation: 200 `sustain` zones and 200 `mute` zones.\r\n- Outer key bounds 35–39 and 65 keep nearest-root coverage from the preceding\r\n  map; the played roots and takes are unchanged.\r\n- Zones are emitted root by root, take 1–8 in recording order. The sampler\r\n  chooses round robins by index, so this order is musically significant and must\r\n  not be sorted or reordered.\r\n- Sample paths use the template\r\n  `assets/standard-guitar/UI_Standard_Guitar/Samples/<articulation>/<root>_<articulation><take>.flac`,\r\n  resolved relative to `standard-guitar.muz`.\r\n- `instrument` is the ready-made `kit()` with the pack's level settings.\r\n- `voice(art, options)` builds a voice from the same zones; use it instead of\r\n  calling `sample()` on these zones yourself, because `sample()` stamps the\r\n  directory of the module that evaluates the call as the asset root.\r\n\r\nThe ready-made kit sets `one_shot: false` for both voices.\r\nWritten durations and gates trigger their 95/55 ms releases, so notes stop through\r\nrests.\r\nFor uninterrupted recordings, build `voice(\"Sus_Down\", {one_shot: true})` explicitly.\r\n\r\n## Asset layout\r\n\r\n```\r\ncontrib/unreal/standard-guitar/\r\n  standard-guitar.muz   this pack's map\r\n  install.py            restore and verify the recordings\r\n  manifest.json         archive and recording pins\r\n  README.md             this file\r\n  assets/               gitignored, produced by install.py\r\n    .downloads/standard-guitar.rar\r\n    standard-guitar/UI_Standard_Guitar/Samples/Sus_Down/*.flac\r\n    standard-guitar/UI_Standard_Guitar/Samples/Mute_Down/*.flac\r\n```\r\n\r\nThe archive holds the whole publisher library; this pack maps only the two\r\n`*_Down` articulations.\r\n\r\n## Upstream and license\r\n\r\n| | |\r\n| --- | --- |\r\n| Library | Unreal Instruments Standard Guitar |\r\n| Publisher page | <https://unreal-instruments.wixsite.com/unreal-instruments/standard-guitar> |\r\n| License terms | <https://unreal-instruments.wixsite.com/unreal-instruments/about> |\r\n| Download page | <https://drive.google.com/uc?export=download&id=1uoV7icZV1_IjiOGKM7Wm5_K5UkF41Fm3> |\r\n| Archive | `standard-guitar.rar`, 750,502,921 bytes (716 MiB) |\r\n| Archive SHA-256 | `0777b8cbbfe2fe79e843fa6c2c24ab300c2d5a538d46f4d970f057979f87fee0` |\r\n| Extracted library | 761,487,033 bytes (726 MiB) under `assets/standard-guitar/` |\r\n| Mapped recordings | 400 FLAC files, 115,800,959 bytes (110 MiB) |\r\n\r\nLicense summary: commercial music made with the library is permitted and no\r\ncredit is required; unauthorized alteration and redistribution of the library's\r\ndata are prohibited. Because redistribution is prohibited, the recordings stay\r\nout of git — `install.py` fetches them from the publisher and `**/assets` is\r\nignored by the repository. `manifest.json` carries the pins.\r\n\r\n## Pins and manual installation\r\n\r\n`manifest.json` pins the archive URL, byte count and SHA-256, and the path, byte\r\ncount and SHA-256 of each of the 400 mapped recordings, all copied from the\r\npublisher archive as extracted. The installer re-verifies those pins on every\r\nrun, so a damaged or replaced file is reported rather than used.\r\n\r\nIf the automatic download is blocked, fetch the archive from the publisher page\r\nand place it at `assets/.downloads/standard-guitar.rar`, then re-run the\r\ninstaller. If `unrar` cannot be installed, extract the archive yourself with any\r\nRAR tool into `assets/standard-guitar/` (the archive's `standard-guitar/`\r\ndirectory must end up there) and re-run the installer to verify the result.\r\nWhen the extracted library already exists elsewhere on this machine, moving its\r\n`standard-guitar/` directory to `assets/standard-guitar/` avoids the 716 MiB\r\ndownload.\r\n\r\n## Original SFZ programs\r\n\r\nSee [complete SFZ assets and catalogs](../../SFZ.md) for the `sfz-complete`\r\ninstallation profile. The existing native presets remain available.\r\n","contrib/unreal/standard-guitar/sfz.muz":"// Original SFZ programs. Install sfz-complete assets before use.\r\n// Catalog IDs and paths are recorded in sfz-catalog.json.\r\nfn program(path, options = {}) {\r\n    let linked = merge({embed_assets: false}, options);\r\n    assert(!linked.embed_assets, \"Unreal publisher recordings cannot be embedded for redistribution; use linked assets\");\r\n    sfz(path, linked)\r\n}\r\n\r\nfn program_01_standard_guitar_ksop(options = {}) = program(\"assets/standard-guitar/UI_Standard_Guitar/Programs/01-Standard Guitar KSOP.sfz\", merge({sample_budget_frames: 196083712}, options));\r\nfn program_02_standard_guitar_ksop_xtracking(options = {}) = program(\"assets/standard-guitar/UI_Standard_Guitar/Programs/02-Standard Guitar KSOP XTracking.sfz\", merge({sample_budget_frames: 196083712}, options));\r\nfn program_03_standard_guitar_vsop(options = {}) = program(\"assets/standard-guitar/UI_Standard_Guitar/Programs/03-Standard Guitar VSOP.sfz\", merge({sample_budget_frames: 196083712}, options));\r\nfn program_04_standard_guitar_vsop_xtracking(options = {}) = program(\"assets/standard-guitar/UI_Standard_Guitar/Programs/04-Standard Guitar VSOP XTracking.sfz\", merge({sample_budget_frames: 196083712}, options));\r\nfn program_05_guitar_chord_central(options = {}) = program(\"assets/standard-guitar/UI_Standard_Guitar/Programs/05-Guitar Chord Central.sfz\", merge({sample_budget_frames: 67108864}, options));\r\nfn program_06_simple_arpeggio(options = {}) = program(\"assets/standard-guitar/UI_Standard_Guitar/Programs/06-Simple Arpeggio.sfz\", merge({sample_budget_frames: 67108864}, options));\r\n","contrib/unreal/standard-guitar/standard-guitar.muz":"// Unreal Instruments Standard Guitar: 25 chromatic roots E2-E4, eight recorded\r\n// takes per root, `sustain`/`mute` articulations. Zone order is musically\r\n// significant: the sampler picks round robins by index, so takes are emitted in\r\n// recording order and must not be reordered.\r\n//\r\n// Only the map ships here. The publisher permits commercial music without\r\n// credit but prohibits redistribution, so the recordings stay out of git;\r\n// `install.py` restores them from the publisher archive into\r\n// `assets/standard-guitar/` relative to this file.\r\n//\r\n// Sustain and mute honor written note-offs; their release envelopes finish the tail.\r\n// Use voice(art, {one_shot: true}) explicitly for uninterrupted recordings.\r\n//\r\n// Original Standard Guitar FLAC recordings remain unmodified in assets/.\r\n// Chromatic E2–E4 coverage, eight recorded takes per root and articulation.\r\n// Outer key bounds retain the preceding map's range; played roots/takes stay unchanged.\r\nlet roots = [\r\n    [40, \"e2\", 35, 40],\r\n    [41, \"f2\", 41, 41],\r\n    [42, \"f#2\", 42, 42],\r\n    [43, \"g2\", 43, 43],\r\n    [44, \"g#2\", 44, 44],\r\n    [45, \"a2\", 45, 45],\r\n    [46, \"a#2\", 46, 46],\r\n    [47, \"b2\", 47, 47],\r\n    [48, \"c3\", 48, 48],\r\n    [49, \"c#3\", 49, 49],\r\n    [50, \"d3\", 50, 50],\r\n    [51, \"d#3\", 51, 51],\r\n    [52, \"e3\", 52, 52],\r\n    [53, \"f3\", 53, 53],\r\n    [54, \"f#3\", 54, 54],\r\n    [55, \"g3\", 55, 55],\r\n    [56, \"g#3\", 56, 56],\r\n    [57, \"a3\", 57, 57],\r\n    [58, \"a#3\", 58, 58],\r\n    [59, \"b3\", 59, 59],\r\n    [60, \"c4\", 60, 60],\r\n    [61, \"c#4\", 61, 61],\r\n    [62, \"d4\", 62, 62],\r\n    [63, \"d#4\", 63, 63],\r\n    [64, \"e4\", 64, 65]\r\n];\r\nfn zones(art) = fold(\r\n    roots,\r\n    [],\r\n    fn(a, r) =>\r\n        a\r\n        + map(range(8), fn(i) => {\r\n            path: format(\"assets/standard-guitar/UI_Standard_Guitar/Samples/{}/{}_{}{}.flac\", [\r\n                art,\r\n                r[1],\r\n                art,\r\n                i + 1\r\n            ]),\r\n            root: r[0],\r\n            keys: [r[2], r[3]]\r\n        })\r\n);\r\n// Callers that need a voice with different options must build it here rather\r\n// than calling `sample()` on these zones themselves: `sample()` stamps the\r\n// directory of the module that evaluates the call, so a caller-side call would\r\n// resolve the recordings next to the caller instead of this pack.\r\n// `voice(\"Sus_Down\", {one_shot: false})` gives the mapped sustain with written\r\n// note releases; options are passed through unchanged.\r\nfn voice(art, options = {}) = sample(zones(art), options);\r\nlet instrument = kit(\"standard-guitar\", {\r\n    sustain: sample(zones(\"Sus_Down\"), {\r\n        one_shot: false,\r\n        attack_ms: 1.5,\r\n        release_ms: 95,\r\n        velocity_track: 0.6,\r\n        gain_db: 2\r\n    }),\r\n    mute: sample(zones(\"Mute_Down\"), {\r\n        one_shot: false,\r\n        attack_ms: 1,\r\n        release_ms: 55,\r\n        velocity_track: 0.6,\r\n        gain_db: 8\r\n    })\r\n});\r\n","contrib/virtuosity-drums/README.md":"# Virtuosity Drums v0.925\r\n\r\nNative drum maps for Virtuosity Drums v0.925 by\r\n[Versilian Studios](https://versilian-studios.com/virtuosity-drums/) with\r\nKaroryfer, performed by Austin McMahon. The recordings are CC0 and play directly,\r\nwithout an SFZ player or conversion. The Python 3 installer downloads the\r\npublisher's roughly 1.2 GB ZIP (1,227,151,376 bytes) into ignored `assets/`.\r\n\r\n[All packs](../../contrib/README.md) · [Instrument guide](../../docs/instruments.md)\r\n\r\nRun shell commands from the `muz-core` checkout unless stated otherwise.\r\nFor the installed CLI, run these utilities from the installed contrib copy\r\ncreated by `./install.sh`; see the [pack setup guide](../../contrib/README.md#install-and-import).\r\n\r\n## Contents\r\n\r\n- [Install](#install)\r\n- [Use the kit](#use-the-kit)\r\n- [Mappings and mix options](#mappings-and-mix-options)\r\n- [Shared insert automation](#shared-insert-automation)\r\n- [Asset layout](#asset-layout)\r\n- [Upstream and license](#upstream-and-license)\r\n- [Pins and manual installation](#pins-and-manual-installation)\r\n\r\n## Install\r\n\r\n```sh\r\npython3 contrib/virtuosity-drums/install.py\r\n```\r\n\r\nThe installer downloads the publisher's ZIP into `assets/`, checks its pinned\r\nsize and sha256, and extracts `Samples/`, `Programs/`, `LICENSE` and\r\n`notes.txt` into `assets/`. It is idempotent: a complete install is verified\r\nand left untouched, missing files are filled in, files that already match are\r\nnot rewritten, and anything that differs from the pinned release stops the run\r\ninstead of being overwritten.\r\n\r\n```sh\r\npython3 contrib/virtuosity-drums/install.py --check     # verify only, no download\r\npython3 contrib/virtuosity-drums/install.py --source /path/to/Virtuosity_Drums_v0.925.zip\r\n```\r\n\r\n`--source` verifies an already-downloaded copy and extracts from it in place\r\nwithout copying another 1.2 GB into `assets/`.\r\n\r\n## Use the kit\r\n\r\nAfter installing the recordings, save this as a song in your project:\r\n\r\n```muz\r\nuse \"contrib/virtuosity-drums/kit\" as vd;\r\nsong({\r\n    tracks: [track(\"drums\", drums({kick: \"X...\", snare: \"..X.\", hat: \"x.x.\"}), vd.acoustic)],\r\n    buses: [bus(\"room\", [fx(\"reverb\", {mix: 1})]), bus(\"crushed\", [])]\r\n})\r\n```\r\n\r\nThe acoustic kit sends to `room` and `crushed`; declare both buses even if you\r\nstart with an empty chain. Choose their processing to suit your song.\r\n\r\n## Mappings and mix options\r\n\r\nZone paths are written relative to `kit.muz`, so\r\n`assets/Samples/{mic}/{drum}/{mic}_{drum}_{art}_vl{n}[_rr{j}].flac` resolves\r\ninside this pack. Velocity boundaries follow the publisher's SFZ maps; zone\r\norder is significant because samplers pick round robins by index.\r\n\r\n| export | what it is |\r\n| --- | --- |\r\n| `zones(mic, drum, art, layers, rr)` | zone list for one articulation, velocity split from the SFZ map |\r\n| `hit(mic, drum, art, layers, key, rr, gain)` | one-shot sample over those zones |\r\n| `acoustic` | close kit: kick mic, snare mic and mid mics with per-voice processing, chokes on `hat`/`open_hat` |\r\n| `room` | shells on the room mic, kick and rimshot trimmed back |\r\n| `room_light` | the same room recordings with shallower trims, un-gained tom bodies and no rim voice |\r\n| `overheads` | cymbals only, from the overhead pair |\r\n| `full_overheads` | the overhead pair carrying every voice, shells included |\r\n| `closed_hat`, `closed_zones` | closed hat with the divergent fourth layer replaced by layer three plus a small accent |\r\n| `center_snare`, `cymbal`, `tom`, `path` | helpers selecting four-layer snares, overhead cymbal round robins and four-layer toms |\r\n| `snare_room`, `kick_attack`, `metal` | the snares on the room mic, the mid-mic kick beater attack, and a pitched-up crossstick voice |\r\n\r\nPer-voice trims, pans, chokes and effect chains are part of each table's mix\r\npolicy; a caller that wants different processing merges over these tables\r\nrather than editing them.\r\n\r\n## Shared insert automation\r\n\r\nLogical kit-track insert automation broadcasts to each played voice, including\r\nvoices with their own existing EQ or compression chains:\r\n\r\n```muz\r\nuse \"contrib/virtuosity-drums/kit\" as vd;\r\nsong({\r\n    tracks: [track(\"drums\", drums({kick: \"X...\", snare: \"..X.\", hat: \"x.x.\"}), vd.acoustic, {\r\n        chain: [fx(\"lowpass\", {id: \"tone\", cutoff_hz: 16000})]\r\n    })],\r\n    buses: [bus(\"room\", [fx(\"reverb\", {mix: 1})]), bus(\"crushed\", [])],\r\n    automation: [automation(\"drums.tone.cutoff_hz\", curve([[0b, 800], [4b, 16000]]))]\r\n})\r\n```\r\n\r\nEach voice retains its own filter instance, also affecting its sends; this is not a\r\nshared bus filter. The room/overhead kits remain separate tracks and need their own\r\nlanes when they should follow the same motion. The closed-hat top-layer substitution\r\nremains intentional: the fourth layer has a splashier sound than the chosen alternative.\r\n\r\n## Asset layout\r\n\r\n```\r\ncontrib/virtuosity-drums/\r\n  README.md\r\n  install.py\r\n  manifest.json\r\n  kit.muz\r\n  assets/                                  # git-ignored, created by install.py\r\n    virtuosity.zip                         # verified archive, outside the extracted tree\r\n    Samples/{mic}/{drum}/{mic}_{drum}_{art}_vl{n}[_rr{j}].flac\r\n    Programs/                              # publisher's SFZ programs and keymaps\r\n    LICENSE                                # CC0 1.0\r\n    notes.txt                              # publisher's version notes\r\n```\r\n\r\n`assets/Samples/` holds one folder per microphone position. The module uses\r\n`kickmic`, `snaremic`, `mid`, `oh` and `room`; `lofi` and `perc` are installed\r\ntoo. Each drum folder holds `kick`, `snare`, `snareoff`, `hh`, `crash`, `ride`,\r\n`flatride`, `htom` and `ltom`, with the velocity layers and round robins the\r\nzones above expect.\r\n\r\n## Upstream and license\r\n\r\nThe recordings use [CC0 1.0 Universal](https://github.com/sfzinstruments/virtuosity_drums/blob/master/LICENSE),\r\na public-domain dedication allowing redistribution. This repository still stores\r\nonly mappings and installers, with audio under ignored `assets/`.\r\n\r\nThe ZIP also contains `GUI/`, `Virtuosity Drums.bank.xml`,\r\n`VirtuosityDrums_Keymap.pdf` and `VirtuosityDrumsManual.pdf` — the sample\r\nplayer's own interface definitions and its documentation. The installer\r\ndeliberately leaves those in the archive; they are not needed to render this\r\nmapping. The library's own `notes.txt` (version notes through Beta 0.925) and\r\nits CC0 `LICENSE` are extracted next to the samples.\r\n\r\n## Pins and manual installation\r\n\r\n| archive member | files | bytes | installed at |\r\n| --- | ---: | ---: | --- |\r\n| `Samples/` | 4858 | 1468997687 | `assets/Samples/` |\r\n| `Programs/` | 419 | 663828 | `assets/Programs/` |\r\n| `LICENSE` | 1 | 7048 | `assets/LICENSE` |\r\n| `notes.txt` | 1 | 5997 | `assets/notes.txt` |\r\n| All archive members (uncompressed) | 5357 | 1488795308 | includes content left in the ZIP |\r\n| Compressed ZIP | 1 | 1227151376 | `assets/virtuosity.zip` |\r\n\r\n`manifest.json` carries the same pins: URL, archive bytes, sha256 and the\r\nextraction layout. The verifier counts files and adds bytes per member, so a\r\ntruncated or partly deleted install is reported rather than silently reused.\r\n\r\n### Manual installation\r\n\r\n1. Download <https://versilian-studios.com/Distro/Virtuosity_Drums_v0.925.zip>.\r\n2. Confirm size `1227151376` bytes and sha256\r\n   `c6c5d0fe11a394e94be3146a950c3377ec102cb57d189d5a23cec26183d1963a`.\r\n3. Place the archive at `contrib/virtuosity-drums/assets/virtuosity.zip`.\r\n4. Extract `Samples/`, `Programs/`, `LICENSE` and `notes.txt` from its root\r\n   into `contrib/virtuosity-drums/assets/`, then run the installer with\r\n   `--check`.\r\n\r\n## Original SFZ programs\r\n\r\nSee [complete SFZ assets and catalogs](../SFZ.md) for the `sfz-complete`\r\ninstallation profile. The existing native presets remain available.\r\n","contrib/virtuosity-drums/kit.muz":"// Native Virtuosity Drums v0.925 mapping (CC0; Versilian Studios with\r\n// Karoryfer, performed by Austin McMahon). Install the recordings with\r\n// `python3 contrib/virtuosity-drums/install.py`; no SFZ player or conversion\r\n// utility is involved. Every zone path resolves relative to this file as\r\n// assets/Samples/{mic}/{drum}/{mic}_{drum}_{art}_vl{n}[_rr{j}].flac\r\n// Velocity boundaries follow the supplied SFZ maps; these are native muz zones.\r\n// This module owns the recordings' shared mapping: `zones`/`hit`, the close,\r\n// room and overhead voice tables, and the alternate selections below. Further\r\n// processing, mixing and non-Virtuosity material belong to the caller.\r\nfn zones(mic, drum, art, layers, rr = 1) = range(layers)\r\n    .map(\r\n        fn(i) => range(rr).map(fn(j) => {\r\n            path: format(\"assets/Samples/{}/{}/{}_{}_{}_vl{}{}.flac\", [\r\n                mic,\r\n                drum,\r\n                mic,\r\n                drum,\r\n                art,\r\n                i + 1,\r\n                if rr == 1 { \"\" } else { format(\"_rr{}\", [j + 1]) }\r\n            ]),\r\n            velocity: [\r\n                if i == 0 { 0 } else { (floor(i * 127 / layers) + 0.5) / 127 },\r\n                if i + 1 == layers { 1 } else { (floor((i + 1) * 127 / layers) + 0.5) / 127 }\r\n            ]\r\n        })\r\n    )\r\n    .fold([], fn(a, b) => a + b);\r\nfn hit(mic, drum, art, layers, key, rr = 1, gain = 0) = sample(zones(mic, drum, art, layers, rr), {\r\n    root: key,\r\n    one_shot: true,\r\n    attack_ms: 0.3,\r\n    release_ms: 40,\r\n    velocity_track: 0.2,\r\n    gain_db: gain\r\n});\r\n// Build any other selection of these recordings: a function body evaluates in\r\n// its defining module, so calling this through the pack keeps the pack's asset\r\n// root. A piece that called `sample()` itself would resolve `assets/...` against\r\n// the piece's directory instead.\r\nfn instrument(zones, options = {}) = sample(zones, options);\r\n// The fourth closed-hat layer jumps roughly 13 dB and becomes much splashier.\r\n// Keep the lower three layers and their RR takes; use layer three with a small\r\n// accent gain for the highest velocity range instead of those four outliers.\r\n// Substitute this for `acoustic.hat` where the top strike should keep the\r\n// quieter articulation.\r\nlet closed_zones = zones(\"mid\", \"hh\", \"closed\", 4, 4);\r\nlet closed_hat = sample(\r\n    map(range(len(closed_zones)), fn(i) => if i >= 12 {\r\n        merge(closed_zones[i], {path: closed_zones[i - 4].path, gain_db: 2.5})\r\n    } else {\r\n        closed_zones[i]\r\n    }),\r\n    {root: 42, one_shot: true, attack_ms: 0.3, release_ms: 40, velocity_track: 0.2, gain_db: 15}\r\n);\r\nlet acoustic = kit(\"virtuosity\", {\r\n    kick: {\r\n        instrument: hit(\"kickmic\", \"kick\", \"snon\", 4, 36, 4, -2),\r\n        chain: [\r\n            fx(\"highpass\", {cutoff_hz: 32}),\r\n            fx(\"compressor\", {threshold_db: -12, ratio: 4, attack_ms: 2, release_ms: 85})\r\n        ]\r\n    },\r\n    snare: {\r\n        instrument: hit(\"snaremic\", \"snare\", \"center\", 36, 38, 1, -2),\r\n        gain: 3,\r\n        chain: [\r\n            fx(\"highpass\", {cutoff_hz: 115}),\r\n            fx(\"eq\", {frequency_hz: 190, gain_db: 3, q: 0.8}),\r\n            fx(\"eq\", {frequency_hz: 850, gain_db: -2, q: 1.2}),\r\n            fx(\"compressor\", {\r\n                threshold_db: -16,\r\n                ratio: 3,\r\n                attack_ms: 4,\r\n                release_ms: 100,\r\n                makeup_db: 3\r\n            })\r\n        ],\r\n        sends: {room: -12, crushed: -19}\r\n    },\r\n    rim: hit(\"mid\", \"snare\", \"crossstick\", 16, 37, 1, 2),\r\n    rimshot: {\r\n        instrument: hit(\"snaremic\", \"snare\", \"rimshot\", 12, 38, 1, -4),\r\n        gain: 1,\r\n        chain: [\r\n            fx(\"highpass\", {cutoff_hz: 115}),\r\n            fx(\"eq\", {frequency_hz: 190, gain_db: 4, q: 0.8}),\r\n            fx(\"eq\", {frequency_hz: 850, gain_db: -2, q: 1.2}),\r\n            fx(\"compressor\", {threshold_db: -14, ratio: 3, attack_ms: 4, release_ms: 100})\r\n        ],\r\n        sends: {room: -11, crushed: -17}\r\n    },\r\n    hat: {\r\n        instrument: hit(\"mid\", \"hh\", \"closed\", 4, 42, 4, 3),\r\n        pan: -0.25,\r\n        chain: [\r\n            fx(\"highpass\", {cutoff_hz: 1800}),\r\n            fx(\"eq\", {frequency_hz: 6500, gain_db: -2, q: 0.8}),\r\n            fx(\"lowpass\", {cutoff_hz: 9500})\r\n        ]\r\n    },\r\n    // The written openings use half-open strikes: body and motion without a full wash.\r\n    open_hat: {\r\n        instrument: hit(\"mid\", \"hh\", \"half\", 4, 46, 4, 3),\r\n        pan: -0.25,\r\n        chain: [\r\n            fx(\"highpass\", {cutoff_hz: 1400}),\r\n            fx(\"eq\", {frequency_hz: 5000, gain_db: -3.5, q: 0.65}),\r\n            fx(\"lowpass\", {cutoff_hz: 10000})\r\n        ]\r\n    },\r\n    crash: {\r\n        instrument: hit(\"mid\", \"crash\", \"crash\", 3, 49, 4, 3),\r\n        pan: -0.38,\r\n        chain: [\r\n            fx(\"highpass\", {cutoff_hz: 750}),\r\n            fx(\"eq\", {frequency_hz: 4700, gain_db: -2, q: 0.8}),\r\n            fx(\"lowpass\", {cutoff_hz: 11000})\r\n        ]\r\n    },\r\n    ride: {\r\n        instrument: hit(\"mid\", \"ride\", \"ride\", 3, 51, 4, 2),\r\n        pan: 0.32,\r\n        chain: [fx(\"highpass\", {cutoff_hz: 1600})]\r\n    },\r\n    tom_high: {\r\n        instrument: hit(\"mid\", \"htom\", \"center\", 16, 50, 1, 2),\r\n        pan: -0.22,\r\n        sends: {room: -15}\r\n    },\r\n    tom_low: {\r\n        instrument: hit(\"mid\", \"ltom\", \"center\", 16, 43, 1, 2),\r\n        pan: 0.26,\r\n        sends: {room: -15}\r\n    },\r\n    chokes: [[\"hat\", \"open_hat\", \"pedal_hat\"]]\r\n});\r\n// Shells use the original room microphone; cymbals use the overhead pair.\r\n// The close/mid tracks above remain the direct component of the same performance.\r\nlet room = kit(\"virtuosity-room\", {\r\n    kick: hit(\"room\", \"kick\", \"snon\", 4, 36, 4, -7),\r\n    snare: hit(\"room\", \"snare\", \"center\", 36, 38, 1, 0),\r\n    rimshot: hit(\"room\", \"snare\", \"rimshot\", 12, 38, 1, -3),\r\n    rim: hit(\"room\", \"snare\", \"crossstick\", 16, 37, 1, 0),\r\n    tom_high: hit(\"room\", \"htom\", \"center\", 16, 50, 1, -1),\r\n    tom_low: hit(\"room\", \"ltom\", \"center\", 16, 43, 1, -1)\r\n});\r\n// The room and close files are the same recorded strikes, not independent takes.\r\n// A lighter room balance: shallower kick and rimshot trims, un-gained tom\r\n// bodies and no rim voice.\r\nlet room_light = kit(\"virtuosity-room-light\", {\r\n    kick: hit(\"room\", \"kick\", \"snon\", 4, 36, 4, -3),\r\n    snare: hit(\"room\", \"snare\", \"center\", 36, 38, 1, 0),\r\n    rimshot: hit(\"room\", \"snare\", \"rimshot\", 12, 38, 1, -2),\r\n    tom_high: {instrument: hit(\"room\", \"htom\", \"center\", 16, 50), pan: -0.2},\r\n    tom_low: {instrument: hit(\"room\", \"ltom\", \"center\", 16, 43), pan: 0.2}\r\n});\r\nlet overheads = kit(\"virtuosity-overheads\", {\r\n    hat: hit(\"oh\", \"hh\", \"closed\", 4, 42, 4, -4),\r\n    open_hat: hit(\"oh\", \"hh\", \"half\", 4, 46, 4, -4),\r\n    crash: hit(\"oh\", \"crash\", \"crash\", 3, 49, 4, -5),\r\n    ride: hit(\"oh\", \"ride\", \"ride\", 3, 51, 4, -4),\r\n    chokes: [[\"hat\", \"open_hat\", \"pedal_hat\"]]\r\n});\r\n// The same overhead pair carrying every voice: the cymbal table above plus the\r\n// shells, for balancing a whole kit from the overheads.\r\nlet full_overheads = kit(\"virtuosity-full-overheads\", {\r\n    kick: hit(\"oh\", \"kick\", \"snon\", 4, 36, 4, -7),\r\n    snare: hit(\"oh\", \"snare\", \"center\", 36, 38, 1, 0),\r\n    rimshot: hit(\"oh\", \"snare\", \"rimshot\", 12, 38, 1, -2),\r\n    rim: hit(\"oh\", \"snare\", \"crossstick\", 16, 37, 1, 0),\r\n    tom_high: {instrument: hit(\"oh\", \"htom\", \"center\", 16, 50, 1, -2), pan: -0.2},\r\n    tom_low: {instrument: hit(\"oh\", \"ltom\", \"center\", 16, 43, 1, -2), pan: 0.22},\r\n    hat: hit(\"oh\", \"hh\", \"closed\", 4, 42, 4, -4),\r\n    open_hat: hit(\"oh\", \"hh\", \"half\", 4, 46, 4, -4),\r\n    crash: hit(\"oh\", \"crash\", \"crash\", 3, 49, 4, -5),\r\n    ride: hit(\"oh\", \"ride\", \"ride\", 3, 51, 4, -4),\r\n    chokes: [[\"hat\", \"open_hat\", \"pedal_hat\"]]\r\n});\r\n// Alternate selections from the same sessions: four-layer center snares, hi-hat\r\n// and crash round robins from the overheads, four-layer toms, and a pitched-up\r\n// crossstick voice.\r\nfn path(mic, drum, articulation, layer, rr = \"\") = format(\r\n    \"assets/Samples/{}/{}/{}_{}_{}_vl{}{}.flac\",\r\n    [mic, drum, mic, drum, articulation, layer, rr]\r\n);\r\nfn center_snare(mic, gain = 0) = sample(\r\n    map([25, 26, 27, 28], fn(i) => {path: path(mic, \"snare\", \"center\", i), root: 39}),\r\n    {one_shot: true, velocity_track: 0.8, gain_db: gain, attack_ms: 0.8}\r\n);\r\nfn cymbal(art, root, gain) = sample(\r\n    map(range(4), fn(i) => {path: path(\"oh\", \"hh\", art, 3, format(\"_rr{}\", [i + 1])), root: root}),\r\n    {one_shot: true, velocity_track: 0.85, gain_db: gain, attack_ms: 0.2}\r\n);\r\nfn tom(drum, root, gain) = sample(\r\n    map([13, 14, 15, 16], fn(i) => {path: path(\"mid\", drum, \"center\", i), root: root}),\r\n    {one_shot: true, velocity_track: 0.8, gain_db: gain}\r\n);\r\nlet snare_room = center_snare(\"room\", 1);\r\nlet kick_attack = sample(\r\n    map(range(4), fn(i) => {\r\n        path: path(\"mid\", \"kick\", \"snon\", 4, format(\"_rr{}\", [i + 1])),\r\n        root: 36\r\n    }),\r\n    {one_shot: true, velocity_track: 0.8, gain_db: 8}\r\n);\r\n// Four crossstick takes pitched well above the kit's own crossstick voice.\r\nlet metal = sample(\r\n    map([12, 14, 15, 16], fn(i) => {path: path(\"mid\", \"snare\", \"crossstick\", i), root: 62}),\r\n    {one_shot: true, velocity_track: 0.7, gain_db: 0}\r\n);\r\n","contrib/virtuosity-drums/sfz.muz":"// Original SFZ programs. Install sfz-complete assets before use.\r\n// Catalog IDs and paths are recorded in sfz-catalog.json.\r\nfn program(path, options = {}) = sfz(path, options);\r\n\r\nfn program_01_basic_kit(options = {}) = sfz(\"assets/Programs/01-basic-kit.sfz\", merge({sample_budget_frames: 230686720}, options));\r\nfn program_02_full_kit(options = {}) = sfz(\"assets/Programs/02-full-kit.sfz\", merge({sample_budget_frames: 644874240}, options));\r\nfn program_03_kick_mic(options = {}) = sfz(\"assets/Programs/03-kick-mic.sfz\", merge({sample_budget_frames: 93323264}, options));\r\nfn program_04_snare_mic(options = {}) = sfz(\"assets/Programs/04-snare-mic.sfz\", merge({sample_budget_frames: 115343360}, options));\r\nfn program_05_oh_mic(options = {}) = sfz(\"assets/Programs/05-oh-mic.sfz\", merge({sample_budget_frames: 122683392}, options));\r\nfn program_06_mid_mic(options = {}) = sfz(\"assets/Programs/06-mid-mic.sfz\", merge({sample_budget_frames: 115343360}, options));\r\nfn program_07_room_mic(options = {}) = sfz(\"assets/Programs/07-room-mic.sfz\", merge({sample_budget_frames: 115343360}, options));\r\nfn program_08_vintage_mic(options = {}) = sfz(\"assets/Programs/08-vintage-mic.sfz\", merge({sample_budget_frames: 93323264}, options));\r\n","contrib/vsco-2-ce/README.md":"# VSCO 2 Community Edition\r\n\r\nNative orchestral sample maps for strings, winds, brass, harp, and percussion.\r\nThe installer needs Python 3 and downloads the pinned CC0 recordings separately.\r\nNo recordings are committed to this repository.\r\n\r\n[All packs](../../contrib/README.md) · [Instrument guide](../../docs/instruments.md)\r\n\r\nRun shell commands from the `muz-core` checkout unless stated otherwise.\r\nFor the installed CLI, run these utilities from the installed contrib copy\r\ncreated by `./install.sh`; see the [pack setup guide](../../contrib/README.md#install-and-import).\r\n\r\n## Contents\r\n\r\n- [Install](#install)\r\n- [Use the instruments](#use-the-instruments)\r\n- [Available mappings](#available-mappings)\r\n- [Calibrated sustains](#calibrated-sustains)\r\n- [Expressive voices](#expressive-voices)\r\n- [Asset layout](#asset-layout)\r\n- [Upstream and license](#upstream-and-license)\r\n- [Manual installation](#manual-installation)\r\n- [Known limits](#known-limits)\r\n\r\n## Install\r\n\r\n```sh\r\npython3 contrib/vsco-2-ce/install.py            # fetch, verify and place\r\npython3 contrib/vsco-2-ce/install.py --check    # verify only, download nothing\r\npython3 contrib/vsco-2-ce/install.py --force    # replace files that fail their pin\r\npython3 contrib/vsco-2-ce/install.py --jobs 8   # parallel downloads (default 4)\r\n```\r\n\r\nFiles are downloaded from `raw.githubusercontent.com` at the pinned revision,\r\nchecked against their pinned size and SHA-256, and only then moved into place\r\natomically. Re-running verifies what is already there and installs what is\r\nmissing; an existing file that does not match its pin is reported instead of\r\nbeing overwritten. `--check` exits non-zero when anything is missing or\r\ndiffering.\r\n\r\n## Use the instruments\r\n\r\nThis fragment declares instruments to pass to `track(...)`:\r\n\r\n```muz\r\nuse \"contrib/vsco-2-ce/strings\" as strings;\r\nuse \"contrib/vsco-2-ce/winds\" as winds;\r\nuse \"contrib/vsco-2-ce/calibrated\" as calibrated;\r\n\r\nlet cello = strings.instrument(strings.cello_zones, {attack_ms: 82, release_ms: 290});\r\nlet flute = calibrated.instrument(calibrated.flute_zones, {attack_ms: 18, release_ms: 130});\r\n```\r\n\r\nUse `instrument(zones, options)` from the module that owns the zones rather\r\nthan calling `sample(zones, options)` directly: the engine resolves sample\r\npaths in the module that defines the function, so a call from a piece would\r\nlook for the recordings next to the piece. `shorts.muz` already exposes its\r\nfinished `cello_short` and `violin_short` samplers.\r\n\r\nLevel tables (`cello_levels`, `violin_levels`, ..., keyed by pitch and velocity\r\nrange) carry the measured level of each zone for pieces that want a\r\nsource-derived gain lane; `extra.muz` folds that gain into each zone's\r\n`gain_db` instead, and `calibrated.muz` replaces it with -24 dBFS everywhere.\r\n\r\n## Available mappings\r\n\r\nZone tables are tabulated per instrument; order is musically significant\r\nbecause samplers select round robins by index.\r\n\r\n| Module | Contents |\r\n|---|---|\r\n| `strings.muz` | cello, viola and violin section sustains with level tables |\r\n| `winds.muz` | flute sustains with level table |\r\n| `expanded.muz` | horn, oboe, contrabass, harp, struck timpani, timpani roll, suspended cymbal |\r\n| `extra.muz` | clarinet, bassoon, trumpet, trombone (zone gain baked in) |\r\n| `shorts.muz` | cello and violin section spiccato, already built into samplers |\r\n| `alternates.muz` | a second flute sustain mapping, solo violin arco vib, two-take flute staccato |\r\n| `calibrated.muz` | original sustains with per-zone calibration, levels reported as -24 dBFS |\r\n\r\n## Calibrated sustains\r\n\r\n`calibrated.muz` reads the pinned original recordings and applies the historical\r\nbody-RMS corrections as per-zone `gain_db`. Each note owns its correction, including\r\nits release. `install.py` alone is sufficient: the 124 derived float WAVs (about\r\n447 MB) are no longer needed. Existing derivatives are left untouched.\r\n\r\n`calibration.json` records the original source hashes, measured mono body RMS over\r\n0.4–2.8 seconds, and gains targeting -24 dBFS. These are the actual derivative\r\nmeasurements, not estimates from the older pitch/velocity level tables. The small\r\n`calibration-gains.muz` module carries the same values in source:\r\n\r\n```sh\r\npython3 contrib/vsco-2-ce/export-calibration.py --check\r\n```\r\n\r\nOmit `--check` to regenerate the source table. This validates the measurements against\r\nthe pinned manifest. `calibrate.py` remains a legacy derivative reproduction tool;\r\nit is unnecessary for playback and does not update the committed gain tables.\r\nGain follows resampling instead of being baked into float samples, so tiny\r\nfloating-point differences are possible; recording selection, tuning and onsets remain.\r\n\r\n## Expressive voices\r\n\r\n```muz\r\nuse \"contrib/vsco-2-ce/expressive\" as expressive;\r\nlet flute = expressive.voice(\"flute\", [71, 74], 6000Hz, {release_ms: 130});\r\nlet cello = expressive.strings(\"cello\", [46, 48]);\r\n```\r\n\r\n`voice(name, keys, tone, options, sample_budget_frames)` provides a stereo note-local filter; pressure\r\nraises cutoff by one octave. `strings(name, keys, options)` accepts cello, viola,\r\nor violin, retaining round robins separately in the soft and loud layers. Pressure\r\ncrossfades the two calibrated timbres from 0 to 1; note velocity still controls\r\namplitude. These optional sounds use their own envelope policies; the original samplers\r\nremain available. The optional `keys` argument restricts loaded zones and coverage; its default\r\n`[0, 127]` keeps the complete map. Both helpers explicitly allow 16,777,216 decoded\r\nframes (128 MiB), sufficient for each full section-string map. `voice` accepts a\r\n`sample_budget_frames` argument; `strings` accepts it in its patch `options`.\r\nLayered strings use a 30 ms attack and 250 ms release; `options` overrides patch\r\ncontrols such as gain. Both layer maps must cover every performed note.\r\n\r\n## Asset layout\r\n\r\nDestination paths keep the upstream folder names, including spaces. They are\r\nrelative to `assets/`, and the modules below address them as `assets/<path>`.\r\n\r\n```\r\nassets/vsco/Strings/Cello Section/susvib/      cello section sustains\r\nassets/vsco/Strings/Viola Section/susvib/      viola section sustains\r\nassets/vsco/Strings/Violin Section/susVib/     violin section sustains\r\nassets/vsco/Strings/Solo Contrabass/SusNV/     contrabass sustains\r\nassets/vsco/Strings/Solo Violin/Arco Vib/      solo violin arco vib\r\nassets/vsco/Strings/Harp/                      harp\r\nassets/vsco/Brass/F Horn/sus/                  horn sustains\r\nassets/vsco/Brass/Trumpet/                     trumpet sustains\r\nassets/vsco/Brass/Tenor Trombone/              trombone sustains\r\nassets/vsco/Woodwinds/Flute/                   flute sustains and staccato\r\nassets/vsco/Woodwinds/Oboe/Vib/                oboe sustains\r\nassets/vsco/Woodwinds/Clarinet/susLong/        clarinet sustains\r\nassets/vsco/Woodwinds/Bassoon/                 bassoon sustains\r\nassets/vsco/Percussion/Timpani/                struck timpani\r\nassets/vsco/VSCO 1 Percussion/varMetal/Cymbals/susp/  suspended cymbal\r\nassets/vsco/LICENSE, assets/vsco/README.md     upstream attribution\r\nassets/shorts/Strings/Cello Section/spic/     cello section spiccato\r\nassets/shorts/Strings/Violin Section/Spic/    violin section spiccato\r\n```\r\n\r\nThree pinned files (the upstream LICENSE and README, and one alternate timpani\r\nhit take) are kept alongside the catalogs rather than referenced by them.\r\n\r\n## Upstream and license\r\n\r\n| | |\r\n|---|---|\r\n| Library | VSCO 2 Community Edition (VSCO 2 CE) |\r\n| Publisher | Versilian Studios — recorded by Sam Gossner and Simon Dalzell, sample cutting by Elan Hickler / Soundemote |\r\n| Repository | https://github.com/sgossner/VSCO-2-CE |\r\n| Revision | `440300901dfe9275fd84e0b7763af1f8443ae62e` |\r\n| License | CC0 1.0 Universal (public domain dedication) — https://raw.githubusercontent.com/sgossner/VSCO-2-CE/440300901dfe9275fd84e0b7763af1f8443ae62e/LICENSE |\r\n| Size | 268 files, 462482142 bytes (about 462 MB) |\r\n\r\n`manifest.json` pins every file: upstream repository path, destination path,\r\nbyte size and SHA-256. No recording is committed to this repository; the\r\n`assets/` directory is gitignored.\r\n\r\n## Manual installation\r\n\r\nAny downloader works as long as the files land at the pinned paths and verify:\r\n\r\n```sh\r\ncd contrib/vsco-2-ce\r\npython3 -c \"import json;[print(f['path'], f['url'], sep='\\t') for f in json.load(open('manifest.json'))['files']]\" |\r\nwhile IFS=\"$(printf '\\t')\" read -r path url; do\r\n    mkdir -p \"assets/$(dirname \"$path\")\"\r\n    curl -fsSL --retry 3 -o \"assets/$path\" \"$url\"\r\ndone\r\npython3 install.py --check\r\n```\r\n\r\n## Known limits\r\n\r\nResearch on 2026-09-12 found that the upstream\r\n[CE cello sustain SFZ](https://github.com/sgossner/VSCO-2-CE/blob/6dd651d55dde97fd4028699be9d4481f26917891/CelloEnsSusVib.sfz)\r\ndoes not specify loop points; the installed C1 v1 recording also has no embedded\r\n`smpl` loop chunk. This does not establish a validated loop set for our maps.\r\nSustain-loop defaults remain deferred until candidate regions are auditioned for\r\nvibrato continuity, crossfade beating, and release behavior. Do not use the separate\r\nVSCO Pro manual as evidence that CE contains equivalent looping or dynamic controls.\r\n\r\nFull section-string maps can be prepared with the explicit sample budget; range\r\nselection is optional. Simultaneous dynamic layers can also reveal timing or\r\nphase differences between recordings: audition the chosen register before using a\r\ncrossfade as a replacement for velocity selection.\r\n","contrib/vsco-2-ce/alternates.muz":"// VSCO 2 CE alternates that complement winds.muz: a second flute sustain\r\n// mapping of the same eight recordings, solo violin arco vib, and two-take\r\n// flute staccato tongued attacks. Zone 