, low: 0, high: 1, db: -38.154},];\r\n\r\n// The engine resolves sample paths in the module that defines the function,\r\n// so build samplers through this module instead of calling sample() elsewhere.\r\nfn instrument(zones, options = {}) = sample(zones, options);\r\n","contrib/vsco-2-ce/expressive.muz":"// Opt-in per-note tone over calibrated originals. Full maps fit the explicit 128 MiB budget.\r\nuse \"calibrated.muz\" as calibrated;\r\nuse \"std/instrument\" as instrument;\r\nuse \"std/signal\" as s;\r\nfn voice(name, keys = [0, 127], tone = 6000Hz, options = {}, sample_budget_frames = 16777216) {\r\n    assert(len(keys) == 2 && keys[0] <= keys[1], \"keys must be [low, high]\");\r\n    let zones = filter(calibrated[name + \"_zones\"], fn(z) =>\r\n        z.keys[0] <= keys[1]\r\n        && z.keys[1] >= keys[0]);\r\n    let selected = map(\r\n        zones,\r\n        fn(z) => merge(z, {keys: [max(z.keys[0], keys[0]), min(z.keys[1], keys[1])]})\r\n    );\r\n    let cutoff = s.octaves(s.param(\"tone\", tone, 100Hz, 12000Hz), s.expression(\"pressure\"));\r\n    instrument.sampled(calibrated.instrument(selected, options), cutoff, {\r\n        sample_budget_frames: sample_budget_frames\r\n    })\r\n};\r\n\r\n// Two recorded dynamic layers, with round robins retained inside each layer.\r\n// Only the three section-string maps have this common velocity split.\r\nfn strings(name, keys = [0, 127], options = {}) {\r\n    assert(\r\n        contains([\"cello\", \"viola\", \"violin\"], name),\r\n        \"dynamic strings requires cello, viola, or violin\"\r\n    );\r\n    assert(len(keys) == 2 && keys[0] <= keys[1], \"keys must be [low, high]\");\r\n    let zones = filter(calibrated[name + \"_zones\"], fn(z) =>\r\n        z.keys[0] <= keys[1]\r\n        && z.keys[1] >= keys[0]);\r\n    fn layer(loud) = calibrated.instrument(\r\n        map(\r\n            filter(zones, fn(z) => if loud {\r\n                z.velocity[0] >= 0.7\r\n            } else {\r\n                z.velocity[1] <= 0.7\r\n            }),\r\n            fn(z) => merge(z, {\r\n                velocity: [0, 1],\r\n                keys: [max(z.keys[0], keys[0]), min(z.keys[1], keys[1])]\r\n            })\r\n        )\r\n    );\r\n    let soft = layer(false);\r\n    let loud = layer(true);\r\n    let blend = s.mapping(s.expression(\"pressure\"));\r\n    let e = s.adsr(30ms, 300ms, 0.8, 250ms);\r\n    fn channel(side) = instrument.crossfade(s.reader(soft, side), s.reader(loud, side), blend);\r\n    voice_patch(\r\n        \"vsco-dynamic-strings\",\r\n        merge({\r\n            sample_budget_frames: 16777216,\r\n            gain_db: 0,\r\n            velocity_track: 1,\r\n            output: s.stereo_mul(s.stereo(channel(\"left\"), channel(\"right\")), e),\r\n            lifetime: {envelope: e, tail: 0s}\r\n        }, options)\r\n    )\r\n};\r\n","contrib/vsco-2-ce/extra.muz":"// VSCO 2 CE winds and brass extras: clarinet, bassoon, trumpet and trombone,\r\n// each with a baked zone gain that targets -24 dBFS mono body RMS.\r\n// Upstream: sgossner/VSCO-2-CE, revision 440300901dfe9275fd84e0b7763af1f8443ae62e (CC0-1.0).\r\n// Recordings are fetched by install.py into the gitignored assets/ directory.\r\n\r\n// 50 unchanged CC0 recordings, verified against manifest.json by byte size and\r\n// SHA-256. Static zone gain targets -24 dBFS mono body RMS.\r\n// Filename octaves are one below scientific pitch. Written safe ranges:\r\n// clarinet G3-G5 (55-79), bassoon G#1-D#4 (32-63), trumpet D#4-A5 (63-81),\r\n// trombone B2-G4 (47-67). Originals stay unedited under the gitignored assets/.\r\n\r\nlet clarinet_zones = [\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Clarinet/susLong/DCClar_susLong_A#2_v1_rr1_sum.wav\",\r\n        root: 58.041638,\r\n        keys: [55, 60],\r\n        velocity: [0, 0.7],\r\n        offset: 0.019921s,\r\n        gain_db: 13.8564\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Clarinet/susLong/DCClar_susLong_A#2_v3_rr1_sum.wav\",\r