: 0.014931s\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Flute/susvib/LDFlute_susvib_E4_v1_1.wav\",\r\n        root: 75.9699,\r\n        keys: [75, 78],\r\n        velocity: [0, 1],\r\n        offset: 0.014931s\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Flute/susvib/LDFlute_susvib_A4_v1_1.wav\",\r\n        root: 80.9951,\r\n        keys: [79, 82],\r\n        velocity: [0, 1],\r\n        offset: 0.014931s\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Flute/susvib/LDFlute_susvib_C5_v1_1.wav\",\r\n        root: 84.0063,\r\n        keys: [83, 86],\r\n        velocity: [0, 1],\r\n        offset: 0.034885s\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Flute/susvib/LDFlute_susvib_E5_v1_1.wav\",\r\n        root: 88.0405,\r\n        keys: [87, 90],\r\n        velocity: [0, 1],\r\n        offset: 0.014931s\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Flute/susvib/LDFlute_susvib_A5_v1_1.wav\",\r\n        root: 92.9792,\r\n        keys: [91, 94],\r\n        velocity: [0, 1],\r\n        offset: 0.024908s\r\n    },\r\n    {\r\n        path: \"assets/vsco/Woodwinds/Flute/susvib/LDFlute_susvib_C6_v1_1.wav\",\r\n        root: 96.0306,\r\n        keys: [95, 98],\r\n        velocity: [0, 1],\r\n        offset: 0.064816s\r\n    },\r\n];\r\n\r\nlet flute_levels = [\r\n    {lo: 58, hi: 62, low: 0, high: 1, db: -33.515},\r\n    {lo: 63, hi: 66, low: 0, high: 1, db: -31.141},\r\n    {lo: 67, hi: 70, low: 0, high: 1, db: -30.342},\r\n    {lo: 71, hi: 74, low: 0, high: 1, db: -27.309},\r\n    {lo: 75, hi: 78, low: 0, high: 1, db: -23.805},\r\n    {lo: 79, hi: 82, low: 0, high: 1, db: -22.496},\r\n    {lo: 83, hi: 86, low: 0, high: 1, db: -17.586},\r\n    {lo: 87, hi: 90, low: 0, high: 1, db: -16.931},\r\n    {lo: 91, hi: 94, low: 0, high: 1, db: -12.165},\r\n    {lo: 95, hi: 98, low: 0, high: 1, db: -10.803},\r\n];\r\n\r\n// The engine resolves sample paths in the module that defines the function,\r\n// so build samplers through this module instead of calling sample() elsewhere.\r\nfn instrument(zones, options = {}) = sample(zones, options);\r\n","docs/README.md":"# muz documentation\r\n\r\nmuz turns source into a musical performance and an audio graph. Start with a\r\nnative instrument to learn the workflow, then add the composition and production\r\nfeatures your piece needs. These guides describe the current checkout.\r\n\r\nOffline: `muz docs` or `muz docs index`. Use `muz COMMAND --help` for command flags\r\nand `muz devices inspect DEVICE` for device parameters and ranges.\r\n\r\n## Start here\r\n\r\n1. [Getting started](getting-started.md) (`muz docs getting-started`): install,\r\n   create a project, check it, render audio, and audition changes.\r\n2. [Language](language.md) (`muz docs language`): build musical material and\r\n   arrange it into a song.\r\n3. [Performance](performance.md) (`muz docs performance`): control articulation,\r\n   dynamics, timing, pedals, and expression.\r\n4. [Instruments](instruments.md) (`muz docs instruments`) and\r\n   [production](production.md) (`muz docs production`): choose sounds and connect\r\n   them with effects, routing, and automation.\r\n5. [Workflow](workflow.md) (`muz docs workflow`): inspect, revise, compare, and\r\n   deliver a finished piece.\r\n\r\n## Find a task\r\n\r\n| I want to… | Read |\r\n| --- | --- |\r\n| Understand syntax, units, patterns, or imports | [Language](language.md) |\r\n| Reuse a passage and edit one occurrence | [Arranging passages](language.md#arranging-passages) |\r\n| Import or export MIDI | [MIDI interchange](language.md#midi-interchange) |\r\n| Humanize notes or check piano constraints | [Performance](performance.md) |\r\n| Install samples or configure a plugin | [Instruments](instruments.md), [contrib packs](../contrib/README.md) |\r\n| Build a native instrument graph | [Synthesis](synthesis.md) (`muz docs synthesis`) |\r\n| Set up sends, sidechains, racks, or automation | [Production](production.md) |\r\n| Control a live session or page through events | [Workflow](workflow.md) |\r\n| Render a section, stems, or comparison variants | [Rendering and delivery](workflow.md#rendering-and-delivery) |\r\n| Move a song into a DAW | [DAWProject export](dawproject.md) (`muz docs dawproject`) |\r\n| Understand the evidence behind DAW compatibility claims | [DAWProject validation](dawproject-validation.md) (`muz docs dawproject-validation`) |\r\n| Build an editor or another host around muz | [Embedding](embedding.md) (`muz docs embedding`) |\r\n| Host native playback, revision receipts, listening controls, and analysis | [Native output coordinator](embedding.md#native-output-coordinator) |\r\n| Import and play original SFZ programs | [Native SFZ instruments](sfz.md) |\r\n| Inspect native SFZ realtime measurements | [SFZ performance qualification](sfz-performance.md) |\r\n| Report an engine or language obstacle | [Composer friction](composer-friction.md) |\r\n\r\n## Terms used in the guides\r\n\r\n| Term | Meaning |\r\n| --- | --- |\r\n| Pattern | Musical events plus a logical span, before instrument assignment. |\r\n| Score time | Exact beat positions and written durations. A literal bar is always four quarter beats. |\r\n| Performed time | Scheduled attacks, releases, and controls after tempo and performance offsets are applied. |\r\n| Track | A pattern connected to an instrument, with inserts and output routing. |\r\n| Logical / physical track | The authored track / a compiled audio lane. A kit expands into physical tracks for its played voices. |\r\n| Bus | A shared processing and routing destination; `master` is the final output chain. |\r\n| Passage / occurrence | Reusable local material / one named placement of that material in an arrangement. |\r\n| Accepted revision | The description retained after its matching audio application receipt. Failed edits leave the last accepted session running. |\r\n| Tap | Audio taken at a defined point in the graph, such as after a track's inserts and pan. |\r\n| Tail | Extra render time for releases and effect decay after the musical material ends. |\r\n\r\n## For contributors and agents\r\n\r\nRead [AGENTS.md](../AGENTS.md) for repository boundaries and the verification\r\nbudget. Before composing, revising a piece, or changing the engine, read the\r\n[friction protocol and live log](composer-friction.md). It is the canonical place\r\nfor unresolved engine and language issues.\r\n\r\n| Location | Contents |\r\n| --- | --- |\r\n| `src/` | Rust language implementation, compiler, audio engine, CLI, and host APIs |\r\n| `std/` | Editable `.muz` functions, instrument recipes, and musical policies |\r\n| `examples/` | Independent demonstrations of individual techniques |\r\n| `templates/song.muz` | Source copied by `muz new` |\r\n| `tests/` | Focused engine and language tests using synthetic material |\r\n| `crates/muz-clap/` | Native instrument/effect wrapper used by DAWProject exports |\r\n| `contrib/` | Third-party instrument mappings and installers; content is downloaded separately |\r\n| `out/` | Ignored local renders and other generated artifacts |\r\n\r\nIn the maintainer's workspace, pieces happen to live in the sibling\r\n`muz-projects` checkout. That is a local convention for agents working here,\r\nnot a required layout for muz users.\r\n\r\nThe [blind comparison skill](../.agents/skills/muz-ab/SKILL.md) runs listening\r\ntrials; the [visualizer skill](../.agents/skills/muz-visualizer/SKILL.md) makes\r\nvideos synchronized to a piece's performed notes and master. Their instructions\r\napply when using those workflows.\r\n","docs/composer-friction.md":"# Composer friction\r\n\r\nThis is the canonical protocol and live log for unresolved engine and language\r\nissues that can be fixed in muz. Read it before composing, revising a piece, or\r\nchanging the engine. Repository boundaries and the verification budget are in\r\n[AGENTS.md](../AGENTS.md).\r\n\r\n[Documentation index](README.md)\r\n\r\n## What belongs here\r\n\r\nRecord defects and limitations in language semantics, synthesis, rendering,\r\ndiagnostics, and exposed primitives. Include issues that distort musical choices\r\nor force repetitive editing, even when a workaround lets the piece proceed.\r\nA valid workaround does not close a report.\r\n\r\nExternal model quality, provider availability, skill tooling, and development\r\nprocess reports do not belong here.\r\n\r\n## Recording a report\r\n\r\nCommit a report in the same commit as the piece or revision that exposed it.\r\nFor work without a piece, name the task and commit the report with that work.\r\nEach entry includes:\r\n\r\n- **Origin:** the piece, revision, or task that exposed the issue.\r\n- **Observed behavior:** what muz does and the relevant conditions.\r\n- **Affected work:** the musical decision or work the issue obstructs.\r\n- **Workaround:** how the work proceeded, if possible.\r\n- **Desired behavior:** the capability or correction needed.\r\n\r\nInclude a small reproduction when useful. Do not freeze a whole composition as\r\na test. A piece commit with no new friction needs no report; a problem found and\r\nfixed within the same commit needs no artificial live entry.\r\n\r\n## Choosing a resolution\r\n\r\nSeek a general solution that expands the builtins/kernel as little as necessary\r\nwhile fully resolving the reported problem. First ask whether existing language\r\noperations and exposed data can express the solution clearly. Put reusable\r\npolicies and recipes in `std/`, particular musical choices in project source,\r\nand demonstrations of useful techniques in examples.\r\n\r\nWhen source cannot express the solution well, identify the missing general\r\ncapability. Prefer a small, composable primitive or better access to musical data\r\nthat enables a family of solutions over a builtin for one special case. Keep\r\nshapes, selection rules, and overlap policies in source wherever practical.\r\n\r\nKernel changes remain appropriate for engine defects, runtime guarantees, and\r\ncapabilities that require them. Minimizing the kernel must not retain awkward\r\nworkarounds or move complexity into every composition.\r\n\r\nIn the fixing commit, explain why existing facilities suffice or why the new\r\nprimitive belongs in the kernel. Demonstrate the specific resolution in source.\r\nFor example, tag-derived automation uses exposed note data and timing operations\r\nso composers can write their own automation recipes. This principle applies to\r\nall friction items.\r\n\r\n## Closing a report\r\n\r\nVerify the reported use case, document usage in the relevant reference, and add\r\nfocused regression tests. Remove the entry in the same commit that resolves the\r\nengine or language issue. If only part is fixed, keep the remaining problem\r\nexplicit.\r\n\r\nGit history retains reports and fixes. This file has no resolved section or\r\nremedy archive; do not maintain parallel per-piece friction logs.\r\n\r\n## Open reports\r\n\r\nNo open reports.\r\n","docs/dawproject-validation.md":"# DAWProject validation evidence\r\n\r\nThese are observations from the Bitwig Studio 6.0.11 Linux probes begun on\r\n2026-09-26 and their follow-ups. They support the capability statements in\r\n[DAWProject export](dawproject.md); they are historical evidence, not mandatory\r\ndelivery checks or a promise about other hosts and versions.\r\n\r\nLabels such as `final13` identify successive probe runs. Observations below are\r\ngrouped by feature; later runs sometimes resolve a narrower question left open\r\nby an earlier one. Audible response, displayed data, and exact DSP equivalence\r\nare separate claims.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs dawproject-validation`\r\n\r\n## Contents\r\n\r\n- [Basic import and parameter persistence](#basic-import-and-parameter-persistence)\r\n- [Embedded samples](#embedded-samples)\r\n- [Note expression](#note-expression)\r\n- [Sidechains](#sidechains)\r\n- [Groups, sends, buses, and markers](#groups-sends-buses-and-markers)\r\n- [Controller lanes](#controller-lanes)\r\n- [Probe isolation](#probe-isolation)\r\n\r\n## Basic import and parameter persistence\r\n\r\nBitwig Studio 6.0.11 (revision 160070,\r\n`f2730b10e641fdf2e4ae82140089d5f6550ca3b7`) imported a three-note\r\nsynthetic archive whose XML passed the pinned XSDs. The notes appeared at the\r\nintended MIDI keys and beats; Bitwig labels MIDI key 60 as C3. Muz Instrument\r\nrestored its state and parameters. At 48 kHz, the lead and master meters moved\r\nduring playback. G3 was edited from start `1.3.1.00` to `1.2.1.00`, the track\r\nwas duplicated, and the edited project saved and reopened with both changes.\r\nBitwig also completed an offline WAV export.\r\n\r\nA second synthetic archive imported Muz Instrument with cutoff automation and\r\na ZamEQ2 CLAP insert. Bitwig displayed the overridden ZamEQ2 value `3.0`, the\r\nMuz cutoff lane and its `800 Hz` initial value. During playback the cutoff\r\nread `1030.4 Hz` at 0.127 s, `3003.2 Hz` at 1.237 s and `1200 Hz` at 2.389 s,\r\nfollowing the rising then falling lane. Other device families and routing\r\ncases remain bounded by their report warnings.\r\n\r\nA combined synthetic archive contained four note tracks, a native parallel\r\nrack, a sidechain compressor, embedded sampler assets, note expression, smooth\r\nautomation, a tempo change and an effect tail. In the final13 run, all four\r\nMuz Instrument and two Muz FX instances loaded. Playback activated meters on\r\nall four tracks and Master, and the displayed tempo changed from 120 to 90 BPM.\r\nThe sampled track's `gain_db` was changed from `0` to `24`; that value survived\r\nsaving and reopening the combined project. Two offline 24-bit WAV exports\r\ncompleted.\r\n\r\nThe combined run did not reconnect the sidechain. It contained\r\nno groups, sections, controller lanes, buses or sends,\r\nso their representation was not exercised. The report still names manual\r\nsidechain setup, unverified rack/expression fidelity and manual tail setup; successful\r\nplayback and export do not establish DSP parity or exact tail handling.\r\n\r\nIn final14, the duplicated lead's Muz Instrument cutoff was changed to\r\n`7494.3 Hz` while the original remained at `1800 Hz`. Saving and reopening\r\nretained both distinct values, and both plugin instances loaded successfully.\r\nThis establishes independent parameter state for that duplicate pair.\r\n\r\n## Embedded samples\r\n\r\nIn final15, the combined archive was copied into the private sandbox's home\r\ndirectory. The sampled track was soloed and the first bar exported offline to\r\na 24-bit WAV. The result was 48 kHz stereo with 112001 frames, 9592 nonzero PCM\r\nsamples, a peak of 917165 in signed 24-bit units and its first nonzero sample at\r\nindex 2. Bitwig loaded all six instances without sample or state errors. This\r\nconfirms audio from the embedded sample after relocation; it does not establish\r\npinned-zone equivalence or DSP parity. It supersedes the earlier inconclusive\r\nSolo/Play screenshot, which showed no meter movement in that frame.\r\n\r\n## Note expression\r\n\r\nIn final16, the selected glass note's inspector showed Pitch `0.06` and Timbre\r\n`0.95%`, with a rising line inside the note. The exported XML contained three\r\npitch and three timbre points within that note. The attempted drag did not move\r\nit: Start remained `1.2.1.00`. The observation establishes visible expression\r\ndata, but not expression playback or attachment after a note move.\r\n\r\nFinal25 moved the glass B3 note with plain Right Arrow from Start `1.2.1` to\r\n`1.2.2`, preserving its key and length. The rising internal line remained visible.\r\nAfter movement, Inspector showed Pitch `0.00%`, Timbre `0.95%` and Pressure\r\n`0.00%`. This establishes note movement with visible expression retained; it does\r\nnot establish unchanged values for every curve point. The archive contains three\r\npitch and three timbre points, but point-by-point host readback remains\r\nunverified. The later expression A/B below tests an audible effect separately.\r\n\r\nA later glass solo comparison tested imported expression against a no-expression\r\nvariant. After excluding the first 100 ms, their difference had a peak of 1600481\r\nand RMS of 314919.55 in raw signed 24-bit PCM units. A repeated no-expression\r\nbounce was bit-identical over that same window. This supports an audible effect\r\nfrom the imported expression, alongside the note-edit observation. It does not\r\nprove each pitch/timbre point was unchanged or establish sample-exact native Muz\r\nexpression parity. The CC11 limitation above remains a separate diagnosed outcome.\r\n\r\n## Sidechains\r\n\r\nIn the final18 follow-up, the compressor's header sidechain icon opened the\r\n`Select sidechain input` auxiliary-input panel. Its kick source offered PRE,\r\nPOST and Muz Out choices; kick POST was selected and playback was active.\r\nNo dedicated Detector meter was observed, and there was no exact detector-tap,\r\ntiming or sound comparison. Separately, the native harness verifies detector-driven\r\ngain reduction and exact rack impulse parity with 240 samples of parallel-path\r\nlatency. Those harness results do not establish the imported host connection's\r\naudio behavior.\r\n\r\nFinal19 compared paired Project Master bounces over `1.1.1`–`2.1.1`, both\r\n48 kHz stereo 24-bit with no dither and 112001 frames. With `No input`, peak\r\nwas -6.864 dBFS and RMS was -20.633 dBFS; with kick POST selected, peak was\r\n-8.566 dBFS and RMS was -20.918 dBFS. Of 224002 interleaved PCM samples,\r\n157902 differed. This is consistent with a sidechain response through the\r\nselected auxiliary input. It does not establish the exact original Muz detector\r\ntap, timing or DSP parity.\r\n\r\n## Groups, sends, buses, and markers\r\n\r\nIn final17, the structure probe showed a `drums` group with `hat` and `open_hat`\r\nchildren, a `room` FX track containing Muz and routed to Master, a `keys` send\r\nnamed `room`, and an `End` marker. That run did not verify the exact send level,\r\npost tap, `Intro`/`Turn` labels or CC64 lane representation/playback.\r\n\r\nFinal20 imported the structure fixture with the keys-to-room send and room FX\r\nbus, then exported Project Master with the bus enabled. The 2-second WAV was\r\n48 kHz stereo 24-bit with 96000 frames and nonzero PCM (peak 464796 and RMS\r\n68750 in signed 24-bit units). The paired bus-muted condition could not be run:\r\nthe isolated Xvfb window was unavailable through the UI controller. The enabled\r\nbounce establishes project audio output, but does not isolate the send/bus\r\ncontribution or verify the -12 dB send level or post tap. The real profile,\r\nCLAP directory and Projects manifests matched after correcting the comparator.\r\n\r\nFinal22 showed green meters on both keys and the room FX track during playback\r\nat `1.2.1.77` / `0:00.597`. Room had no clip, and its idle meter was dark. This\r\nsupports audio reaching room through the keys send. It does not measure the\r\nsend's exact -12 dB level or establish its post tap.\r\n\r\nFinal23 showed the keys-to-room send hover in Bitwig's Mixer explicitly reading\r\n`SEND -12.0 dB` and `ENABLE On`. `Intro`, `Turn` and `End` markers were visible.\r\nThis verifies the imported send's displayed level and enabled state and the\r\nsection labels. The archive encodes the send as `type=\"post\"`; Bitwig's actual\r\npost-fader behavior was not independently verified in that run. The CC64 lane\r\nwas not inspected during final23.\r\n\r\nFinal24 compared a schema-valid variant that changed only keys Volume from `1`\r\nto `0.0001` (-80 dB), leaving the `type=\"post\"` send unchanged. The baseline\r\nshowed green keys and room meters at `0:00.597`; the variant showed keys at\r\n-80 dB and a dark room meter at `0:00.575`. This supports post-fader send\r\nresponse in Bitwig. The meter comparison does not establish sample-exact tap\r\nparity with native Muz.\r\n\r\n## Controller lanes\r\n\r\nFinal26 inspected the existing keys automation lane `Ch. 1 Sustain Pedal (#64)`.\r\nIt showed a high hold from the start of bar 1 followed by a step down, matching\r\nthe fixture's CC64 values of 127 at beat 0 and 0 at beat 2. No lane was created\r\nand no points were drawn. This verifies imported controller-lane representation;\r\nthe audible sustain-pedal effect was not tested.\r\n\r\nA subsequent CC11 probe compared two Bitwig bounces differing only in a normalized\r\n`channelController` 11 point, changed from `1` to `0`. The 96000-frame bounces\r\nwere byte-identical. A focused CLAP harness test independently delivered MIDI\r\nCC11 high/low events and matched native DSP output sample-for-sample; after\r\nsmoothing, low-level energy was below 1% of high-level energy. Together these\r\nresults indicate that the imported lane did not produce the expected controller\r\neffect in this Bitwig/Muz path. There was no host callback trace, so this does\r\nnot establish that all CC events are absent or that every controller is affected.\r\nUse native Muz playback for guaranteed original controller behavior; imported\r\nlane visibility alone is insufficient evidence of playback fidelity.\r\n\r\n## Probe isolation\r\n\r\nThe probe projects and their follow-up runs used a private Bitwig profile\r\nand temporary activation copies in\r\nan isolated Linux sandbox. The copies were removed, and the real Bitwig profile,\r\nCLAP directory and Projects tree had no mtime-manifest changes after the runs.\r\n\r\nReturn to the [export guide](dawproject.md) for setup, report remedies, and the\r\ncurrent handoff contract.\r\n","docs/dawproject.md":"# DAWProject export\r\n\r\n`muz export` creates an editable DAWProject archive and a fidelity report from\r\none compiled song. Use it for a one-way handoff to a DAW: notes, arrangement,\r\nand exposed automation can be edited there, but those edits cannot be converted\r\nback into authored muz source.\r\n\r\nThe tested target profile is Bitwig Studio 6.0.11 on Linux. Read the report before\r\nusing an export for production; a successful export does not imply lossless\r\nconversion. See the [dated validation evidence](dawproject-validation.md) for what\r\nhas been observed in that host.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs dawproject`\r\n\r\n## Contents\r\n\r\n- [Install the native wrapper and export](#install-the-native-wrapper-and-export)\r\n- [Read the fidelity report](#read-the-fidelity-report)\r\n- [Supported data and limitations](#supported-data-and-limitations)\r\n- [DAW setup and troubleshooting](#daw-setup-and-troubleshooting)\r\n- [Replace native device source](#replace-native-device-source)\r\n- [State and runtime contract](#state-and-runtime-contract)\r\n\r\n## Install the native wrapper and export\r\n\r\nNative muz instruments and effects are carried by the Muz CLAP wrapper. From the\r\nengine checkout, run the installer to install both the CLI and wrapper:\r\n\r\n```sh\r\n./install.sh\r\n```\r\n\r\nOn Linux the wrapper is installed to `~/.clap`; on macOS it goes to\r\n`~/Library/Audio/Plug-Ins/CLAP`. Set `CLAP_DIR` to choose another location.\r\nRestart or rescan the DAW after installation. The plugin exposes\r\n`com.plausiblyreliable.muz.instrument` and `com.plausiblyreliable.muz.fx`.\r\nKeep the same plugin version available when reopening an export. The recipient\r\nmust also install any third-party plugins used by the song.\r\n\r\nWith the muz CLI installed, run from your project directory:\r\n\r\n```sh\r\nmuz export song.muz -o song.dawproject\r\n```\r\n\r\n`--format dawproject` and `--profile bitwig-linux` are the defaults. Without an\r\ninstalled CLI, use `cargo run -- export /path/to/song.muz -o /path/to/song.dawproject`\r\nfrom the engine checkout.\r\n\r\n## Read the fidelity report\r\n\r\nFor `song.dawproject`, the default reports are `song.dawproject.report.json`\r\nand a readable `song.dawproject.report.txt` beside the archive. Their names replace\r\nthe output extension with `dawproject.report.json` / `dawproject.report.txt`.\r\n`--report PATH` selects a different JSON report path. Keep the report with the\r\narchive when transferring the project.\r\n\r\n`--strict` rejects any export with a fidelity warning and leaves an existing\r\narchive untouched. The report remains available after strict rejection. Missing\r\nrequired assets/plugins, invalid state, and invalid graphs fail export.\r\n\r\nThe report's `entries` are sorted by physical path, code and feature. Each entry\r\ncontains a stable code, severity, source location when available, logical and\r\nphysical paths, affected feature, intended sound or structure, exported behavior,\r\nfidelity outcome and a practical remedy. `required_plugin_ids` identifies the\r\nplugin roles needed to play the handoff. `external_dependencies` names any source\r\ndependencies that remain outside the archive.\r\n\r\nCommon actions include:\r\n\r\n| Report code | Meaning and action |\r\n| --- | --- |\r\n| `SAMPLE_ZONE_OMITTED` | The note is editable, but its pinned sampler recording is omitted. Use native muz for exact pinned selection; re-exporting does not restore it. |\r\n| `SIDECHAIN_MANUAL_SETUP` | The declared detector source is disconnected. Connect and verify the plugin's Detector input in the DAW if available. |\r\n| `SONG_TAIL_MANUAL_SETUP` | Extend the DAW export range by the reported tail duration; the archive does not set that range. |\r\n\r\nIf the host cannot expose the required Detector input, use native muz playback\r\nor recreate the routing and processing externally. `--strict` rejects these\r\nwarning outcomes.\r\n\r\n## Supported data and limitations\r\n\r\n| Feature | Exported representation | Compatibility boundary |\r\n| --- | --- | --- |\r\n| Notes and clips | Editable performed notes | Editing, duplication, save/reopen, and bounce were observed in Bitwig. |\r\n| Note expression | Pitch, pressure, and timbre timelines inside notes | Visible expression survived a note move and had an audible effect; exact curve preservation and native parity remain unverified. |\r\n| Channel controls | Lanes identified by channel and controller, including pedals | CC64's displayed lane was observed. Imported CC11 high/low bounces were identical despite native-wrapper response; use native muz for guaranteed controller behavior. |\r\n| Native DSP | Muz Instrument/Muz FX with code-backed state, including serial/parallel racks | State persistence and relocated embedded-sample audio were observed; exact DSP and pinned-zone parity remain open. |\r\n| Arrangement | Tempo points, meter, authored groups, and section markers | Tempo changes, kit groups, and section labels were observed. |\r\n| Mixer | Tracks, buses, master, output routes, sends, and volume automation | Send level/enabled state and response consistent with a post-fader send were observed; exact tap parity remains unverified. |\r\n| External plugins | CLAP/VST3 identities, effective public values, and available state | ZamEQ2 CLAP loaded with an override; VST3 import remains unverified. |\r\n| Sidechains | Muz FX detector input | Manual connection produced a repeatable audio change; exact source tap, timing, and DSP parity remain unverified. |\r\n\r\n### Native devices and assets\r\n\r\nThe exporter writes editable performed notes, track and bus channels, output\r\ndestinations, sends, tempo points, meter, section markers and authored groups.\r\nStudioSynth, samplers, voice patches and simple built-in effects can be carried\r\nas Muz CLAP instances when their standalone source reconstructs the evaluated\r\ndevice. Required WAV/FLAC samples are embedded by SHA-256 identity, subject to\r\na 32 MiB asset and 64 MiB state limit. State restoration validates the source,\r\nasset digests and device structure. Persistent parameter IDs use DAWProject's\r\nsigned 32-bit range and include default controls. Simple native control\r\nautomation is exported as points; smooth curves are approximated within a\r\n0.001 normalized-value bound and reported as such.\r\n\r\nNative racks retain serial and parallel DSP, exposed realtime controls,\r\nmodulation, mix and latency inside Muz FX. Nested external plugins and sampled\r\nracks are currently rejected from standalone rack state and diagnosed in the\r\nreport. Rack structural settings remain in code-backed state rather than host\r\nautomation.\r\n\r\n### External plugins and automation\r\n\r\nOriginal third-party CLAP and VST3 instances are exported with their identities,\r\neffective parameter values and saved state after source overrides. VST3 state\r\ncurrently includes the component chunk; controller-private state is specifically\r\nreported as omitted.\r\n\r\nPlugin parameter declarations and points use normalized 0–1 values derived from\r\nthe plugin range; typed mixer/send Volume uses linear amplitude. Approximation\r\nwarnings state their value domain and error bound. Structural rack controls are\r\nnot exposed as realtime automation. Embedded native assets are portable;\r\nthird-party opaque state may retain external file dependencies.\r\n\r\nThe report names every device or feature that this implementation omits or cannot\r\nyet verify. Nested external/sampled racks, exact sidechain connections, some expression slots,\r\nsampler zone pins and uninterpreted raw MIDI messages have explicit omissions or\r\nmanual fallbacks in the report. Native FX sound parity,\r\ncomplex routing, exact expression fidelity, controller behavior beyond the diagnosed\r\nCC11 case, and VST3 import remain unverified in Bitwig. A schema-valid archive alone\r\ndoes not establish audible equivalence. These limitations remain part of the\r\ninitial handoff contract, even where bounded probes establish an audible response.\r\n\r\n## DAW setup and troubleshooting\r\n\r\n### Missing plugin or silent instrument\r\n\r\nIf a DAW reports a missing Muz plugin, install the `.clap` library shown above,\r\nrescan CLAP plugins and reopen the project. If notes appear but sound is absent,\r\ncheck the instance state and the report's `required_plugin_ids` and\r\n`external_dependencies`.\r\n\r\n### Connect a sidechain\r\n\r\nIn Bitwig 6.0.11, select the Muz FX compressor in the device panel and click its\r\nsidechain icon in the plug-in header: the small downward-arrow/branching-box\r\nsymbol between the parameter knob button and the search field. This opens\r\n`Select sidechain input`. Choose the source track and the required tap; the probe\r\noffered `kick PRE`, `kick POST` and `kick Muz Out` and selected `kick POST`.\r\nThis is the plug-in's auxiliary-input panel, not the track-input chooser.\r\nCompare detector level, timing and sound with the original Muz render before\r\nrelying on the connection; that comparison remains unverified.\r\n\r\nIn other hosts, first check whether the plug-in Detector input is exposed. If\r\nit is, connect the reported source and verify its tap, timing and sound. If it\r\nis not, use native Muz playback or recreate the routing and processing externally.\r\nKeep the report with the archive when transferring it.\r\n\r\n### Parameter discovery in other hosts\r\n\r\nThe Bitwig profile is the tested target. On its first preset load, Muz suppresses\r\nCLAP parameter rescans because Bitwig reports an initialization restart error\r\nwhen a rescan is sent. Bitwig 6.0.11 enumerated the imported controls and played\r\ntheir automation in the synthetic probe. Other hosts may cache the default\r\ncontrols before loading state; parameter discovery and automation in those hosts\r\nremain unverified.\r\n\r\n## Replace native device source\r\n\r\nTo revise a native plugin's code, extract its `plugins/*.clap-preset` state from\r\nthe archive, write a standalone Muz device expression, then run:\r\n\r\n```sh\r\nmuz devices replace-source old.clap-preset revised-device.muz -o revised.clap-preset\r\n```\r\n\r\nThe command accepts the DAWProject CLAP preset container and preserves its\r\nplug-in ID and framing. It also accepts an older raw Muz JSON state and writes\r\nraw JSON in that case. Replace the same `plugins/*.clap-preset` entry in a copy\r\nof the archive, or load the resulting state through the host's preset/state\r\ncommand. The replacement keeps parameter IDs and current host values for matching\r\nparameter paths. It rejects incompatible source or state before replacing the\r\noutput file. Existing embedded assets remain available; adding new sample files\r\nrequires a fresh export from the Muz project.\r\n\r\n## State and runtime contract\r\n\r\nThese details matter when maintaining integrations or reopening and revising\r\nexported devices. Native internals stay inside Muz Instrument/Muz FX; the export\r\ndoes not bake the whole song or substitute native DAW devices. Unsupported or\r\nunverified semantics receive object-specific report entries.\r\n\r\n### State identity and compatibility\r\n\r\nNative plugin state version 4 (with version 3 read compatibility) stores a standalone generated Muz device expression,\r\nthe evaluated device, role, parameter identities/current values, and embedded\r\nsample bytes identified by SHA-256. The generated expression is authoritative\r\nfor source replacement; load checks that it reconstructs the stored device.\r\nUnrecognized versions and mismatched source or asset digests are rejected.\r\nParameter IDs are stable for each persistent path and checked for collisions;\r\nmatching paths retain their host values when source is replaced. Renaming a path\r\ncreates a new control identity. Revisions to the plugin state format require an\r\nexplicit compatibility update; old state is never silently recompiled under a\r\nnew engine version.\r\n\r\nPlugin state entry names include the full SHA-256 digest of the plugin identity\r\nand state bytes, plus an instance number. Re-exporting changed state therefore\r\nuses a different archive path, avoiding stale state cached by DAWs under an\r\nearlier export's path.\r\n\r\n### Processing and MIDI input\r\n\r\nThe CLAP wrapper reuses native DSP, applies events at sample offsets, and exposes\r\nlatency and tail information. State compilation, asset decoding and processor\r\nconstruction occur outside processing. Invalid processing inputs and capacity\r\nfailures report processing errors; Rust panics are contained at exported ABI\r\ncallbacks. Muz FX has fixed Main and Detector stereo inputs; an unused Detector\r\nis ignored. Host transport cannot reconstruct arbitrary prior effect history.\r\nTransport/fidelity diagnostics therefore remain relevant when seeking or looping.\r\n`SONG_TAIL_MANUAL_SETUP` requires extending the DAW export range by the reported\r\ntail duration; the archive does not set that export range.\r\n\r\nMuz Instrument accepts CLAP notes and MIDI note events. MIDI note-on, note-off,\r\nnote-on with zero velocity, and channel CC messages become native device events\r\nat their sample offsets. Overlapping MIDI notes on the same channel and key\r\nrelease one voice per note-off, oldest first. Other MIDI messages remain raw;\r\nnative Muz instruments do not interpret them.\r\n\r\n### Format baselines\r\n\r\nThe format baseline is DAWProject 1.0 at revision\r\n`ee4dcdde75940f30e14e55401a26955a58b8322b`; the CLAP API baseline is\r\n`a47f6badb49d948fd009998f28309cdab78979c9`.\r\n\r\n## Next steps\r\n\r\nRead [validation evidence](dawproject-validation.md) to assess the tested host\r\nbehavior. Use [native renders](workflow.md#rendering-and-delivery) when the report\r\nidentifies a handoff limitation that matters to your piece.\r\n\r\n## SFZ dependencies\r\n\r\nNative SFZ devices use the Muz instrument plugin state when attached to a\r\nDAWProject. The default linked state retains SHA256-verified dependencies outside\r\nthe project archive and emits `SFZ_LINKED_ASSETS`; the destination must have the\r\nsame library at the saved paths. Explicit `embed_assets: true` packages bounded\r\nassets only when the author has permission to redistribute them. Export does not\r\nimplicitly convert a licensed library into an embedded archive.\r\n\r\nLinked SFZ state uses compact version 4 source/options descriptors and a normalized\r\nprogram fingerprint; restore rebuilds normalized regions only after the complete\r\ndependency closure passes SHA256 verification. This keeps large inherited programs\r\ninside the unchanged 64 MiB state cap without embedding recordings.\r\n\r\nNative linked restore automatically scopes the discovered contrib installation\r\nto its five SFZ asset directories. For a custom library, set `MUZ_SFZ_ASSET_ROOTS`\r\nto an OS path-list of authorized directories before starting the DAW, or supply\r\nan explicitly authorized resolver through the embedding API. Paths inside saved\r\nstate do not authorize filesystem access; symlinks escaping grants are rejected.\r\n","docs/embedding.md":"# Embedding muz\r\n\r\nEmbed the Rust library when your application owns source documents, assets, and\r\naudio output. This guide assumes familiarity with Rust and the\r\n[song/track model](language.md#songs-and-tracks). Keep host UI and browser bridges\r\nin the consuming project.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs embedding`\r\n\r\n## Contents\r\n\r\n- [Build capabilities](#build-capabilities)\r\n- [Host lifecycle](#host-lifecycle)\r\n- [Source loading and compilation](#source-loading-and-compilation)\r\n- [Assets and versions](#assets-and-versions)\r\n- [Validation and preparation](#validation-and-preparation)\r\n- [Editor inspection](#editor-inspection)\r\n- [Playable snapshots](#playable-snapshots)\r\n- [Live revisions](#live-revisions)\r\n- [Native output coordinator](#native-output-coordinator)\r\n\r\n## Build capabilities\r\n\r\nThe default `desktop` Cargo feature includes the CLI, PipeWire output, native\r\nVST3/CLAP hosting, filesystem watching, control socket, and render jobs. Disable\r\ndefault features for the language, compiler, model, inspection, native synthesis,\r\neffects, and audio engine without those desktop dependencies.\r\n\r\nFor example, with the Rust WebAssembly target installed, run from the checkout:\r\n\r\n```sh\r\ncargo check --lib --no-default-features --target wasm32-unknown-unknown\r\n```\r\n\r\nThe portable build rejects native plugin instruments explicitly. It does not\r\nprovide browser audio output itself: the embedding host owns scheduling and\r\noutput buffers. `AudioEngine::render_interleaved` produces PCM at the host's\r\nconfigured sample rate, in blocks no larger than its configured capacity.\r\n\r\n## Host lifecycle\r\n\r\n1. Create a `HostContext` with limits, cancellation, and an asset resolver.\r\n2. Provide a `SourceLoader` and compile the selected source revision.\r\n3. For native output, construct `native::NativeRuntime` on a dedicated coordinator\r\n   thread; prepare, submit, poll, and service it on that same thread.\r\n4. For portable or application-owned output, validate and prepare under the host\r\n   context, then render into host-owned buffers within the configured capacity.\r\n5. Retain accepted and candidate compilations in the host. Promote a native\r\n   candidate only on `NativeEvent::RevisionApplied`; retire old callback objects\r\n   through the coordinator.\r\n\r\nSource compilation, asset decoding, and processor construction belong to\r\npreparation. The host owns path boundaries, asset revision tokens, and presentation\r\npolicy. `NativeRuntime` owns native output scheduling and processor lifecycle;\r\nportable hosts own their output scheduling.\r\n\r\n### Host context\r\n\r\n`host::HostContext` owns expansion/evaluation/graph limits, cancellation and an\r\n`Arc<dyn assets::AssetResolver>`. Use `compile_with_context(path, loader, &context)`\r\nto compile and `context.run(|| AudioEngine::new(...))` (or transaction preparation)\r\nto prepare with the same services. Scopes are synchronous, thread-local and\r\nunwind-safe; explicitly install the context on each preparation thread. They do\r\nnot change audio callback behavior. Independent default contexts do not share\r\ncancellation; CLI constructors retain the process interrupt flag and environment\r\ngraph-budget default.\r\n\r\nThe checked session captures its `HostContext`, including its cancellation token,\r\nasset service and graph budget. Preparing it later uses that captured context;\r\ntelemetry allocates from the resulting engine's `graph_budget()`. Structural\r\ncutovers reject a different budget before mutation. Expansion, graph preparation,\r\nbounded reads and decoding have cancellation checkpoints off the audio thread.\r\n\r\n## Source loading and compilation\r\n\r\n`lang::SourceLoader` supplies module identity resolution, source text, and the\r\ncontrib library root. `lang::load_with_loader` evaluates through that loader;\r\n`compile::compile_with_loader` also lowers and checks the resulting session.\r\nPass an `Rc<dyn SourceLoader>`. A fresh compilation uses a fresh evaluator/cache,\r\nso unsaved revisions are isolated. Imports, dependencies, and cycle detection\r\nuse the same host-provided identities. `FileSourceLoader` preserves ordinary\r\ndesktop behavior. Standard modules remain embedded; `lang::STANDARD_MODULES`\r\nexposes their import names and source text for hosts that want to display them.\r\n\r\nThe host's `resolve` implementation must normalize equivalent paths consistently\r\nand enforce its own filesystem/mount boundaries. Relative imports are passed\r\nrelative to the declaring module. `contrib_modules` optionally provides names\r\nfor missing-module suggestions.\r\n\r\n`lang::classify_root_with_context(path, loader, &context)` uses the same evaluator,\r\nbound `main`/last-expression selection and dependency identities without lowering,\r\nvalidation, asset stamping or processor preparation. `RootClassification` is\r\n`Song { dependencies }`, `NonSong { description, dependencies }`, or\r\n`Unresolved { error }` preserving the original structured evaluation diagnostic.\r\nCancellation and evaluation/expansion budgets return the outer error, never a\r\nconfirmed non-song or a successfully empty scan. A song root means only an\r\nevaluated record with `type == \"song\"`: missing samples/state, unconfigured plugins,\r\ninvalid graphs and unsupported playback policies still fail actual compilation or\r\npreparation. Classification is not guaranteed I/O-free: imports and evaluation\r\nbuiltins such as MIDI use the caller's loader/resolver. Authorize snapshot reads,\r\ntrust and budgets before evaluation; there is no global resolver relaxation.\r\n\r\n## Assets and versions\r\n\r\nAsset resolvers provide normalized identities, `(byte_length, revision_token)`\r\nversions and independently seekable readers. `FileAssets` uses filesystem paths\r\nand weak size/mtime tokens; `MemoryAssets` shares immutable bytes with independent\r\ncursors. MIDI, structural SMF and WAV/FLAC readers use these services. Reads and\r\ndecoded frame counts are bounded. Hosts must normalize paths and enforce mount\r\nboundaries themselves, and change tokens whenever asset bytes change. A scope\r\ndoes not propagate automatically to a child process: desktop render workers use\r\nfilesystem assets. Native plugin loading/state APIs remain desktop-only; an\r\nin-memory resolver does not imply browser plugin support.\r\n\r\n`AssetResolver::snapshot` returns immutable bytes bound to a version. The default\r\nimplementation reads in bounded chunks and rejects metadata changes during the\r\nread; memory assets share immutable storage directly. Hosts must change versions\r\nwhenever content changes. Device preparation also compares the opened version to\r\nthe authored stamp. WAV/FLAC decoding and VST3/CLAP state reads use this byte\r\nservice. Filesystem metadata versions are change detectors, not cryptographic\r\ncontent identities or protection against a writer deliberately restoring metadata.\r\n\r\n`audio_file::load_shared` shares native-rate stereo recordings within a host's\r\nbounded weak cache, keyed by resolver identity, resolved path and version. Each\r\nreader/sampler still owns its playback state; a cache hit still enforces the\r\ncaller's frame limit. Missing, stale, oversized and unsupported assets produce\r\ndistinct errors with the asset path.\r\n\r\nNative plugin aliases resolve their configuration through the active\r\n`HostContext.assets` snapshot, with an 8 MiB limit and config-relative plugin/state\r\npaths preserved. A host must pin the configured file bytes (or explicit `{}` when\r\nthere are no aliases). Resolver `NotFound` means an empty alias map; other grant,\r\nversion, and read failures propagate. There is no fallback disk read that bypasses\r\nthe supplied resolver.\r\n\r\n## Validation and preparation\r\n\r\n`description::ValidatedSession::new` checks an immutable session description\r\nbefore processor construction. `AudioEngine::from_validated` accepts this checked\r\nborrow and prepares audio-configuration-dependent state and external resources.\r\nThe compatibility `AudioEngine::new` entry point uses the same boundary. A checked\r\nborrow does not certify external asset availability or runtime route scheduling;\r\nthose checks still run during preparation.\r\n\r\n`description` owns shared Extras and parameter specifications; `diagnostic` owns\r\nsource-neutral locations/errors. Previous compile/source/lang imports remain\r\nre-exports. The legacy `Device` DTO is accepted through `validate_device`, which\r\nreturns a tagged payload view; `patch_description::ValidatedPatch` checks typed\r\noperations, node edges and configuration-independent ranges. Runtime preparation\r\nstill checks rates, resources, plugin support and sample regions.\r\n\r\nVoice patches cross `patch_description::ValidatedPatch` once per preparation:\r\noperations and outputs are typed, graph references resolve to node indices, and\r\nlifetime, sample budget, module directory and voice mode are checked settings.\r\nControls are exposed separately from structural identity. Runtime preparation\r\nconsumes this representation directly; only recording-dependent regions and\r\nsample-rate-dependent storage remain runtime checks. Source lowering uses the\r\nsame checked conversion as wire descriptions.\r\n\r\n### Scheduled event capacity\r\n\r\nPerformed MIDI schedules are prepared against the candidate's single timeline.\r\nPreparation rejects conservative callback bounds above the fixed event capacity,\r\nincluding expression updates, releases and seek restoration. Revision application\r\nalso checks accumulated held-note obligations before any mutation. Dense material\r\nmay require simpler expression or fewer simultaneous events; events are never\r\nsilently dropped. Expression programs serialize only their actual points;\r\nprepared voice state stays fixed-size on the audio thread. Seek uses per-controller/message binary-search histories and a\r\nprepared interval index for sounding notes, not scans over elapsed score history.\r\n\r\nLegacy loop-pattern schedules are also capacity-checked before playback. The\r\nconservative bound includes repeated onsets/releases within a block, notes held\r\nover multiple cycles, and obligations retained across edits. Ignored out-of-loop\r\nnotes are omitted from the prepared callback schedule. Pattern edits therefore\r\nrequire `PreparedValueTransaction::prepare_with_config`, just like other schedule\r\nedits. Config-free preparation remains available for non-schedule value changes.\r\n\r\n## Editor inspection\r\n\r\n### Locations and diagnostics\r\n\r\n`Compiled::locations` maps keys such as `track.lead`, `device.lead.instrument`,\r\nand `route.lead.out` to the declaration locations already retained by lowering.\r\nThis is declaration attribution, not a complete expansion history of every\r\ngenerated note. Locations serialize their path, one-based line and Unicode\r\ncharacter column, and source excerpt. Browser editors using UTF-16 positions\r\nmust convert character columns to their document offsets.\r\n\r\n`lang::Diagnostic::to_json` exposes the same primary-location selection, help,\r\nand caller locations as terminal diagnostics. Avoid parsing the terminal text\r\nto recover locations.\r\n\r\nGraph validation retains source diagnostics in\r\n`audio::EngineError::Source(diagnostic)`, including unknown automation targets,\r\nlatency-changing targets, and duplicate lanes. Its `Display` remains the source\r\ndiagnostic's terminal display, while `Error::source` exposes the typed\r\n`lang::Diagnostic`. When using `anyhow`, a root `downcast_ref` alone does not\r\nrecover a diagnostic nested inside an engine error; search the source chain:\r\n\r\n```rust\r\nlet diagnostic = error.chain()\r\n    .find_map(|cause| cause.downcast_ref::<muz::lang::Diagnostic>())\r\n    .map(muz::lang::Diagnostic::to_json);\r\n```\r\n\r\n`Diagnostic::named` and `Diagnostic::locate` also retain structured diagnostics\r\nfound in source chains when adding fallback attribution. Keep the structured\r\n`message`, `location`, and `help` fields rather than scraping formatted text.\r\nThe CLI prints the recovered diagnostic once, rather than duplicating its\r\nterminal rendering through the outer engine error and its source.\r\n\r\nNative runtime boundaries preserve the same diagnostic in the public\r\n`NativeError::diagnostic: Option<Diagnostic>` field and expose it through\r\n`Error::source`. Existing `code`, `message`, and `Display` behavior remain\r\nunchanged. Hosts can consume that field directly or use the same source-chain\r\nlookup above; `SubmitRevisionError` also exposes its `NativeError` source.\r\nUnknown automation targets may compile successfully and fail only during\r\n`NativeRuntime::prepare_revision`, so map preparation errors as structured\r\nfailures too, without promoting the rejected candidate.\r\n\r\n### Paged inspection\r\n\r\n`snapshot::SessionSummary::new(session, revision)` provides a bounded status view.\r\nIt retains exact track IDs (rejecting IDs above 1,024 bytes), abbreviates display\r\nnames and titles, and reports truncation after 1,000 tracks. Never use an\r\nabbreviated display label as a lookup identity.\r\n\r\nGiven a compiled revision and its revision number, request a page as follows:\r\n\r\n```rust\r\nlet request = muz::inspect::PageRequest {\r\n    revision: Some(accepted_revision),\r\n    offset: 0,\r\n    limit: 100,\r\n    track: Some(\"lead\".into()),\r\n    start_tick: Some(0),\r\n    end_tick: Some(4 * muz::compile::PPQ as u64),\r\n};\r\nlet page = muz::inspect::page_compiled(\r\n    &compiled, accepted_revision, \"performance\", &request\r\n)?;\r\n```\r\n\r\n`page_session` supports `summary`, `graph`, `patches`, `patch_nodes`,\r\n`patch_detail`, `automation`, `automation_points`, `sections`, `track_groups`,\r\n`performance`, and `performance_overview`. `page_compiled` additionally supports\r\n`score`, `diagnostics`, and `locations`. Responses contain `revision`, `view`,\r\n`rows`, `total`, and `next`; pass `next` as the following offset.\r\n\r\nTrack and tick filters are applied before pagination where meaningful: tick ranges affect score,\r\nperformance, diagnostics, and performance overview, not sections or\r\nsecond-based automation points. An offset past the end returns empty rows and no\r\ncontinuation. A zero limit is an error. A requested revision must match the\r\nretained compilation.\r\n\r\nLimits are 1–1,000 rows and 1 MiB of serialized row payload per page; a single\r\noversized row is an error. Nested patch nodes and automation points have their\r\nown views, separate from summaries. Dense arrangement views should request `performance_overview`, then fetch visible `performance` ranges.\r\nOverview bins include sorted unique MIDI `pitches` overlapping each interval,\r\nso hosts can retain pitch contours and sustained spans without retrieving every\r\nnote. Their time resolution is approximate (at most 128 bins per track/range);\r\nthey are not individually selectable notes.\r\n`notes` counts duration occupancy, not new attacks. Additive `onsets` counts only\r\nnote starts inside each half-open bin and the requested range; kit-hit density\r\nshould use this field rather than infer velocity or count sustained occupancy.\r\n\r\nGraph rows contain compact `transport`, `master`, `bus`, and `track` metadata,\r\nin that order. Transport detail retains `mode` and `meter`, plus `bpm` and\r\n`loop_ticks` for loops or `meter_source` for one-shot playback. Track source\r\nsummaries retain MIDI `ppq` and `end_tick`; outputs and sends retain routing and\r\ngain metadata. Device details expose identity, controls, patch presence, and\r\nplugin identity without plugin state, normalized SFZ programs, sample maps, or\r\npatch bodies. Fetch performed notes, controllers, messages, and tempo changes\r\nthrough `performance`; fetch patch metadata through the patch-family views.\r\n\r\nOnly selected detail rows are materialized; bounded serialization stops before\r\nallocating an oversized encoded row. Counting/filtering still scans the relevant\r\nin-memory collections and is not an incremental index.\r\n\r\n#### Inspection cost and host policy\r\n\r\nThe bounded producer remains scan-based: no revision-owned inspection index,\r\nprecomputed overview store, or whole-track pitch-bound endpoint is retained.\r\nHosts should complete catalog continuations, cache bounded track-filtered pages,\r\ncoalesce navigation requests, and choose a stable pitch scale independently of\r\nthe currently loaded tile. These policies do not require another accepted\r\ncompiler/session or a larger inspection budget.\r\n\r\nQualification used the unchanged workbench default viewport fixture: 18,696 UTF-8\r\nsource bytes, 172 physical tracks, 150 buses and 38,028 notes, with provenance\r\nenabled. Its source SHA-256 was\r\n`652c47b809630cad5a2fb915a6c6db1d2e086782f63aa2579410c749a9e87807`.\r\nThe optimized native producer and corrected Chromium host were measured\r\nseparately; their costs are not interchangeable:\r\n\r\n| Measured boundary | Observed p95 |\r\n| --- | --- |\r\n| Native selected `lane0` performance, beats [64,80), query plus final page serialization | 0.141 ms |\r\n| Native selected overview, largest measured case | 0.512 ms |\r\n| Native complete graph catalog, 324 rows / 108,980 encoded bytes | 3.378 ms |\r\n| Browser selected performance, combined WASM query and serialization | 0.3 ms |\r\n| Browser selected overview, combined WASM query and serialization | 1.0 ms |\r\n| Browser host inspection including queue, worker delivery, parsing and adapter | 7.6 ms |\r\n| Browser structural layout / drawing | 0.5 / 2.9 ms |\r\n\r\nActual browser navigation exercised more than 128 pages; retained cache entries\r\nstayed capped at 128, with peak encoded retention 1,806,659 bytes and at most four\r\nactive requests. Native live Rust heap accounting measured 76,455,389 bytes for\r\nthe retained compilation, 39,470,919 bytes for the session-only baseline and\r\n89,155,079 bytes at compile peak; 40 dropped page/serialization results retained\r\nzero additional bytes. These are allocation-layout measurements, not RSS or\r\nWASM linear-memory capacity.\r\n\r\nThe joint producer/host profile did not identify a material core scan, overview,\r\nor metadata blocker, so no index or producer API expansion was selected.\r\nAll-track stress queries are not the corrected host's visible-track request\r\nshape. These observations are fixture-specific, exclude audio-callback work,\r\nand do not establish an end-to-end frame rate or analysis/display age.\r\n\r\nThe CLI uses the same page envelope and defaults `muz inspect FILE` to `summary`:\r\n\r\n```sh\r\nmuz inspect song.muz --view performance --track lead \\\r\n  --start-tick 0 --end-tick 3840000 --limit 100\r\n```\r\n\r\nThe control socket accepts the same `revision`, `offset`, `limit`, `track`,\r\n`start_tick`, and `end_tick` fields. Its default inspect view is also `summary`.\r\nThe newline protocol wraps the page as `{\"ok\":true,\"result\":PAGE}`.\r\nGraph requests use this page envelope even without filters; they never serialize\r\nthe full session as one row. `inspect::session` returns the compact graph rows as\r\nan array and rejects rather than truncates when continuation is needed. It\r\nretains the existing full automation and section shapes within their row and\r\nbyte limits; performance and patch-family results also use their paginated row\r\nshapes.\r\n\r\n### Expanded track groups\r\n\r\nThe `track_groups` inspection view retains authored groups after lowering;\r\nserialized `Session` snapshots retain them in `extras.track_groups`. A kit\r\nproduces `{id, kind: \"kit\", members: [{track, label}]}`: `id` is the logical track\r\nID, `track` is a physical track ID, and `label` is the original kit voice name.\r\nHosts can group kit lanes without parsing dotted IDs, guessing from pitches or\r\ninstrument names, or losing custom voice labels. Membership is presentation\r\nmetadata; output routing, event streams, and track controls use physical IDs.\r\nEmpty kits have no members. Older snapshots without this optional field deserialize\r\nwith no groups. Source navigation uses `Compiled::locations[\"track.\" + id]` for\r\nboth the group and each expanded voice.\r\n\r\n### Note provenance and revision differences\r\n\r\nEnable `HostContext::provenance` to retain an interned occurrence chain for each\r\nscore note, its definition, and field-specific latest relevant edits. Placement,\r\nrepeat and expansion contexts share parents and are limited to depth 128 under\r\nthe host expansion budget. Imported MIDI explanations identify the resolved asset\r\npath/version, source track and event order, with the import call only as a source\r\nfallback. Provenance is optional and excluded from musical equality and playable\r\nsnapshots.\r\n\r\n`Compiled::explain_notes(track, offset, limit)` returns bounded explanations.\r\n`latest_pattern_call` is a compatibility alias for the latest relevant primitive\r\nedit, as is the newer `latest_edit`; it is not a history of arbitrary returning\r\nwrappers. `field_edits` is the precise field-to-location map and `occurrences`\r\nlists the interned placement path. Identity comes from note keys, not source\r\noffsets: named paths can survive unrelated insertions, whereas positional\r\ncomponents can shift. Renames appear as remove/add and duplicate keys are\r\nreported as ambiguous, never guessed.\r\n\r\n`provenance::diff_page(old, new, category, offset, limit)` pages `notes`,\r\n`metadata`, `occurrences`, `controllers`, `messages`, `tempos`, `performed`, or\r\n`consequences` independently. Note additions/removals and key renames are in\r\n`occurrences`; `notes` contains changed sounding fields. Controller, message and\r\ntempo rows compare ordered streams without inventing event identities. Metadata\r\nnames each changed note or session field. Consequence rows describe the predicted\r\nreconciliation and processor retention/replacement; they do not assert that an\r\napply succeeded. `try_visit_processor_consequences` provides the same processor\r\ndecisions without allocating a complete JSON row vector.\r\n\r\n## Playable snapshots\r\n\r\nOrdinary `Session` serialization deliberately omits imported/performed event\r\narrays. It is an inspection description, not a playable transfer format. Use\r\n`snapshot::PlayableSnapshotV1::capture`, `decode_checked(bytes, byte_limit)` and\r\n`restore_checked` inside the receiving `HostContext`. The decoder honors the\r\nsmaller of the caller's limit and the 256 MiB format maximum. Version 1 requires exactly\r\none performed association per MIDI track, keyed by both track and source IDs;\r\nduplicates, missing/unknown associations, summary mismatches, unordered streams,\r\ninvalid numeric/event buffers, incomplete manifests and stale assets are rejected.\r\nTrack order may change. Snapshots reference assets, not bundle their bytes. A\r\nnon-filesystem host may use `restore_description`, but must validate every manifest\r\nrevision through its own resolver before preparation. Transfers do not promise\r\nfuture bit-identical plugin rendering.\r\n\r\n## Live revisions\r\n\r\n### Prepare and apply\r\n\r\n`PreparedTransaction::prepare` classifies presentation, controls, schedules and\r\nstructural changes. Presentation and compatible native schedule changes construct\r\nno processors. The static control subset is poly synth, gain and voice patch;\r\nother controls conservatively prepare structurally. Automation/tail, resource,\r\nmode and incompatible-source changes remain structural. Apply checks base\r\nrevision, an in-process description signature and prepared configuration before mutation, swaps prepared storage and\r\nleaves retired objects in the transaction for destruction off callback. Use\r\n`prepare_with_config` for direct value transactions changing timelines.\r\n\r\nPortable hosts may pass `None` for the optional `event_started` `Instant`; that\r\nfield is latency telemetry, not preparation correctness. Structural transactions\r\nexpose `needs_fade`, `fade_out`, `fade_in`, and `fade_recovery`. Pass those masks\r\nto `AudioEngine::render_interleaved_with_fade` at the host's block boundary;\r\n`fade_recovery` restores the old engine if a prepared cutover cannot apply.\r\n\r\nCompatible source tempo edits preserve held-note release/expression obligations\r\nat their original remaining wall-clock times. Explicit seek/restart/mode changes\r\nstill create discontinuities. A shortened piece does not immediately cancel held\r\nvoices. No incremental compiler or cross-process capability cache is implied.\r\n\r\n### Temporary listening controls\r\n\r\nFor temporary listening controls, `AudioEngine::set_track_audibility(ids, ramp)`\r\naccepts an exact physical-track allowlist (empty silences all tracks). It gates\r\nboth outputs and pre/post-fader sends after route delay compensation, without\r\nchanging the session, revision, transport, or running voices. `ramp=true` uses a\r\n5 ms transition; `false` initializes the mask immediately. Hosts own mute/solo\r\nand group policies and must reapply the mask after structural transactions.\r\nShared bus tails decay naturally; analysis taps and sidechain detectors remain\r\npre-mask so listening controls do not change musical processing.\r\n\r\n## Native output coordinator\r\n\r\nWith the `desktop` feature, `native::NativeRuntime` is the source-independent\r\nnative output boundary. It consumes borrowed `Session` descriptions, not paths,\r\nsource text, watchers, or an owned `Compiled`. Its public DTOs and exact method\r\nsignatures live in [src/native.rs](../src/native.rs). `RuntimeDeviceStatus` belongs\r\nto `muz::native`; its serialized device fields remain unchanged.\r\n\r\n### Ownership and startup\r\n\r\nCall `NativeRuntime::start(&session, &context, running)` on the plugin coordinator\r\nthread. Public startup attempts real native output and returns an audio error\r\nwhen unavailable; it never falls back to a silent clock or browser engine.\r\nExplicit CLI `--headless` and lifecycle tests use the crate-private backend\r\nconstructor. A headless result is not a hardware or installed-plugin qualification.\r\n\r\nThe runtime and `PreparedNativeRevision` are neither `Send` nor `Sync`. Construct,\r\nprepare, service, poll, discard prepared handles, and shut down on their owning\r\nthread. Keep that thread available between requests for CLAP main-thread work and\r\nreceipt retirement. Preparation/replay may block in foreign plugin code;\r\ncooperative cancellation cannot interrupt a hung plugin. A host needing failure\r\nisolation supervises its own engine process.\r\n\r\nNo runtime or prepared handle borrows the host's `Session` or `Compiled` after a\r\ncall. The host retains its accepted and candidate compilations, inspection data,\r\nsource locations, provenance, and export pins. The runtime retains signatures,\r\nID mappings, listening policy, and owned engine/prepared state, not another\r\npermanent accepted `Session` clone.\r\n\r\nEach startup, preparation, or replay installs the supplied `HostContext::run`\r\non the actual coordinator thread. Clone the accepted resolver, decoded cache,\r\nand budgets for a new operation, but give that operation a fresh cancellation\r\n`Arc<AtomicBool>`. Do not cancel an accepted-session or export token to supersede\r\na candidate. Context scopes do not propagate to other threads automatically.\r\n\r\n### Revision submission and outcomes\r\n\r\nAccepted/runtime revision and source generation start at zero. To rebuild:\r\n\r\n1. Compile a candidate in the host, preserving the accepted compilation.\r\n2. Apply `runtime.plugin_stamp().apply(&mut candidate.session)`.\r\n3. Call `prepare_revision(accepted, candidate, base_revision, source_generation,\r\n   context)`. The accepted signature and revision must match the runtime.\r\n4. Submit the returned owning handle with `submit_revision`.\r\n5. Drain `poll` and promote only its matching `RevisionApplied`. Apply that\r\n   event's `plugin_stamp` to the newly accepted description before another borrow.\r\n   `RevisionRejected` leaves the old description and audio accepted.\r\n\r\nEvery successful submission returns a `RevisionTicket` containing its operation,\r\nbase revision, candidate revision, and caller-supplied source generation. Revisions\r\nadvance only on an applied receipt, including presentation-only and plugin-restart\r\nrevisions. Failed attempts may reuse `base + 1`; operation IDs never repeat.\r\nCounters reject overflow. Source generation is host metadata, not a revision or an\r\nautomatic cancellation counter.\r\n\r\nThere is at most one submitted revision and one owned unsubmitted preparation.\r\nAnother preparation supersedes an older unsubmitted handle, not submitted work.\r\nPreparing against an unacknowledged baseline returns `Busy`; retain only the\r\nlatest queued compile request in the host. `SubmitRevisionError` returns both\r\n`error` and `prepared` on every refusal. In particular, retry `QueueFull` with the\r\nsame handle rather than repeating expensive construction or erasing ownership\r\ninto an `anyhow::Error`.\r\n\r\n`poll(&mut [Option<NativeEvent>])` is nonblocking, writes only empty slots, and\r\nreturns `DrainCount { written, remaining }`. Empty/full slices are safe. Consume\r\nand promote returned revisions before servicing or preparing against the accepted\r\ndescription. Polling also retires callback-owned objects on the coordinator;\r\nit never recompiles or watches source.\r\n\r\nEach admitted revision or control receives exactly one terminal applied/rejected\r\nevent. Reliable outcomes are reserved before admission: one submitted revision,\r\n64 outstanding controls, and one coalesced plugin-restart notice. Capacity\r\nexhaustion rejects synchronously; telemetry never displaces operation outcomes.\r\n\r\nA submitted revision reserves admission until its terminal event is actually\r\nreturned in an empty `poll` destination slot. All controls, including pause/panic,\r\nlistening/observation, loop and prepared transport, synchronously return typed\r\n`Busy` during that boundary; no command, listening change or promised control\r\noutcome is published. Internal receipt collection into a full/empty destination\r\ndoes not release it. The callback's expected-revision guard remains the final\r\nsafety check for deliberately low-level stale operations. Rejections preserve\r\ntheir ticket plus `NativeError.expected_revision` / `observed_revision` when\r\ncallback revision context is available. Hosts own bounded deferred intentions,\r\nsafety-critical ordering and metadata publication beyond the core boundary.\r\n\r\n`cancel_operation` arbitrates with the callback's pending-to-applying transition.\r\n`Prevented` guarantees no mutation and a submitted operation still receives a\r\nrejection. `PendingOutcome` means application may already have started; await the\r\nauthoritative event rather than claim rollback.\r\n`AlreadyResolved` covers undelivered terminal outcomes and the last 64 resolved\r\nidentities; unknown or expired IDs return `UnknownOperation`. A dropped,\r\nnever-submitted handle cancels without a callback outcome. Retain results in the\r\nhost if longer request history is needed.\r\n\r\n`shutdown` consumes the runtime, stops/joins output before reclamation, and\r\nreturns `ShutdownReport { events, status, error }` with final outcomes. Destroy\r\nplugins and retired transactions on the coordinator, not the callback. Drop is\r\na safe reclamation fallback; use explicit shutdown to retain final outcomes.\r\n\r\n### Plugin servicing and status\r\n\r\nCall `service_plugins(accepted, expected_revision)` between operations. It services\r\nCLAP main-thread requests and emits a coalesced `PluginRestartRequested`, keyed\r\nby actual instance tokens. Source work may defer that restart. If callback state\r\nhas advanced before its receipt is promoted, drain events before servicing again.\r\n\r\nUse `prepare_plugin_restart` with the accepted description and the received\r\nrequest, then submit the same prepared-handle type. This temporarily clones and\r\nstamps the accepted Session for preparation; it does not recompile disk or edited\r\nsource, and does not clone the whole Compiled. Restart success advances the\r\nrevision but may keep source generation unchanged. Apply the returned plugin\r\nstamp to the accepted Session before the next borrow, retaining immutable old\r\nexport/diff pins according to host policy. Failure leaves the accepted stamp\r\nunchanged and does not permanently suppress restart flags.\r\n\r\n`status()` reports accepted/runtime/source identities, optional pending revision,\r\ntransport, finite peak/RMS, delivered events, devices, native output health, stream\r\nstarts, and observation drops. When callback state has advanced without its\r\nmatching receipt promotion, `runtime_mapping_pending` prevents old device IDs\r\nbeing attached to new telemetry. Health and callback counters are actual backend\r\nmeasurements, not synthesized success values.\r\n\r\n### Transport and listening\r\n\r\nNative controls return `ControlTicket` on admission; wait for `ControlApplied` or\r\n`ControlRejected` for the callback outcome and transport status. Every control is\r\nguarded by its expected revision. A queued control that becomes stale rejects\r\nbefore mutation. Commands retain FIFO order; audibility and observation changes\r\ndo not invent transport discontinuities.\r\nPrepared transport operations and revision preparation return `Busy` while earlier\r\ncontrol outcomes remain undelivered, including internally collected receipts.\r\nConsume the pause outcome before preparing a dependent seek.\r\n\r\n- `set_running(false)` pauses without rewinding.\r\n- `restart` seeks to the active audition-loop start or zero, preserving playing\r\n  state. Hosts own play-at-end policy and any combined pause/acknowledged-seek\r\n  action they call “Stop.”\r\n- `seek_ticks` uses integer `model::TICKS_PER_BEAT` units, not seconds.\r\n- `set_loop` takes a half-open range with `start < end`. Enabling seeks its start;\r\n  disabling keeps position. Seeking outside an active range clamps to its start.\r\n- `panic` terminates voices; it is not a fabricated rewind.\r\n\r\nSFZ seek/restart/loop preparation replays accepted history off callback with the\r\naccepted asset context and a one-hour frame ceiling. Native controls never use a\r\nbare output seek to bypass required SFZ state. Candidate preparation rebuilds\r\nvalid loop checkpoints before publication. A range past a shortened candidate's\r\nend clears at cutover and is reported in its receipt; replay failure for a valid\r\nrange rejects the candidate, preserving the accepted engine and loop.\r\n\r\n`set_audibility(expected_revision, exact_ids)` validates physical track IDs and\r\nrejects unknown or duplicate IDs. Empty means silence. The initial policy enables\r\nall tracks; an explicit allowlist survives rebuild by ID intersection, leaving\r\nnew tracks silent until the host updates it. The existing 5 ms ramp gates outputs\r\nand pre/post sends after compensation while voices, insert processing, detector\r\nsidechains, and pre-mask analysis continue. The host resolves mute/solo/group\r\npolicy; authored Session controls are unchanged. NativeRuntime reapplies the\r\npolicy to structural and replay replacements **before** replay fills routed effect\r\nhistory, so muted sources cannot reappear as bus/master tails at cutover. A changed\r\npolicy invalidates older prepared handles rather than publishing stale listening\r\nstate. Direct portable `AudioEngine` users retain responsibility for reapplying\r\ntheir own masks.\r\n\r\n### Nondestructive observation\r\n\r\nConfigure `ObservationSelection` through `set_observation`; it is a reliable,\r\nrevision-guarded control. Master capture observes the processed audible mix;\r\nselected tracks are measured after inserts/pan and before routing/listening masks.\r\nCapture never changes output, sidechains, latency compensation, or musical\r\nrevision. Do not use the output-replacing `AudioEngine::set_tap` for live analysis.\r\n\r\nSelect at most 1,000 physical track meters, an optional master meter, and one\r\ndetailed `ObservationTarget::Master` or `Track(id)`. Meter frequency is at most\r\n20 Hz; detail frequency at most `native::MAX_ANALYSIS_HZ` (30 Hz). This is a finite\r\ncandidate ceiling, not a measured callback/IPC/paint performance guarantee. Zero\r\ndisables that stream; hidden/disabled detail stops history work independently of\r\nmeters. Unknown IDs, duplicates, excess selections and invalid frequencies reject\r\nrather than truncate. The meter limit does not cap playable tracks.\r\n\r\n`drain_observations` nonblockingly fills only empty caller slots without draining\r\nreliable events. A preallocated four-slot pool provides bounded latest-wins\r\ndelivery and observable cumulative dropped counts. `ObservationFrame` identifies\r\nrevision, transport generation, capture epoch, strictly increasing sequence,\r\nfinite positive sample rate and running state. Detail appends the selected\r\n`(L + R) / 2` tap on every running callback into preallocated circular history;\r\nonly a fully warmed chronological 2,048-sample window is published. Anti-phase\r\nstereo may cancel under these mono semantics. `sample_count` is actual captured\r\ncount (2,048 for detail), not zero-padding. `sample_position` is the exclusive\r\nwindow end; start is end minus count, in the physical sample-clock domain, not\r\nwall time or score ticks. A meter-only frame has no target/window and count zero.\r\n`meters_present` and optional `meter_sample_position` identify fresh block meters,\r\nwhose position is that hardware block's exclusive end. Independent clocks may\r\ncoalesce the latest meter/detail payloads with distinct boundary positions;\r\ndetail-only delivery must not erase retained meter state.\r\n\r\nRevision, selection replacement, seek/restart/loop discontinuity and pause/resume\r\nreset history and advance `capture_epoch`. Restoration warms a new full window;\r\na hardware block spanning a loop boundary contributes only its post-boundary\r\nsuffix. Reorder/removal preserves physical identities, disables removed detail\r\ntargets and intersects meters by ID. History accumulates through pool stalls,\r\npublishes at most one newest window per callback and never backfills a queue.\r\nPrepared buffers/mappings and retired objects stay off callback. Compute FFT,\r\nwaveform reduction and serialization in the host; an FFT2048 real spectrum may\r\ninclude 1,025 bins with Nyquist. Native playback PCM need not cross app IPC.\r\n\r\nFocused actual-output qualification is reproducible with\r\n`cargo test --test native_observation_qualification -- --ignored --nocapture`.\r\nOn Linux 7.2.8 x86_64 / rustc 1.98.1, a muted actual PipeWire default output at\r\n48 kHz, stereo, requested/negotiated 256 frames delivered 89 full windows in\r\nthree seconds at the 30 Hz candidate setting. Observed arrival p50/p95 was\r\n32.721/38.006 ms; sample-hop p50/p95 was 1,536/1,792 samples. The full window\r\nspanned 42.667 ms, with two observation drops, zero reported render/stream/\r\ntransaction faults and one stream start. Pause/seek/resume invalidation was also\r\nexercised. This is a small synthetic native fixture, not plugin qualification,\r\nend-to-end webview throughput or calibrated capture-to-paint age.\r\n\r\nAn optimized one-off capture-only harness (meters disabled, 48 kHz / 256 frames,\r\nnine repetitions of 30,000 callbacks) measured median 0.00719 microseconds per\r\ncallback for the former sparse 10 Hz copying mechanism, versus 1.11172 for\r\ncontinuous 10 Hz and 1.12391 for continuous 30 Hz. This comparison includes pool\r\npublication under a stalled consumer, not synthesis, hardware callback CPU,\r\nIPC, FFT or paint; it establishes that preallocation does not make continuous\r\ncapture free. Deterministic callback tests separately instrument allocations\r\n**and frees** across capture/replacement, control/revision apply and retirement.\r\nRates and costs must be requalified for the actual host/environment.\r\n\r\n### Source-watching CLI host\r\n\r\n`live::LiveSession` owns the same NativeRuntime, not a second native lifecycle.\r\nIt retains the accepted Session, `.muz`/JSON5 parsing, dependency watch targets,\r\ndebounce, one latest queued source candidate, reload diagnostics, and\r\nwatch-to-callback latency summaries. Ordinary candidates receive the current\r\nplugin stamp before preparation. Plugin restarts use accepted source even when\r\nthe file on disk has an invalid edit, and do not increment watcher generation.\r\nIf admitted controls temporarily block preparation, LiveSession keeps the latest\r\nsource candidate queued and retries after collecting their outcomes.\r\nDeferred plugin restart requests belong to that accepted instance set. A revision\r\ncommit discards its old tokens; surviving plugins' flags are rediscovered against\r\nthe new baseline, so a source commit removing the requester cannot enqueue a\r\nstale-token restart.\r\n\r\nLive transport methods return the admitted `ControlTicket`; socket controls return\r\n`{\"queued\":true,\"operation\":...,\"expected_revision\":...}`, not callback success.\r\nTheir matching `LiveEvent::ControlApplied` / `ControlRejected` retains operation\r\nidentity and authoritative outcome; rejection also updates `LiveEvent::Rejected`\r\nand `last_error`. Ordinary boundary refusal returns typed `busy` / `queue_full`\r\nsocket errors without publishing a control. Status remains actual telemetry.\r\nOnly a matching revision receipt promotes source/watch targets; an older receipt\r\ndoes not erase a newer diagnostic. Policy supersession re-prepares the retained\r\ncompiled candidate after acknowledged outcomes, rather than reporting user\r\ncancellation or restarting output. Socket shutdown is a coordinator lifecycle\r\nrequest, not a pinned panic that could be refused during admission pressure.\r\n`LiveSession::shutdown` forwards the native final-outcome report.\r\n\r\n## Next steps\r\n\r\nThe [workflow guide](workflow.md) shows CLI and socket clients using these\r\nfacilities. For public Rust definitions, start with [host](../src/host.rs),\r\n[native runtime](../src/native.rs), [inspection](../src/inspect.rs), and\r\n[transactions](../src/audio/transaction.rs).\r\nThese APIs expose general host facilities; musical policy belongs in source.\r\n\r\n## SFZ assets and saved state\r\n\r\nNative SFZ compilation stores a normalized `sfz::Program` in `model::SfzConfig`.\r\nThe resolver snapshots mapping sources/includes and samples during preparation;\r\nall dependencies participate in device revision stamps. Host resolvers must\r\nsupply independently seekable readers and stable identities/versions for these\r\nassets, including on WASM where a filesystem resolver is unavailable.\r\n\r\nSFZ `DeviceState` defaults to **linked local assets**. Version 4 serializes a compact source/options descriptor, a normalized-program\r\nSHA256 fingerprint, and the complete SHA256 dependency table, without copying\r\nrecordings or duplicating inherited regions. Restore verifies every dependency\r\nbefore parsing through a resolver restricted to that closure, then compares the\r\nreconstructed normalized fingerprint. Version 3 states remain readable. Missing or changed\r\nlibraries fail with a diagnostic; reinstall the identical licensed assets at the\r\nsaved paths. Automatic relocation is not currently provided. Embedding hosts can restore through\r\n`DeviceState::decode_with_resolver` and `DeviceState::host_context_with_resolver` to provide the saved identities through\r\ntheir own explicitly authorized asset resolver, including in WASM. Native CLAP\r\nand DAWProject restoration authorizes only the five SFZ asset directories under\r\nthe normally discovered contrib installation (`MUZ_CONTRIB_DIR`, checkout, or\r\nXDG installation). Custom libraries require `MUZ_SFZ_ASSET_ROOTS`, a platform\r\npath-list of directories explicitly granted by the user. Serialized paths never\r\ncreate grants; canonical resolution rejects symlinks escaping granted roots.\r\nAn embedding host must independently authorize its resolver before passing it to\r\n`decode_with_resolver`; an implicit default HostContext does not grant native\r\nfilesystem access.\r\n\r\nSet `embed_assets: true` only when redistribution is permitted. Embedding is\r\nexplicit, retains the existing 32 MiB total asset budget and 64 MiB state budget,\r\nand rewrites normalized dependency/sample paths into the host's memory resolver.\r\nLarge libraries require linked state; this option does not grant redistribution\r\nrights. Native and embedded restoration uses the saved normalized program, not\r\nreparsing an original mapping at a machine-specific path.\r\n\r\nEffect racks cannot contain SFZ instruments. State generation rejects this topology\r\nbefore reading or packaging dependencies; save the SFZ instrument separately.\r\n\r\nSFZ graph accounting reports every normalized region, distinct sample dependency,\r\nmodulation declaration and configured voice slot. Regions and sample identities\r\ncost one graph unit each; modulation terms and voice slots cost one per 32 entries.\r\nLarge roots can exceed the default 4096-unit graph budget. Set a deliberate host\r\n`graph_units` limit or `MUZ_GRAPH_BUDGET` (maximum 65536) after inspecting the\r\nreported contributors; loading one root does not count as a single instrument\r\nallocation. `sample_budget_frames` independently bounds shared decoded stereo\r\nframes: the default is 64 Mi frames (512 MiB), and the maximum is 1024 Mi frames\r\n(8 GiB). The original Virtuosity full kit needs about 4.9 GiB. Raise it explicitly\r\nfor a verified library footprint rather than relying\r\non a larger implicit default. Processor SFZ statistics expose decoded frames,\r\nvoice occupancy and steals/drops for host inspection.\r\n\r\nLive SFZ seeks prepare a separate engine by replaying accepted history off the audio\r\nthread, then swap it at a callback boundary. Old processors are retired on the\r\ncoordinator thread. Audition loops capture SFZ voices, DSP, note identities,\r\ncontrollers, keyswitches, sequences and random state at the prepared start; each\r\nwrap restores preallocated state and the event schedule. Effect tails retain their\r\nexisting loop behavior. Authored controller history repeats with the loop; controls\r\nchanged after the checkpoint return to the captured boundary value on wrap.\r\n\r\nReplay is bounded to one hour of project frames per live transport request and\r\nsupports cancellation. While a source revision is pending, transport preparation\r\nreports a retryable diagnostic. Candidate preparation rebuilds active SFZ loop\r\ncheckpoints before cutover; an out-of-range loop is cleared at that cutover,\r\nwhile a valid-range replay failure rejects the candidate.\r\nSeeking outside an active audition range returns to its start; seeking inside\r\nreplays forward from the captured start. Failed or superseded candidates preserve\r\nthe accepted runtime and are destroyed outside the callback.\r\n\r\nWAV inspection exposes `audio_file::Info.compatibility` flags for two verified\r\nPCM container quirks in pinned libraries: zero padding after a PCM `fmt` extension,\r\nand a mono 24-bit `data` size that incorrectly includes its single final zero RIFF\r\npad. Metadata and decoding use the same validated frame range; original bytes,\r\nhashes and sample identity remain unchanged. The decoder checks RIFF/chunk bounds,\r\nbase PCM layout and extension bounds, and rejects actual partial frames, nonzero\r\nextra payload and truncation. These compatibility interpretations run off-thread\r\nunder the existing asset, decoded-frame and cancellation limits.\r\n\r\n\r\nThe metadata-only [state qualification](../contrib/sfz-state-qualification.json)\r\nrecords actual linked roundtrips across all six SFZ families. Large normalized\r\nprograms are represented by compact descriptors: Standard KSOP uses 689,215 state\r\nbytes, METAL Full 754,037, Shinyguitar 214,738, and Darkblack 01 405,066 on the\r\naudited machine. These observations retain the unchanged 64 MiB cap and include\r\nno recordings. See [reproduction instructions](sfz-state-qualification.md).\r\n","docs/getting-started.md":"# Getting started\r\n\r\nCreate and render your first muz project with native instruments. You need no\r\nsamples or plugins for this guide. Commands below run from the `muz-core`\r\ncheckout unless a different terminal is specified.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs getting-started`\r\n\r\n## Contents\r\n\r\n- [Install the CLI](#install-the-cli)\r\n- [Create a project](#create-a-project)\r\n- [Understand the generated song](#understand-the-generated-song)\r\n- [Check, inspect, and render](#check-inspect-and-render)\r\n- [Audition edits live](#audition-edits-live)\r\n- [Next steps](#next-steps)\r\n\r\n## Install the CLI\r\n\r\nThe desktop CLI is exercised on Linux. Building it requires:\r\n\r\n- Rust/Cargo and a native C/C++ build toolchain.\r\n- `pkg-config`, with the ALSA and PipeWire development libraries and headers.\r\n- Clang/libclang for the PipeWire/SPA bindings generated during the build.\r\n\r\nPackage names vary by distribution. A running PipeWire service is needed for\r\nlive playback, but not for offline checks or renders.\r\n\r\nInstall the desktop CLI, CLAP plugin, and contrib pack files. Cargo's binary\r\ndirectory must be on your `PATH`:\r\n\r\n```sh\r\n./install.sh\r\nmuz --help\r\n```\r\n\r\n`install.sh` copies contrib packs to `$XDG_DATA_HOME/muz/contrib` (default\r\n`~/.local/share/muz/contrib`), including any existing checkout assets. It retains\r\nassets already downloaded into that destination on reinstall. It downloads no\r\nsample libraries; follow [pack setup](../contrib/README.md#install-and-import).\r\n`CLAP_DIR` overrides the plugin destination. Plain `cargo install --path .`\r\ninstalls only the CLI; it can use an existing installed contrib tree, or an\r\nexplicit `MUZ_CONTRIB_DIR`.\r\n\r\nAlternatively, build in the checkout:\r\n\r\n```sh\r\ncargo build --release\r\n./target/release/muz --help\r\n```\r\n\r\nIf you choose the second option, replace `muz` in this guide with\r\n`./target/release/muz`. A missing ALSA/PipeWire metadata error points to the\r\ndevelopment packages or their `pkg-config` search path. A missing libclang error\r\npoints to the Clang shared library needed during binding generation.\r\nFor a host without desktop dependencies, see [embedding](embedding.md).\r\n\r\n## Create a project\r\n\r\nChoose a directory for your project. This example uses `~/music/my-song`; muz\r\ndoes not require a particular parent directory, repository, or folder layout.\r\n\r\n```sh\r\nmuz new ~/music/my-song\r\n```\r\n\r\nThis creates `song.muz` and prints its path. Choose an unused project directory:\r\n`muz new` refuses to replace an existing `song.muz`. The project can hold source\r\nmodules and any notes about asset requirements.\r\nThe render commands below use this checkout's ignored `out/` directory; choose\r\nanother output location if you prefer.\r\n\r\n## Understand the generated song\r\n\r\nOpen `~/music/my-song/song.muz`. It contains:\r\n\r\n| Binding | Role |\r\n| --- | --- |\r\n| `theme` | A short phrase, with its last note tagged `echo`. |\r\n| `echo` | A function that derives delay-send automation from those tagged notes. |\r\n| `phrase_section` | A reusable passage with the lead part and its automation gesture. |\r\n| `form` | Two named occurrences, `opening` and `return`; the return edits the tagged note. |\r\n| `main` | The built song, with a native synth, delay bus, master processing, and tail. |\r\n| `delivery` | A named render collection containing a 24-bit master. |\r\n\r\nThe file's final expression is `main`, so ordinary check/render commands use that\r\nsong. `muz batch` can select the named `delivery` collection instead. Functions\r\nand passages are explained in the [language guide](language.md); you can begin by\r\nchanging pitches in `theme` or the song's tempo.\r\n\r\n## Check, inspect, and render\r\n\r\n```sh\r\nmuz check ~/music/my-song/song.muz\r\nmuz inspect ~/music/my-song/song.muz --view sections\r\nmuz render ~/music/my-song/song.muz -o out/my-song/mix.wav\r\n```\r\n\r\n`check` evaluates the source, validates the performance, and prepares the audio\r\ngraph. Errors identify the relevant source location. `inspect` shows the named\r\nsections without playing them. `render` writes a stereo WAV and prints a render\r\nreport; its default output format is 48 kHz float32. Open the WAV in your audio\r\nplayer to hear it. A successful render is sufficient routine verification.\r\n\r\nTo render just the opening or use the generated delivery recipe:\r\n\r\n```sh\r\nmuz render ~/music/my-song/song.muz --section opening -o out/my-song/opening.wav\r\nmuz batch ~/music/my-song/song.muz delivery -o out/my-song/delivery\r\n```\r\n\r\nA section render preserves preceding instrument and effect history. The\r\n[workflow guide](workflow.md#rendering-and-delivery) explains render scopes,\r\ntails, stems, and queued jobs.\r\n\r\n## Audition edits live\r\n\r\nStart the server in one terminal and leave it running:\r\n\r\n```sh\r\nmuz serve ~/music/my-song/song.muz --stopped\r\n```\r\n\r\nIn another terminal:\r\n\r\n```sh\r\nmuz audition opening\r\nmuz status\r\nmuz stop\r\n```\r\n\r\n`audition` loops the named section and starts playback through PipeWire. Edit and\r\nsave the source while the server runs. It watches the source and prepares\r\nrevisions; a failed edit leaves the last accepted session running. Read its\r\nerror, correct the source, and save again.\r\n\r\nWhen finished:\r\n\r\n```sh\r\nmuz shutdown\r\n```\r\n\r\nUse `serve --headless` if you need session inspection and queued rendering without\r\naudio playback. Multiple servers need distinct `--socket` paths, also supplied\r\nto their client commands; see [live sessions](workflow.md#live-sessions).\r\n\r\n## Next steps\r\n\r\n- [Language](language.md): notes, functions, transformations, and arrangements.\r\n- [Workflow](workflow.md): inspection, transport, comparisons, and delivery.\r\n- [Instruments](instruments.md): samples, clips, plugins, and asset setup.\r\n- [Production](production.md): effects, routing, sidechains, and automation.\r\n\r\nRun `muz docs` to find the same guides offline.\r\n","docs/instruments.md":"# Instruments, samples, and plugins\r\n\r\nChoose a sound source for a track, then configure any recordings or plugins it\r\nneeds. This guide assumes the [language basics](language.md). Native synthesis\r\nneeds no external assets; sample and plugin examples require the named local files.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs instruments`\r\n\r\n## Contents\r\n\r\n- [Choose an instrument](#choose-an-instrument)\r\n- [Native presets and kits](#native-presets-and-kits)\r\n- [Samples and zones](#samples-and-zones)\r\n- [Clock-timed clips](#clock-timed-clips)\r\n- [External plugins](#external-plugins)\r\n- [Asset paths and optional packs](#asset-paths-and-optional-packs)\r\n\r\n## Choose an instrument\r\n\r\n| Source | Use it for | External requirements |\r\n| --- | --- | --- |\r\n| `synth(\"glass-lead\")` | A ready-to-play native sound | None |\r\n| `voice_patch(...)` | A programmable native instrument | Recordings only if the patch reads samples |\r\n| `sample(...)` | Pitched recordings or velocity/round-robin maps | WAV or FLAC files |\r\n| `kit(...)` | Named drum or articulation voices | Depends on the voices |\r\n| `plugin(...)` / `piano(...)` | VST3 or CLAP instruments | Installed plugin, any license and preset assets |\r\n| `clip(...)` | A recorded region placed in seconds | WAV or FLAC file; creates its own track |\r\n\r\n## Native presets and kits\r\n\r\n```muz\r\nlet lead = synth(\"glass-lead\", {cutoff_hz: 2800});\r\nlet notes = phrase(\"C4:q E4:q G4:h\");\r\nsong({tracks: [track(\"lead\", notes, lead)]})\r\n```\r\n\r\nPresets include `pulse-bass`, `glass-lead`, `pad`, `choir`, `bell`, `fifths`, and\r\npercussion voices. Their definitions are readable in [std/catalogs](../std/catalogs.muz).\r\nUse `muz devices inspect studio_synth` for native synth controls; see\r\n[synthesis](synthesis.md) for envelope conventions, expression, and custom patches.\r\n\r\nA kit maps semantic voices such as `kick`, `snare`, and `hat` to instruments.\r\nFor example, `kit(\"default\", {snare:sample(\"snare.wav\",{one_shot:true})})`\r\noverrides one voice. Kits expand into physical tracks named from the logical\r\ntrack and voice, such as `drums.kick`. Read [drum performance](performance.md#drums-and-kits)\r\nfor choke groups and voice processing.\r\n\r\n## Samples and zones\r\n\r\n`sample(\"audio.wav\",{root:60,offset:0s,attack_ms:2,release_ms:30})` plays a recording\r\nat the note's pitch. Samples decode mono/stereo WAV or FLAC before playback.\r\nInteger and float WAV files and different sample rates are supported.\r\n\r\nAn array of paths rotates between takes on successive attacks (round robin).\r\nAn array of zone records additionally selects recordings by pitch and velocity:\r\n\r\n| Zone field | Meaning |\r\n| --- | --- |\r\n| `path` | Recording path relative to the declaring module. |\r\n| `root` | The recording's MIDI pitch, including fractional tuning. |\r\n| `keys` | Inclusive MIDI key range; default `[0,127]`. |\r\n| `velocity` | Velocity layer; default `[0,1]`. |\r\n| `offset` | Initial playback offset. |\r\n| `loop` | `[start_seconds,end_seconds]` within the recording. |\r\n| `one_shot` | Whether playback continues after note-off. |\r\n| `gain_db` | Static calibration for this recording. |\r\n\r\n### Note-off and one-shot playback\r\n\r\nA standalone sample follows note-off by default. Inside `kit()`, sample voices\r\ninstead default to `one_shot:true`, so the recording continues after the written\r\nnote ends and `release_ms` does not stop it. When using kit voices for pitched\r\narticulations, explicitly set `one_shot:false` in each sample's options, for\r\nexample `sample(\"guitar.wav\",{root:40,one_shot:false,release_ms:95})`. Explicit\r\nzone settings still take precedence over instrument defaults.\r\n\r\n### Recording calibration\r\n\r\nZone records also accept `gain_db` (−120–120, default 0): a static recording\r\ncalibration captured by each sample voice at note-on. It multiplies the voice's\r\nvelocity response without changing velocity-layer selection, round robins, or\r\nolder releases. `gain_db` in the instrument options remains a shared automatable\r\ncontrol and is **not** inherited as zone gain. Old serialized zones default to\r\n0 dB. Changing zone calibration prepares a replacement instrument, like changing\r\na zone's root or sample path.\r\n\r\nCalibration measurement and target level belong in source/project recipes:\r\n\r\n```muz\r\nfn calibrated(zones, measured_db, target_db) =\r\n    map(range(len(zones)), fn(i) => merge(zones[i], {\r\n        gain_db: target_db - measured_db[i]\r\n    }));\r\n// Original files stay in use; each recording has its own compensation.\r\nlet strings = sample(calibrated([\r\n    {path:\"soft.wav\",velocity:[0,0.5]},\r\n    {path:\"loud.wav\",velocity:[0.5,1]}\r\n], [-30,-18], -24), {root:60,velocity_track:0.8});\r\n```\r\n\r\nThe target level and measurement method are project choices. Zone gain applies\r\nthe compensation during playback, so this recipe needs no derived audio files.\r\n\r\n### Root pitch and fine tuning\r\n\r\n`root` is the recording's MIDI pitch in `[0,127]`, including fractional values\r\nfor fine tuning. For a sample with measured fundamental `f` Hz, calculate its\r\nMIDI root as 69 + 12 log₂(f/440). For a waveform repeated every `n` frames at sample\r\nrate `r`, `f=r/n`. For example, 32 frames at 8,363 Hz need\r\n`root:59.981341609272455`. The sampler preserves that value through compilation,\r\nsession serialization and playback; rounding or truncating it detunes every note.\r\nZone `root` values override the parent sample root; integer roots remain valid.\r\n\r\n### Key and velocity coverage\r\n\r\nGraph preparation (including `muz check`, render and live reload) rejects performed\r\nsampler notes with no matching zone before loading instruments. The diagnostic\r\nnames each affected physical track, its missing-note count, and an example pitch,\r\nvelocity and source key. Keys use the same rounded MIDI key as playback; fractional\r\npitch remains available for tuning. Key bounds are inclusive. Velocity layers are\r\n`[low,high)`, except an upper bound of 1 includes full velocity. Checking uses the\r\nperformed float velocity, not its MIDI-export quantization. Overlapping matching\r\nzones still rotate round robin; this check never remaps notes.\r\n\r\n### Pinning a recording to a note\r\n\r\nTo fix a recording choice to a note, use\r\n`pattern.annotate(\"last\", {sample_zone:2})`. `sample_zone` is a zero-based index\r\ninto the instrument's complete zone list, not the list of matching alternates.\r\nThe selected zone must match the performed key and velocity; invalid indices,\r\nwrong layers and non-sampler destinations fail during compilation. Graph\r\npreparation also validates imported annotations before playback. The annotation\r\nsurvives selection, placement, repeat and lane edits. Keep the zone list order\r\nstable, and reassign choices if transposition or velocity changes invalidate them.\r\nThis is an attack choice, not a continuous expression control; an already sounding\r\nvoice keeps its recording. MIDI export does not encode recording choices.\r\n\r\nUnannotated notes retain the original sampler policy: one counter per instrument,\r\nstarting at zero, advances on every matching attack (including single-zone and\r\nexplicitly selected attacks). It selects counter modulo matching-zone count.\r\nPinning one note therefore leaves subsequent unannotated choices unchanged on the\r\nsame lane. Lane splits can still change unpinned choices; pin the full reference\r\nbefore splitting when all recordings must remain stable.\r\n\r\nThe source recipe `std/sampler.pin_recordings(pattern,zones,clock={})` assigns\r\nround-robin choices in performed attack order. Supply the complete original\r\npattern, explicit zone records and the song timing record; then split the result:\r\n\r\n```muz\r\nuse \"std/sampler\" as sampler;\r\nlet pinned = sampler.pin_recordings(original, zones, {tempo:120});\r\nlet main = pinned.reject(\"tag:solo\");\r\nlet solo = pinned.select(\"tag:solo\");\r\n// Give both lanes sample(zones, options); expression can now differ by lane.\r\n```\r\n\r\nThis recipe is a source policy for a fresh instrument, not a capture of live\r\nsampler state. It requires unique note keys and explicit zone ranges when parent\r\noptions would supply them. It sorts by source performed time, retaining pattern\r\norder for ties; attacks separated only below the compiler's timing precision or\r\nvelocities at floating-point layer boundaries may need explicit choices to\r\nreproduce a prior render. Existing hand-selected choices can be authored with\r\n`map_notes(fn(n)=>{data:merge(n.data,{sample_zone:choice})})` instead. Selection\r\npolicy stays in source; only delivery of the chosen zone to the note-on belongs\r\nto the engine.\r\n\r\n## Clock-timed clips\r\n\r\nThis fragment creates a track containing a recorded region:\r\n\r\n```muz\r\nclip(\"texture\", \"audio.wav\", {\r\n    at: 8s, offset: 2s, duration: 6s,\r\n    fade_in: 100ms, fade_out: 400ms, gain: -12\r\n})\r\n```\r\n\r\n`at` places it in clock time; `offset` trims the start of the recording. Clips\r\nsupport trimming, fades, and sample-rate conversion, but no time stretching.\r\nChange the trim through `clip` options. See the\r\n[language timing rules](language.md#clock-clips) for restrictions on transforming\r\npatterns that contain clips.\r\n\r\n## External plugins\r\n\r\n### Discover and inspect\r\n\r\n```sh\r\nmuz devices list\r\nmuz devices inspect /path/to/Instrument.clap\r\nmuz devices inspect /path/to/Instrument.vst3\r\n```\r\n\r\nInspect the installed plugin for class IDs, parameter IDs/keys, ranges, and ports.\r\nThen declare it in source; these fragments require your own paths and IDs:\r\n\r\n```muz\r\nplugin(\"/path/to/Instrument.clap\", {class: \"plugin.id\", state: \"patch.state\", p123: 0.4})\r\nplugin(\"/path/to/Instrument.vst3\", {class: \"class-id\", state: \"patch.state\", parameter_key: 0.5})\r\n```\r\n\r\n`plugin` can describe an instrument or an effect. If `class` is omitted, the first\r\naudio class is selected. Linux stereo plugins are the exercised layout.\r\n\r\n| Format | Parameter values in muz source |\r\n| --- | --- |\r\n| VST3 | Normalized 0–1, addressed by numeric ID or the inspected key. |\r\n| CLAP | The plugin's plain units; some plugins themselves expose a 0–1 range. |\r\n\r\nFor VST3, `muz devices convert PATH PARAMETER PLAIN_VALUE` uses the controller's\r\nactual plain-to-normalized mapping. CLAP already uses plain values. Automation\r\nuses sample-offset parameter queues; interpolation within the plugin is the\r\nplugin's responsibility.\r\n\r\n### Local aliases\r\n\r\nMachine paths and plugin class identifiers live in\r\n`$XDG_CONFIG_HOME/muz/plugins.json` (normally `~/.config/muz/plugins.json`).\r\n`MUZ_PLUGIN_CONFIG` selects another file. It contains an object of named aliases:\r\n\r\n```json\r\n{\r\n  \"default\": {\r\n    \"path\": \"/chosen/location/Pianoteq.vst3\",\r\n    \"class\": \"the-class-id-from-muz-devices-inspect\"\r\n  },\r\n  \"my-synth\": {\"path\": \"/chosen/location/instrument.clap\"}\r\n}\r\n```\r\n\r\n`piano()` uses the `default` alias; named plugin references can resolve an alias.\r\nExplicit source fields override the alias. Paths relative to the configuration\r\nfile resolve against its directory. Choose and inspect the actual installed\r\nplugin; there is no built-in versioned Pianoteq path. Project state and source\r\nparameter overrides remain project inputs.\r\n\r\nAn alias must point to an installed plugin. `piano()` resolves the `default`\r\nalias; it does not discover a particular Pianoteq version automatically. The\r\n[shared plugin pack](../contrib/plugins/README.md) documents reusable settings\r\nfor specific plugins. Device CLI commands also accept alias names.\r\n\r\n### State and preparation\r\n\r\n```sh\r\nmuz devices state /path/to/Instrument.vst3 -o preset.state\r\n```\r\n\r\n`--load PATH` loads state before saving. VST3 accepts raw component state or a\r\nVST3 preset. Source instruments load state first and then apply parameter\r\noverrides. State loading, parameter inspection, and plugin preparation happen\r\noutside the audio callback. `muz check` prepares the graph and validates available\r\nplugin parameters as well as musical source.\r\n\r\nFor exact named Pianoteq factory presets on Linux 9.2.4, the\r\n[shared Pianoteq capture helper](../contrib/plugins/README.md#headless-factory-preset-capture-linux-924)\r\nexports native VST3 presets using an isolated copy of existing activation\r\npreferences, verifies the requested identity, and loads/resaves through the\r\nplugin before atomically publishing project-owned component state:\r\n\r\n```sh\r\npython3 contrib/plugins/pianoteq-state.py \\\r\n  --preset 'C. Bechstein DG Warm' -o state/bechstein-dg-warm.state\r\n```\r\n\r\nIt retains the selected alias's class (`--class` overrides it); `--plugin`,\r\n`--pianoteq`, `--prefs`, and `--muz` select local inputs. The instrument pack must\r\nbe licensed. Factory settings remain unchanged; author musical overrides in\r\nsource after state loading. Other Pianoteq versions/platforms are unsupported.\r\n\r\nHost restart notifications request a prepared replacement and recalculate latency\r\non the coordinator. Inspect/state commands run in separate muz invocations.\r\nLive plugins run in the host process, so their crashes are not isolated;\r\nbackground bounces run in child processes and cannot publish partial outputs.\r\n\r\n### Ports and expression\r\n\r\nCLAP supports main-thread callbacks, parameter/state inspection, mono/stereo ports,\r\nnative note expression, and MIDI channel input. The stereo main output is used;\r\nauxiliary outputs are discarded and auxiliary inputs are silent. Plugin MIDI/event\r\noutput is not routed.\r\n\r\nVST3 receives floating attack intensity and initial tuning. Subsequent per-note\r\ncurves need a capable native instrument, CLAP native-note port, or a separately\r\nsplit layer. Capable adapters also support channel pressure, poly pressure,\r\nbank/program, and bend. See [per-note expression](performance.md#per-note-expression)\r\nfor controls and destination support.\r\n\r\nThe locally exercised plugins are Pianoteq 9 VST3, Surge XT VST3/CLAP, Surge\r\nXT Effects VST3/CLAP, and sfizz 1.2.3 VST3. This coverage does not guarantee arbitrary plugin compatibility.\r\nOffline exports use the plugin's offline processing mode; see\r\n[render behavior](workflow.md#plugin-render-behavior).\r\n\r\n## Asset paths and optional packs\r\n\r\nAsset paths are relative to the module declaring them. A function body evaluates\r\nin its defining module, so a pack's instrument builder resolves its own samples.\r\nKeep a `plugin(...,{state:...})` call in the module that owns that state path.\r\n\r\nSamples and preset files are watched along with source imports. File length and\r\nmodification time trigger fresh preparation after edits. These are change detectors,\r\nnot content identities or guarantees of reproducible future rendering.\r\n\r\nEach [contrib pack](../contrib/README.md) supplies source mappings, setup instructions,\r\nand licensing/provenance notes. Sample installers place external content in ignored\r\nasset directories. Document the licensed downloads and folder layout in your project.\r\n\r\n`use \"contrib/<pack>/<module>\"` selects `MUZ_CONTRIB_DIR` when set, otherwise\r\nthe executable's checkout `contrib/`, otherwise `$XDG_DATA_HOME/muz/contrib`\r\n(default `~/.local/share/muz/contrib`). An explicit override must exist and never\r\nsilently falls back. `./install.sh` installs the shared tree; no export is needed.\r\nPlain `cargo install --path .` installs only the binary. See\r\n[pack setup](../contrib/README.md#install-and-import) for installed sample downloads\r\nor choosing a different library. Standard `std/` modules are bundled into the\r\nbinary and need no such configuration.\r\n\r\n## Next steps\r\n\r\nUse [production](production.md) to route and process the instrument, or\r\n[synthesis](synthesis.md) to build a voice graph. The [workflow guide](workflow.md)\r\ncovers checking, live reloads, and exports.\r\n\r\n## Native SFZ programs\r\n\r\n`sfz(\"relative/program.sfz\", {max_voices: 256, seed: 0})` prepares an SFZ\r\ninstrument relative to the declaring module. The second argument can provide\r\n`defines: {sample_dir: \"../samples\"}` for mappings requiring externally supplied\r\nmacros. Preparation reads and normalizes the mapping and includes off the audio\r\nthread; malformed or unsupported mappings report diagnostics rather than silently\r\nsubstituting a preset. This constructor is distinct from numeric `sample_zone`\r\nselection: SFZ chooses every matching region through its own mapping semantics.\r\n\r\nPhysical controllers are exposed as `cc0` through `cc127` in MIDI units 0–127.\r\nDefaults come from the mapping; authored options such as `cc1: 100` override them.\r\nThe existing MIDI CC/bend and note-ID expression event paths drive the processor.\r\nSFZ virtual modulation sources above 127 are internal sources, not physical MIDI\r\ncontrollers. Full corpus qualification and reference-player agreement remain\r\nsubject to the acceptance gates in the implementation plan.\r\n\r\nFor verified upstream syntax defects, `source_overlays` can supply narrowly scoped\r\nremovals before parsing. Each descriptor records its mapping `path`, original\r\n`sha256`, exact `removals`, and explanatory `reason`. The importer requires the\r\npinned original bytes and a unique occurrence of each removal. Pack builders use\r\nthese only for malformed tokens a reference player demonstrably ignores; overlays\r\ndo not infer missing opcode values or modify recordings. Saved state preserves\r\nboth these provenance descriptors and the resulting normalized program.\r\n","docs/language.md":"# The muz language\r\n\r\nA `.muz` file builds values: notes and patterns, reusable functions, instruments,\r\nand songs. A file used by `muz check` or `muz render` normally ends with a song.\r\nUse `muz eval` to inspect other values, or export a pattern directly as MIDI.\r\n\r\nStart with [getting started](getting-started.md) for CLI setup. This guide teaches\r\nthe source model; [performance](performance.md) covers expressive timing and\r\n[production](production.md) covers the audio graph.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs language`\r\n\r\n## Contents\r\n\r\n- [A complete song](#a-complete-song)\r\n- [Values, functions, and modules](#values-functions-and-modules)\r\n- [Units and musical time](#units-and-musical-time)\r\n- [Patterns and transformations](#patterns-and-transformations)\r\n- [Selectors, tags, and note data](#selectors-tags-and-note-data)\r\n- [Harmony and pitch](#harmony-and-pitch)\r\n- [Songs and tracks](#songs-and-tracks)\r\n- [Arranging passages](#arranging-passages)\r\n- [MIDI interchange](#midi-interchange)\r\n- [Diagnostics and limits](#diagnostics-and-limits)\r\n\r\n## A complete song\r\n\r\n```muz\r\nlet theme = phrase(\"C4:q D4:e E4:e | [F4 A4]:h r:h\");\r\nlet lead = theme.repeat(2).velocity(0.7);\r\nsong({\r\n    title: \"First phrase\",\r\n    tempo: 120,\r\n    tracks: [track(\"lead\", lead, synth(\"glass-lead\"))],\r\n    tail: 1\r\n})\r\n```\r\n\r\n`phrase` creates a pattern. Transformations return new patterns, so `theme` stays\r\navailable for another variation. `track` assigns the music to an instrument;\r\n`song` assembles tracks and production settings. The final expression is the\r\nfile's result.\r\n\r\n## Values, functions, and modules\r\n\r\n### Bindings and functions\r\n\r\nUse `let` for a binding, arrays for ordered collections, and records for named\r\nfields. Values are immutable. Arrays use zero-based indices; record fields can\r\nbe accessed with a dot or an index.\r\n\r\n```muz\r\nlet pitches = [60, 64, 67];\r\nlet settings = {velocity: 0.7, label: \"lead\"};\r\nfn shifted(notes, semitones = 12) = notes.transpose(semitones);\r\nfn motif(root) {\r\n    let notes = phrase(\"C4:q E4:q G4:h\");\r\n    notes.transpose(root - 60)\r\n}\r\nlet answer = shifted(motif(pitches[0]), semitones = 7);\r\n```\r\n\r\nFunctions use lexical scope and return their last expression. Expression bodies\r\nend with `;`; block bodies can introduce local bindings. Anonymous functions use\r\n`fn(x) => expression`. Defaults and named arguments work with ordinary functions.\r\nAn `if` is an expression: `if x > 0 { x } else { 0 }`. Comments use `//` or\r\n`/* ... */`.\r\n\r\nSingle- and double-quoted strings stay literal even when their contents match\r\nsyntax: `let label = \"if\";`, `[\"}\", \"fn\", \"<eof>\"]` and `{\"let\": \"=\"}` all\r\nwork. Quoted record keys are allowed; bindings and function parameter names use\r\nunquoted identifiers. Formatting preserves string contents and quote spelling.\r\n\r\n### Imports and asset paths\r\n\r\n```muz\r\nuse \"material.muz\" as material;\r\nuse \"std/music\" as music;\r\nuse \"contrib/virtuosity-drums/kit\" as drums_pack;\r\n```\r\n\r\nLocal modules resolve relative to the importing file. `std/` names bundled source\r\nmodules, and `contrib/` names optional instrument setups. The standard prelude\r\nalready exposes common functions and data as bare names; import a module when\r\nyou need its additional helpers or want an explicit namespace.\r\n\r\nA function body evaluates in its defining module. Asset paths therefore follow\r\nthe module that declares the device, even when another module calls its builder.\r\nSee [asset setup](instruments.md#asset-paths-and-optional-packs) for contrib\r\ninstallation and lookup.\r\n\r\nThe [standard library](../std/) is readable `.muz` source. Extend it for reusable\r\nmusical habits rather than copying large event lists.\r\n\r\n### Collections and strings\r\n\r\n`map`, `filter`, `fold`, `sort_by`, `range`, and `len` operate on ordinary values.\r\nArrays and records are shared immutable values; passing them to callbacks does\r\nnot copy their contents.\r\n\r\n`sort_by(list,fn(item)=>key)` is stable and accepts numeric or string keys;\r\nnumeric keys must have compatible units. `range(end,start=0,step=1)` retains exact\r\narithmetic and accepts compatible dimensional bounds and steps. An omitted step\r\nis one in the end value's original unit.\r\n\r\n`merge(a, b, ...)` shallowly combines any number of records, with later records\r\nwinning on duplicate keys. For example, `merge({x:1}, {y:2}, {x:3})` returns\r\n`{x:3, y:2}`. Nested records are replaced as whole values, and inputs remain\r\nunchanged. `merge()` returns `{}`; `merge(record)` returns an equivalent record.\r\nThe first two arguments still accept the names `base` and `overrides`; additional\r\nrecords are positional.\r\n\r\n`index_by(list, function)` builds a record keyed by the string returned for each\r\nitem. It calls the function once per item in list order, retains the original\r\nvalues, rejects duplicate or non-string keys, and returns `{}` for empty input.\r\nFor example, `index_by(pattern.notes, fn(n) => n.key)[key]` retrieves a note.\r\nLike other collections, input is limited to 200,000 items; construction is\r\nO(n log n), with O(log n) dynamic lookup.\r\n\r\n`format(\"layer{}_rr{}.flac\",[layer,rr])` and `str(value)` help construct asset names\r\nand other strings. They do not search or glob the filesystem.\r\n\r\n### Source catalogs\r\n\r\n[std/catalogs](../std/catalogs.muz) provides synth presets, kit/choke defaults,\r\nscale modes, Euclidean rhythms, and control-curve recipes. The prelude exposes\r\nthese as ordinary values and functions; extending it needs no Rust name registry.\r\n`scale(root,mode=\"minor\",octave=4,modes=catalog.scale_modes)` accepts a replacement\r\nmode table. `drums(lanes,span=4b,voices=...,articulations=...,gate=0.5)` also uses\r\nsource tables: the generic `drum_grid` decoder maps arbitrary lane names to\r\npitches and strike symbols to velocities or null for rests. These signatures\r\nshow optional table arguments; replace the ellipses with real tables.\r\n\r\n### Equality\r\n\r\n`==`, `!=` and `contains` compare values recursively, preserving dimensions in\r\nlists and records. Beats/bars, ms/s and Hz/kHz normalize consistently; beats and\r\nseconds never compare equal. Exact numbers compare as rationals, while a pair\r\ncontaining an inexact number uses finite floating-point comparison without an\r\nepsilon. Record source locations do not affect equality. Functions compare by\r\nbinding identity: a copied function equals itself, independently created closures\r\ndo not. Group/random keys retain their separate deterministic canonical encoding.\r\n\r\n## Units and musical time\r\n\r\nA beat (`b`) is a quarter note. Use explicit units to distinguish score time from\r\nclock time and other quantities:\r\n\r\n| Quantity | Examples |\r\n| --- | --- |\r\n| Score time | `1b`, `1/3b`, `2bars` |\r\n| Clock time | `20ms`, `1s` |\r\n| Gain | `-12dB` |\r\n| Frequency | `500Hz`, `1kHz` |\r\n| Scalar | `0.5`, `50%` |\r\n\r\nA literal `1bar` always equals four quarter beats, even in a non-4/4 song.\r\nFor meter-dependent measures, import `std/arrange` and use\r\n`a.measures(count,meter)`, or its alias `a.bars(count,meter)`.\r\nFor example, `a.measures(2,[3,4])` is `6b`. This distinction also applies to\r\nsection and passage durations.\r\n\r\nNumeric fields preserve their documented plain-number defaults: musical time in\r\nbeats, clock time in seconds, `*_ms` in milliseconds, `*_hz` in Hz and gains in\r\ndB. Compatible explicit units are accepted; incompatible units are errors.\r\nMeter, counts, list indices and discrete MIDI fields require integral unitless\r\nvalues before conversion. Fractional musical pitch remains supported. Exact\r\nstretch factors retain rational score time. Plugin normalized controls are scalars.\r\n\r\n### Arithmetic and precision\r\n\r\nSource numeric literals and their arithmetic retain exact rational values. Floating\r\ncalculations such as `sin`, `cos`, and `pow` produce finite inexact\r\nnumbers; arithmetic involving an inexact operand stays inexact. Exact scalar\r\narithmetic that exceeds the rational representation falls back to floating point;\r\nexact dimensional arithmetic reports overflow rather than silently losing timing\r\nprecision. An inexact value used as a musical duration is approximated as a\r\nrational at that boundary. Division by zero and nonfinite results are errors.\r\nThus `1b/3+1b/3+1b/3` remains exactly one beat, while\r\n`0.5-0.5*cos(6.28318*i/64)` composes as an ordinary control calculation.\r\n\r\n`min` and `max` require compatible units and return the selected quantity without\r\nlosing its exactness. `abs`, `floor`, and `round` retain the input unit (`ms` is\r\nnormalized to seconds, so rounding acts on seconds). `sin`, `cos`, and `pow`\r\nrequire scalars. Addition, subtraction, comparisons and remainder require matching\r\nunits; beats and bars interoperate at four quarter beats per bar. Multiplication\r\nrequires at least one scalar; division accepts a scalar divisor or matching units\r\n(the latter yields a scalar). For example `max(1b,2b)+1b` is `3b`, while\r\n`min(1b,1s)` and `1b*2b` are errors.\r\n\r\nScore-time operations report `exact score time overflow` if an onset, duration,\r\nor span cannot fit the exact rational representation. This covers sequencing,\r\nplacement, repeat/fit, slicing, stretching, and reversal. Inexact offsets can\r\nproduce large denominators when converted to score time. Prefer representable\r\nfractions for score offsets, or [displacement](performance.md#coherent-time-displacement)\r\nfor performance offsets in seconds.\r\n\r\nFor example, this offset can overflow after the 32-beat prefix:\r\n`seq([rest(32b),note_on(57,0.5,at=0.025b+2*(0.013b+0.001b*sin(14)))])`.\r\nA representable alternative is\r\n`seq([rest(32b),note_on(57,0.5,at=53b/1000)])`.\r\n\r\n### Clock clips\r\n\r\nClock clips carry dedicated validated timing. `clock_start`, `clock_duration`\r\nand `clock_span` annotation keys are ordinary metadata and cannot alter playback.\r\nPlace or repeat a clip's pattern normally; change its trim through `clip` options.\r\nScore-duration transforms (`slice`, `fit`, `stretch`, `reverse`, or a duration\r\npatch) reject clock clips rather than manipulating a placeholder beat duration.\r\nDirect Rust/serialized musical notes use the optional `clock` payload; legacy\r\ntiming annotations are not inferred as clock timing in new pattern values.\r\n\r\n`pattern.has_clock_timing` is a read-only boolean indicating private clock-clip\r\nnote timing. Public note records retain their existing beat placeholders; this\r\nproperty does not expose or convert that private payload.\r\n\r\n## Patterns and transformations\r\n\r\nA pattern has musical notes, controller events, raw events, and a logical span.\r\nThe span includes intentional silence and determines how sequencing places the\r\nnext pattern. Local patterns can have negative pickup positions; final compiled\r\nevents must be at or after zero.\r\n\r\n### Write a phrase\r\n\r\n```muz\r\nphrase(\"C4:q D4:e E4:e | [F4 A4]:h r:h\")\r\n```\r\n\r\nPitch names specify the note and octave. Square brackets make a chord; `r` makes\r\na rest. Bar lines are visual separators. An `@name` after a note adds a tag.\r\n\r\n| Length | Value in quarter beats |\r\n| --- | --- |\r\n| `w` | 4 (whole note) |\r\n| `h` | 2 (half note) |\r\n| `q` | 1 (quarter note) |\r\n| `e` | 1/2 (eighth note) |\r\n| `s` | 1/4 (sixteenth note) |\r\n| `t` | 1/8 (thirty-second note) |\r\n\r\nDotted and numeric rational lengths also work. Build individual notes with\r\n`note(\"C4\",1b)`, and intentional silence with `rest(duration)`.\r\n\r\n### Combine and transform\r\n\r\n| Operation | Purpose |\r\n| --- | --- |\r\n| `seq([a,b])` | Place patterns consecutively using their spans. |\r\n| `stack([a,b])` | Combine patterns at their current positions. |\r\n| `.repeat(n)` | Repeat material. |\r\n| `.transpose(semitones)`, `.invert(center)` | Change pitches. |\r\n| `.at(offset)` | Shift events and span by a relative beat offset. |\r\n| `.slice(start,end)` | Extract a window and rebase it to zero. |\r\n| `.stretch(factor)`, `.fit(duration)`, `.reverse()` | Transform score time. |\r\n| `.velocity(value)`, `.gain(factor)` | Set or scale note velocity. |\r\n| `.gate(value)`, `.scale_gate(factor)` | Set or scale the held fraction of written duration. |\r\n\r\nThese are pattern transformations; audio gain and effects belong to tracks and\r\ndevices. See [performance](performance.md) for gate, dynamics, timing, and expression.\r\n\r\n### Placement and slicing\r\n\r\nPattern score positions belong to the current pattern value. `.at(offset)` shifts\r\nevery event and the pattern span by that relative offset; it is not absolute\r\nplacement, so applying `.at(16b)` twice adds 32 beats. Place reusable local\r\nmaterial once for each occurrence rather than placing an already-positioned\r\npattern again.\r\n\r\n`.slice(from,to)` reads the current pattern coordinates, keeps material that\r\nintersects the half-open window `[from,to)`, and subtracts `from` so the result\r\nstarts at zero with span `to-from`. Notes crossing a boundary are trimmed;\r\ncontrols and raw events are retained when their onset is inside the window. A\r\nwindow with no events returns a valid silent pattern of the requested span. To\r\nkeep the selected material at its source position, use `p.slice(a,b).at(a)`;\r\nusually, slice reusable local material before placing the occurrence.\r\n\r\n## Selectors, tags, and note data\r\n\r\nTags and annotations keep musical intent attached to notes through reuse:\r\n\r\n```muz\r\nlet marked = phrase(\"C4:q E4:q G4:h\").tag(\"last\", \"echo\");\r\nlet revised = marked.annotate(\"tag:echo\", {purpose: \"answer\"})\r\n    .refine(\"tag:echo\", {velocity: 0.8});\r\n```\r\n\r\n`select` keeps matching notes; `reject` removes them; `refine` patches them.\r\nSelectors include `all`, `first`, `last`, `tag:name`, `voice:name`, arrays for\r\nunions, records for intersections, and predicates such as `fn(n) => n.pitch > 60`.\r\nA bare tag name is also accepted. Use exact note keys for identity; display labels\r\nare not lookup keys.\r\n\r\n`split(pattern,selector)` returns `{selected,remaining}` patterns with the same\r\nspan. Put them in separate tracks to isolate a phrase ending or a voice before\r\nshared mixing. Channel controls stay with `remaining`; add the appropriate\r\ncontrols to the selected layer deliberately.\r\n\r\n`pattern.notes` exposes ordinary note records. The [performance reference](performance.md#score-and-performed-time)\r\nlists their fields and shows how to calculate performed attack/release times with\r\n`seconds_at`. Transform and place the material before deriving final automation.\r\nUse `map`, `filter`, and `fold` to calculate values, or the\r\n[event patch functions](performance.md#custom-performance-policies) to preserve\r\nall untouched event data.\r\n\r\n`sample_zone` is a reserved annotation that selects an absolute zero-based sampler\r\nzone. See [recording selection](instruments.md#pinning-a-recording-to-a-note) for\r\nvalidation and a recipe that preserves choices when splitting tracks.\r\n\r\n## Harmony and pitch\r\n\r\n```muz\r\nlet harmony = chords(\"F#m D A E\", each = 2bars);\r\nlet voiced = voicelead(harmony, low = 48, high = 84, center = 64);\r\nlet accompaniment = arpeggiate(voiced, [0, 2, 1, 2], 1/2b);\r\n```\r\n\r\n`chord(\"F#m7\")` returns pitches; `pitch(\"F#4\")` returns a MIDI pitch.\r\n\r\nPitch text accepts `#`, `b`, `##` and `bb` in `pitch`, `note` and `phrase`,\r\nas well as chord roots and slash basses. Double accidentals shift the named\r\nnatural by two semitones, including across octave boundaries: `C##5` and `Ebb5`\r\nboth sound MIDI 74, `B##4` sounds 73, and `Cbb5` sounds 70. For example,\r\n`phrase(\"[A#4 C##5 E#5 G#5]:q\")` spells A-sharp dominant seventh directly.\r\nThe existing numeric pitch representation and MIDI range checks still apply;\r\npitch display uses its canonical spelling rather than retaining the input text.\r\n\r\n`scale(\"E\",\"harmonic_minor\",octave=3)` returns pitches. Modes include major/minor,\r\nchurch modes, melodic/harmonic minor, pentatonics, and whole tone.\r\n\r\n| Operation | Result |\r\n| --- | --- |\r\n| `degree(key,1)` | The tonic; degree numbers continue across octaves. |\r\n| `diatonic_chord(key,5,voices=4)` | A chord built by stacking thirds. |\r\n| `pattern.diatonic_transpose(key,steps)` | Transposition by scale steps, retaining chromatic inflections. |\r\n\r\n[std/tonal](../std/tonal.muz) supplies melody and progression helpers based on\r\nscale degrees; [std/piano](../std/piano.muz) supplies accompaniment and performance\r\nfunctions.\r\n\r\n### Voice leading\r\n\r\n`voicelead` searches the whole supplied phrase while preserving chord pitch\r\nclasses. It considers inversions, octave placement, common tones, register, smooth\r\nmovement, and a penalty for parallel fifths/octaves. The default search retains\r\n64 candidates per chord, with at most eight voices and 512 chord attacks per call.\r\nIts result is the best path within that bounded set.\r\n\r\nTag a note `fixed` or annotate `{anchor:true}` to pin its pitch. Keep roles and\r\ntags on individual notes to inspect their resulting placement.\r\n\r\nThe `std/tonal.tonal_scoring` record and search wrappers expose register,\r\ncandidate-count, and ranking preferences in source. Candidate generation and\r\nsearch remain bounded native operations.\r\n\r\n### Reharmonization\r\n\r\n`reharmonize(harmony,melody,[\"Em\",\"Cmaj7\",\"Am\",\"B7\"])` chooses chords for\r\nexisting harmonic slots. Held melody duration, metrical position, and root\r\ncontinuity affect its choice. A `fixed` harmony slot keeps its chord symbol;\r\nthe melody stays unchanged.\r\n\r\n`reharmonizations(harmony,melody,palette,count=3)` returns up to five ranked\r\n`{harmony,score}` alternatives. It varies the first unanchored slot and optimizes\r\nthe rest. Bind one result's `.harmony` in source and audition it; selection is\r\nexplicit and the ranking is not a stylistic guarantee.\r\n\r\nUse `muz eval choices.muz` to inspect these values without preparing audio.\r\nSee [tonal-assistance.muz](../examples/tonal-assistance.muz).\r\n\r\n## Songs and tracks\r\n\r\n`song` contains `title`, `tempo`, `meter`, `sections`, `tracks`, `buses`, `master`,\r\n`automation`, and `tail`. A track connects a pattern to an instrument and accepts\r\nproduction options such as gain, pan, inserts, and sends. Unknown song/track fields\r\nare errors. See [production](production.md#signal-flow) for a complete routed example.\r\n\r\n`section(\"chorus\",16bars)` labels the next span in the section list. It does not\r\nplace notes. Place patterns explicitly or use the arrangement functions below.\r\n\r\n## Arranging passages\r\n\r\n### Define and place reusable material\r\n\r\n`use \"std/arrange\" as a;` provides ordinary source records and functions.\r\n`a.passage(span, parts, gestures=[], tempos=[])` holds local material;\r\n`a.part(\"lead\", pattern)` assigns it to a continuing song track.\r\n`a.sequence([a.occurrence(\"verse\", verse), a.occurrence(\"chorus\", chorus)])`\r\nplaces each occurrence using its logical span. `a.group(sequence)` nests an\r\narrangement. Pickups and note/effect tails do not change the sequencing span.\r\n\r\nThe following complete example places a passage twice and changes the second use:\r\n\r\n```muz\r\nuse \"std/arrange\" as a;\r\nlet theme = phrase(\"C4:q E4:q G4:h\");\r\nlet verse = a.passage(4b, [a.part(\"lead\", theme)]);\r\nlet form = a.sequence([\r\n    a.occurrence(\"opening\", verse),\r\n    a.occurrence(\"answer\", a.edit(verse, \"lead\", fn(p) => p.transpose(7)))\r\n]);\r\na.build(form, {\r\n    tempo: 120,\r\n    tracks: [track(\"lead\", rest(0b), synth(\"glass-lead\"))]\r\n})\r\n```\r\n\r\n`a.edit(passage,\"lead\",fn(p)=>...)` changes that value's part, leaving the shared\r\ninput available for other occurrences. `a.require(p,selector,count=1)` diagnoses\r\na pinned selection that no longer matches; a rule such as `\"last\"` intentionally\r\nfollows whichever note is last. `a.build(form, settings, gestures=[])` fills the patterns of\r\nthe declared tracks and generates section labels, tempo points and automation.\r\nThe same track/instrument/effect graph continues across passage boundaries.\r\nThe optional third argument supplies whole-arrangement gesture callbacks, useful\r\nfor policies such as unioning send windows across passage boundaries.\r\n\r\n### Optional span and containment checks\r\n\r\nPassages remain permissive. Opt into logical contracts with\r\n`a.require_span(pattern, expected)` (exact equality, including trailing rests)\r\nor `a.require_fit(pattern, limit)` (logical span at most the limit). Both return\r\nthe unchanged pattern and require a nonnegative beat duration.\r\n\r\n`a.require_contained(passage, pickups=false, tails=false)` adds a deferred\r\nperformed-time contract, checked by `build` before generating gestures with the\r\ncomplete tempo map and final edited part layers. Attacks and control/raw starts\r\nmust precede the passage end; starts before its beginning require `pickups=true`.\r\nKey releases may equal the end, or exceed it with `tails=true`. Tails never permit\r\nlate attacks or controls. Releases mean scheduled key releases, not acoustic\r\ndecay. Containment does not imply logical fit: a long written note with a short\r\ngate can fit in performed time. Empty layers pass. Each duplicate-ID layer and\r\nnested child is checked independently. Clock-timed clip parts are explicitly\r\nunsupported by containment; logical contracts still work on them.\r\n\r\nFor example, `a.require_contained(a.passage(4b,\r\n[a.part(\"lead\", a.require_span(phrase(\"C4:w\"), 4b))]))` checks both contracts.\r\n\r\n### Derive gestures after placement\r\n\r\nGesture functions receive `{name,start,span,parts,timing}` after placement and\r\nafter assembling the full tempo map. `a.material(context,\"lead\")` supplies the\r\nplaced pattern, including its namespaced keys. Derive any automation from those\r\nnotes. After editing a group, child gestures see their own final edited layers,\r\nincluding changed timing, articulation and deleted or replaced notes. This holds\r\nthrough multiple levels of nesting; siblings and other uses of the original\r\npassage remain independent. A gesture must handle an empty selection explicitly,\r\nor use `a.require` when removing its target should fail.\r\n\r\nFor a previously defined `chorus` passage:\r\n\r\n```muz\r\nlet grouped = a.group(a.sequence([a.occurrence(\"inner\", chorus)]));\r\nlet revised = a.edit(grouped, \"lead\",\r\n    fn(p) => p.map_notes(fn(n) => {at: n.at + 1b, velocity: 0.5}));\r\n```\r\n\r\nHere the chorus's note-derived gestures follow the shifted, quieter notes when\r\n`revised` is placed. Edits to a grouped part use times relative to the group and\r\nrun separately on each matching layer. `edit` preserves the part list's slots,\r\nwhich bind layers to child gestures; use it for pattern revisions rather than\r\nmanually reordering or replacing a group's `parts` list. A replacement pattern\r\nuses the same group-relative coordinates as any other edit.\r\n\r\n`a.local(target,points,shape=\"linear\")` moves beat-relative points;\r\n`a.clock(...)` moves a seconds-relative gesture without stretching its offsets.\r\n`a.join` combines same-target gestures in chronological order, requiring the\r\nsame shape and no overlap. Continuous endpoints must agree; conflicting curves\r\nneed an explicit source combination or transition. There is no implicit winner.\r\n\r\nSee [revision-workflow.muz](../examples/revision-workflow.muz) for meter-aware\r\narrangement, a sparse final occurrence, note-derived gestures, and named render\r\ncollections. The starter from `muz new` uses the same arrangement functions.\r\nFor gestures spanning passage boundaries, see\r\n[automation scope](production.md#passage-and-arrangement-gestures).\r\n\r\n## MIDI interchange\r\n\r\n### Import musical material\r\n\r\n`midi(\"part.mid\",track=1)` imports a musical sequence as a pattern, including\r\nchannel data, controllers, and ordinary channel events. Without a track selection,\r\nsynchronous format-0/1 tracks combine. Format-2 sequences require explicit\r\nselection; place independent patterns yourself.\r\n\r\n`midi_tempos(path,track=...)` supplies beat/BPM points for the song's `tempos`.\r\n`notes_only(pattern)` strips other event families when reusing a melody on a\r\ndifferent destination.\r\n\r\n### Export and inspect files\r\n\r\n```sh\r\nmuz midi export song.muz -o song.mid\r\nmuz midi inspect part.mid -o part.json\r\nmuz midi encode part.json -o part.mid\r\n```\r\n\r\n`export` writes multitrack musical MIDI. `inspect` and `encode` expose structural\r\nformats 0/1/2, PPQN/SMPTE division, delta times, and valid opaque meta/SysEx payloads.\r\nStructural conversion does not promise byte-identical encoding. SMPTE files retain\r\nclock structure here; beat-based composition needs an explicit musical tempo\r\ninterpretation.\r\n\r\n### Explicit channel events\r\n\r\nThe following calls return composable event patterns:\r\n\r\n| Call | Value convention |\r\n| --- | --- |\r\n| `note_on(\"C4\",velocity=0.7,at=0b,channel=0)` | Velocity 0–1; channel 0–15. |\r\n| `note_off(\"C4\",at=2b)` | Explicit matching release. |\r\n| `cc(64,90,at=1b)` | Integer controller value 0–127. |\r\n| `bank(0)`, `program(12)` | Bank 0–16383; program 0–127. |\r\n| `bend(-0.2)` | −1 to 1 of the destination's configured bend range. |\r\n| `pressure(0.4)`, `poly_pressure(60,0.4)` | Pressure 0–1. |\r\n\r\n`.channel(2)` moves notes and channel controls together. Conflicting simultaneous\r\nCC values and ambiguous overlapping raw note-ons for the same key are errors.\r\nRaw notes need matching releases and bypass piano allocation.\r\n\r\n`sysex([126,127,9,1])` adds F0/F7 framing around a 7-bit payload.\r\n`meta(type,[bytes])` and `opaque([bytes])` provide structural escape hatches.\r\nRuntime stereo plugin adapters accept ordinary channel events and reject\r\nSysEx/meta/opaque events they cannot consume.\r\n\r\nA file ending in a pattern can be passed directly to `muz midi export`, including\r\nthese events, without an instrument. Direct pattern exports use 960 pulses per\r\nquarter note (PPQ) and interpret millisecond offsets at 120 BPM. Structural JSON\r\nconversion preserves supported SMF timing/division. See\r\n[midi-messages.muz](../examples/midi-messages.muz).\r\n\r\n## Diagnostics and limits\r\n\r\n### Source errors\r\n\r\nEvaluation errors lead with the offending file, one-based line/column and message,\r\nthen display the source line with the expression underlined. Columns count Unicode\r\ncharacters rather than UTF-8 bytes. Nested calls add a compact trace in innermost\r\ncaller order, collapsing repeated calls on the same source line. Imported and\r\nbundled standard modules retain their own source locations, including function\r\ndefaults. Long traces abbreviate middle caller lines while retaining module\r\ntransitions. For example, an invalid `note` call in a helper reports its definition's\r\nline first, followed by the callers that reached it.\r\n\r\nEvery later stage names a location too: parse failures point at the offending\r\ntoken (with the closing `quote`, `*/` or matching bracket spelled out in a hint),\r\nand production failures (lowering, graph validation, automation targets) point at\r\nthe `song`, `track`, `fx`, `sample` or `automation` call that declared the value.\r\nWhere a name is recognizable, the message adds `= help:` lines listing the accepted\r\nunit, field, parameter, effect, module or function names, plus `did you mean ...?`\r\nfor near misses. Hints are mechanical only: they list what the language accepts and\r\nnever choose musical material for you. `muz check --json` carries the same failures\r\nfor scripts.\r\n\r\n### JSON5 session errors\r\n\r\nFor `project.json5` sessions, semantic validation reports the file, line and\r\ncolumn of the failing value, together with its field path. For example,\r\n`params:{cutof_hz:500}` on the third track's instrument reports\r\n`field: tracks[2].instrument.params.cutof_hz`. Array indices are zero-based;\r\nkeys containing punctuation use quoted brackets, such as `params[\"bad.key\"]`.\r\nDuplicate global IDs point at the duplicate declaration and name the first\r\ndeclaration's field path. A missing field points at its containing record;\r\naggregate graph failures point at the relevant collection or project root.\r\nParsing source text through `parse_session_with_root` uses `<project>` as the\r\nfilename. Comments, escaped keys and repeated values do not change field\r\nidentity. JSON5 syntax errors retain their parser-reported locations.\r\n\r\n### Evaluation and expansion budgets\r\n\r\nEvaluation has bounded steps, call depth, and event counts. A failed evaluation\r\nleaves the live session intact.\r\n\r\nPattern expansion preflights each event stream and owned payload before repeat,\r\nfit or aggregation. Defaults are 200,000 notes/controllers/raw events each and\r\n256 MiB of logical event/payload storage, including generated identity strings.\r\nHosts can lower these through `Evaluator::expansion_limits`. Oversized results\r\nproduce diagnostics, never truncated music. These composition limits are separate\r\nfrom realtime simultaneous-voice and per-block event capacities.\r\n\r\n## Next steps\r\n\r\nUse [performance](performance.md) to shape notes, [instruments](instruments.md)\r\nto choose their sounds, and [workflow](workflow.md) to inspect or render the result.\r\n","docs/performance.md":"# Musical performance\r\n\r\nPerformance controls how written notes become timed attacks, releases, and\r\nexpression. Read the [pattern and selector basics](language.md#patterns-and-transformations)\r\nfirst. The transformations here return patterns that you can reuse and assign to\r\ntracks as usual.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs performance`\r\n\r\n## Contents\r\n\r\n- [Score and performed time](#score-and-performed-time)\r\n- [Gate and pedal](#gate-and-pedal)\r\n- [Dynamics and timing](#dynamics-and-timing)\r\n- [Drums and kits](#drums-and-kits)\r\n- [Per-note expression](#per-note-expression)\r\n- [Piano constraints](#piano-constraints)\r\n- [Custom performance policies](#custom-performance-policies)\r\n\r\n## Score and performed time\r\n\r\nPatterns carry exact score positions and written durations, plus performance\r\nmetadata. Transformations preserve metadata and give repeated occurrences distinct\r\nlocal keys. `muz inspect song.muz --view score` shows the writing;\r\n`--view performance --track ID` shows scheduled events. Both use the\r\n[paged inspection interface](workflow.md#inspect-a-song).\r\n\r\n`pattern.notes` is an array of records:\r\n\r\n| Fields | Meaning |\r\n| --- | --- |\r\n| `at`, `duration` | Score position and written duration, in beats. |\r\n| `pitch`, `velocity`, `release`, `gate` | Pitch, attack intensity, release velocity, and held fraction of duration. |\r\n| `offset`, `release_offset` | Performance displacements, exposed as seconds quantities. |\r\n| `hand`, `voice` | Hand assignment (or null) and musical voice label. |\r\n| `key`, `tags`, `data` | Exact identity, tags, and annotation record. |\r\n\r\n`seconds_at(position,timing={})` converts beats/bars using the renderer's tempo\r\ninterpretation; seconds pass through unchanged. Share one timing record with the\r\nsong, for example `{tempo:120,tempos:[[8b,90]]}`. Defaults are 120 BPM and no\r\nchanges. For an exposed note `n`:\r\n\r\n```text\r\nattack  = seconds_at(n.at, timing) + n.offset\r\nrelease = seconds_at(n.at + n.duration*n.gate, timing) + n.offset + n.release_offset\r\n```\r\n\r\nConverted times and performed offsets are finite inexact seconds, preserving the\r\nrenderer's floating-point precision when combined. Source seconds literals stay\r\nexact, and passing seconds through `seconds_at` preserves their exactness.\r\nTransform and place notes before deriving final automation from these records.\r\n\r\n## Gate and pedal\r\n\r\n`.gate(0.6)` holds each key for 60% of its written duration. `.scale_gate(0.5)`\r\nhalves existing gates, preserving articulation differences: gates 0.4 and 0.8\r\nbecome 0.2 and 0.4. Both require a positive finite value and preserve placement,\r\nwritten duration, pedal, and release offsets. Use `.refine(selector,{gate:0.6})`\r\nto set only selected notes.\r\n\r\n`pedal(harmony,depth=0.65)` returns a control pattern. Combine it with notes:\r\n\r\n```muz\r\nlet changes = chords(\"C F\", each = 4b);\r\nlet held = stack([changes.gate(0.7), pedal(changes, depth = 0.65)]);\r\n```\r\n\r\nThe default 30 ms catch repedals at harmonic changes, reduces depth in dense or\r\nlow registers, and releases at phrase end. Override `catch`, set `aware=false`,\r\nor choose controller 66 (sostenuto) or 67 (una corda). Use `cc(64,0,at=4b)` for\r\nan explicit local release, or write all catches as controller patterns.\r\nHalf-pedal sound depends on the destination; a configured Pianoteq instrument\r\nsupports continuous pedal values.\r\n\r\n## Dynamics and timing\r\n\r\n| Transformation | Effect |\r\n| --- | --- |\r\n| `.dynamics(start,end)` | Shape musical intensity across the pattern. |\r\n| `.humanize(timing=4ms,velocity=0.025,seed=1)` | Share most variation within simultaneous groups, with smaller per-note variation. |\r\n| `.rubato(25ms)` | Displace attacks, releases, and controls inside a phrase while anchoring its ends. |\r\n| `.swing(0.58)` | Change subdivision placement. |\r\n| `.voice(\"melody\")` | Mark a musical role so selectors can shape it independently. |\r\n\r\nUse the song's `tempos:[[position,bpm],...]` for a shared ensemble clock.\r\nRubato changes a pattern's performance offsets, without changing that tempo map.\r\nIt guards forward time using a displacement-to-time ratio relative to phrase\r\nlength, including for long phrases with decimal amounts such as\r\n`note(60,48b).rubato(38ms)`.\r\n\r\nPerformance recipes take time quantities such as `4ms`. Humanization is\r\ndeterministic for its key, seed, and stream. Notes tagged `fixed` keep authored\r\nattack timing under humanize, groove, and drum feel; velocity still varies.\r\nRecipes and their timing/velocity weights are editable in [std/performance](../std/performance.muz).\r\nThe source recipes use different noise values from the former native policies;\r\nrepeated evaluation of the same source remains reproducible.\r\n\r\n## Drums and kits\r\n\r\n`drums({kick:\"X...X...\",snare:\"....X...\"},span=1bars)` returns a pattern.\r\nNamed voices include `kick`, `snare`, `hat`, `open_hat`, `crash`, `ride`, and tom\r\nvariants. Grid symbols are:\r\n\r\n| Symbol | Hit |\r\n| --- | --- |\r\n| `X` | Accent |\r\n| `x` | Ordinary |\r\n| `g` | Ghost |\r\n| `1`–`9` | Explicit intensity |\r\n| `.` | Rest |\r\n\r\nRepeat, place, and refine drum patterns like any other material.\r\n`euclidean(hits,steps,pitch=42,span=4b)` creates a Euclidean rhythm. A kit maps\r\nsemantic voices to synth or sample instruments.\r\n\r\n### Drum feel and articulations\r\n\r\n`groove({snare:9ms,hat:-2ms},accents=[1,0.92,1,0.9],grid=1/2b)` applies repeatable\r\ntiming and metrical intensity. `drum_feel(3ms,variation=0.045,seed=1)` adds\r\ncorrelated bar/hit/recovery variation while keeping ghost/accent relationships.\r\n\r\n`flam(\"snare\",spread=24ms,grace=0.5)` adds a softer preparatory hit.\r\n`roll(\"snare\",step=1/8b,to=0.9)` subdivides selected extents with a dynamic rise\r\nand alternating stick annotations. Tag or refine hits to choose articulations\r\nsuch as `rimshot`. [std/grooves](../std/grooves.muz) supplies acoustic and\r\nelectronic starting points.\r\n\r\n### Chokes and voice processing\r\n\r\nKits accept `chokes:[[\"hat\",\"open_hat\",\"pedal_hat\"]]`; that hat group is the\r\ndefault. A hit releases older samples in its group through a short ramp,\r\nincluding one-shots. Matching velocity zones rotate round robin. See\r\n[sample coverage](instruments.md#key-and-velocity-coverage) for exact layer bounds.\r\n`velocity_track:0.2` reduces double attenuation when recordings already contain\r\ndynamic layers.\r\n\r\nA kit voice can carry `{instrument:sample(...),chain:[fx(...)],gain:3,pan:0.1,sends:{hall:-20}}`.\r\nIts gain is relative to the kit track; its chain precedes the track's common\r\nchain. [Kit insert automation](production.md#kit-insert-automation) can control\r\nthose common inserts through the logical track ID.\r\n\r\n## Per-note expression\r\n\r\nExpression attaches controls to a sounding note, independently of overlapping\r\nnotes and release tails. Positions are phases from 0 to 1 of its performed gate.\r\nA constant or a curve works:\r\n\r\n```muz\r\nlet swelling = phrase(\"C4:q E4:q\").express({\r\n    volume: [[0, 0.7], [0.3, 1], [1, 0.6]],\r\n    tuning: [[0, 0], [0.8, 0], [1, 1]]\r\n}, selector = \"last\");\r\n```\r\n\r\n| Control | Range |\r\n| --- | --- |\r\n| `volume` | 0–4 |\r\n| `tuning` | −120–120 semitones |\r\n| `pan` | 0–1; center 0.5 |\r\n| `vibrato`, `expression`, `brightness`, `pressure` | 0–1 |\r\n| Declared custom native controls | 0–1 |\r\n\r\n| Destination | Support |\r\n| --- | --- |\r\n| Preset synth or sampler | Volume, expression, pan, and tuning. |\r\n| Native `voice_patch` | All standard controls; brightness, vibrato, and pressure need explicit graph wiring. Up to 25 declared custom controls. |\r\n| CLAP native-note instrument | The seven standard expression kinds, subject to plugin support. |\r\n| VST3 | Floating attack intensity and initial tuning; subsequent per-note curves need another destination or a split layer. |\r\n\r\nCurves survive repeat, transpose, and placement, and remain with already-sounding\r\nnotes through compatible reloads. Each note allows at most 32 points across all\r\ncontrols. `.express` checks values and curves immediately; destination support and\r\ncustom declaration membership are checked during compilation, including writes\r\nmade through note `data`. Unsupported destinations report the track and instrument\r\nkind.\r\n\r\nNative expression uses a 128-frame control clock and retains the last delivered\r\nvalue through release. MIDI file export quantizes notes and does not encode these\r\ncurves or invent custom-control messages. Explicit raw bend and pressure messages\r\nkeep their independent bytes and timing. See [synthesis](synthesis.md#expression)\r\nfor native mapping and custom lanes.\r\n\r\n## Piano constraints\r\n\r\nOpt in with `track(...,{policy:\"piano\",reach:12,strict:true})`; the policy works\r\nwith any sound source. Tracks without it are unconstrained. Stack all lanes for\r\none player into the same logical track so the checker sees the combined demands.\r\n\r\nThe bounded hand search uses register as a soft preference and preserves explicit\r\n`.hand(\"left\")` / `.hand(\"right\")` choices. It checks held-note range, key count,\r\nspan, repeated depressions, and movement against `reach` and `movement` assumptions.\r\n`strict:true` rejects violations. `.hands(reach=12)` exposes assignment as an\r\nauthoring transformation.\r\n\r\nThe finger search retains eight alternatives and stops at 400,000 transitions.\r\nHeld notes retain fingers; explicit hands and `annotate(selector,{finger:3})` are\r\nanchors. `inspect --view score` shows the assignments. Failure to find an allocation\r\nand exhaustion of the search budget have different diagnostics. Use `fingering:false`\r\nfor span/count/movement checks without finger allocation.\r\n\r\nThese checks model feasibility under bounded assumptions. They do not prove a\r\nfingering is playable and never delete notes. When flagged, shorten finger-held\r\ndurations under pedal, redistribute, roll, or reduce density.\r\n\r\n### Piano preferences\r\n\r\n`std/performance.piano_preferences` owns the hand centers, initial finger positions,\r\nsearch weights and per-finger pitch-class costs. Import it as `perf` and pass\r\n`{playing:merge(perf.piano_preferences,{hand_centers:[50,74]})}` in track options,\r\nor pass `preferences` to `.hands()`. The source `track` helper supplies defaults;\r\nmanual piano track records must supply `playing`. Costs must be scalar values\r\nfrom 0 to 1,000,000; initial positions must be MIDI pitches 0..127. Default thumb\r\ncosts cover all five black-key pitch classes. Preferences rank allocations;\r\nexplicit hand/finger anchors, held-note constraints and bounded search remain\r\nnative. Existing reach and movement checks still report infeasible results.\r\n\r\n## Custom performance policies\r\n\r\n`std/performance` owns `scale_gate`, `dynamics`, `humanize`, `groove`, `drum_feel`,\r\n`rubato`, `flam`, `roll`, and `pedal`. The source prelude exposes these as global\r\nfunctions and pattern methods. Import the module to use or adapt its helpers:\r\n\r\n```muz\r\nuse \"std/performance\" as feel;\r\nlet shaped = phrase(\"C4:q E4:q\").map_notes(fn(n) => {\r\n    duration: n.duration * 3/4,\r\n    release_offset: n.release_offset + 2ms\r\n});\r\nlet main = feel.displace(shaped, fn(at) => sin(at / 1b) * 5ms);\r\n```\r\n\r\n### Sparse event patches\r\n\r\nA pattern exposes `.notes`, `.controls`, `.raw` and `.span`.\r\n`map_notes(pattern, callback, selector=\"all\")` invokes the callback once per\r\nselected note and applies the returned sparse record as a patch. Omitted fields\r\nremain exactly as authored. Returning `null` drops a note.\r\n`filter_notes(pattern, callback)` keeps notes for which the callback is true.\r\n`flat_map_notes(pattern, callback, selector=\"all\")` expects a list of patches;\r\nan empty list drops a note and multiple patches create multiple notes. An\r\nunselected note is unchanged. Selectors accept the same tags, voices, records,\r\nunions and predicates as `select`.\r\n\r\nNote fields are `at`, `duration`, `pitch`, `velocity`, `release`, `gate`, `offset`,\r\n`release_offset`, `hand`, `voice`, `key`, `tags`, and `data`. The two offsets are\r\nseconds quantities when read, and patches also accept scalar milliseconds.\r\n`offset_ms` and `release_offset_ms` are scalar patch aliases. A patch to `data`\r\nor `tags` replaces that field; use `merge(n.data, {...})` or `n.tags + [\"tag\"]`\r\nto retain existing contents. `hand: null` removes a hand assignment.\r\n`refine(selector, callback)` accepts sparse callback patches with the same\r\nfields, alongside its original constant record form.\r\n\r\n### Identities and expansion\r\n\r\nSingle-patch transformations preserve the original key. Expansion automatically\r\nuses `original/expand0`, `original/expand1`, etc. unless the patch supplies an\r\nexplicit `key`. For an ornament that retains its principal note, return its\r\noriginal key explicitly. `overlay(patterns)` combines already namespaced\r\npatterns without positional key prefixes and rejects duplicate note identities;\r\nuse `.at(position, key=\"occurrence\")` to namespace occurrences before overlay.\r\n\r\n### Controllers and raw events\r\n\r\n`map_controls` / `flat_map_controls` apply patches to `at`, `offset`, `controller`\r\nand `value`. `map_raw` / `flat_map_raw` apply patches to `at`, `offset` and `bytes`.\r\nAll map functions accept `null` to remove an event; flat maps accept empty arrays.\r\nThey preserve other event families and the authored span, including trailing\r\nsilence. `control(controller, value, at=0b, offset=0ms)` constructs a channel-relative\r\nCC event (including pedal); `cc` remains an explicitly channel-addressed raw event.\r\n\r\nCallbacks execute under the evaluator's existing step/depth bounds. Results are\r\nvalidated, and each event family is limited to 200,000 events. Invalid fields,\r\nMIDI values, or nonpositive note durations fail at the transformation. Reusable\r\nfragments may have negative local onset coordinates for pickups; final compiled\r\npatterns must have nonnegative score coordinates.\r\n\r\n### Coherent time displacement\r\n\r\n`displace(pattern, function)` takes a function from score position to a duration\r\nin seconds. It evaluates the displacement at note-on and gated note-off separately,\r\nand at every control/raw event. The release correction accounts for the onset\r\nshift already applied. This keeps matching note releases and pedal releases\r\naligned. `rubato` is a sinusoidal displacement recipe with a forward-time bound;\r\ncustom displacement functions must preserve the intended event ordering.\r\n\r\n### Deterministic noise and grouping\r\n\r\n`keyed_noise(key, seed=0, stream=0)` returns deterministic noise in `[-1,1]`.\r\nKeys and streams may be strings or compound source values. Distinct streams\r\nallow independent velocity and timing variation without positional randomness.\r\n`group_by(list, callback)` groups equal callback keys, preserving first-group and\r\nwithin-group order. `keys(record)` exposes record field names. Pedal policy uses\r\none grouping pass instead of scanning the harmony once per chord; its register,\r\ndensity and catch choices are ordinary source expressions. Piano hand/reach and\r\nvoice-leading solvers remain efficient kernel machinery.\r\n\r\n### Neighbor-aware note policies\r\n\r\n`std/patterns.map_note_runs(pattern, function, run=fn(n) => n.voice)` supplies\r\ncontext for source performance rules. The callback receives\r\n`{note, previous, next, run, index, count}` and returns a sparse note patch or\r\n`null` to drop, as with `map_notes`. Boundaries are `null`. Runs are visited in\r\nfirst-occurrence order, with stable score-onset sorting within each run. Equal\r\nonsets retain original order; second-valued offsets do not change adjacency.\r\nUnvoiced polyphony forms one run with deterministic neighbors, not inferred\r\nmelodic strands. Assign voices or supply a custom grouping function (including\r\ncompound keys); a constant key requests a global run.\r\n\r\nThe grouping callback runs once per original note. All contexts come from the\r\nimmutable input, so earlier onset, voice or key edits and drops cannot change\r\nlater neighbors. Results are applied in original native order through\r\n`map_notes`, preserving omitted fields, controls, raw events, trailing silence\r\nand hidden clip payloads. Empty material invokes neither callback. Collection\r\nwork is O(n log n), excluding callback cost, with O(n) intermediate storage.\r\nFor example:\r\n\r\n```muz\r\nuse \"std/patterns\" as p;\r\nlet linked = p.map_note_runs(phrase(\"C4:q D4:q E4:q\"), fn(c) => {\r\n    gate: if c.next == null { 0.8 } else { 1 }\r\n});\r\n```\r\n\r\n## Next steps\r\n\r\nDerive [production automation](production.md#deriving-automation-from-notes) from\r\nperformed notes, or [inspect and audition](workflow.md) the result. General source\r\nhelpers also live in [std/music](../std/music.muz) and [std/patterns](../std/patterns.muz).\r\n","docs/production.md":"# Production: routing, effects, and automation\r\n\r\nConnect instruments to effects, buses, and the master output. This guide assumes\r\nyou can build a [song and tracks](language.md#songs-and-tracks). For instrument\r\nsetup, see [instruments](instruments.md); for audio exports, see\r\n[workflow](workflow.md#rendering-and-delivery).\r\n\r\n[Documentation index](README.md) · Offline: `muz docs production`\r\n\r\n## Contents\r\n\r\n- [Signal flow](#signal-flow)\r\n- [Native effects](#native-effects)\r\n- [Sidechains](#sidechains)\r\n- [Parallel racks and modulation](#parallel-racks-and-modulation)\r\n- [Automation](#automation)\r\n- [Resource limits](#resource-limits)\r\n\r\n## Signal flow\r\n\r\nA track connects a pattern to an instrument. Its `chain` processes the instrument\r\noutput in order; pan follows the inserts. The output fader (`gain`, in dB) feeds\r\nthe track's output bus. Buses also have a chain, output, and sends. `master` is the\r\nfinal chain.\r\n\r\n```text\r\ninstrument → inserts → pan ─┬→ output fader ─┬→ output bus → master\r\n                           │                └→ post-fader sends\r\n                           ├→ pre-fader sends\r\n                           └→ track tap / sidechain detector\r\n```\r\n\r\nHere is a complete native-instrument example:\r\n\r\n```muz\r\nsong({\r\n    tempo: 120,\r\n    tracks: [track(\"lead\", phrase(\"C4:q E4:q G4:h\"), synth(\"glass-lead\"), {\r\n        gain: -3,\r\n        pan: 0.1,\r\n        chain: [fx(\"eq\", {frequency_hz: 2400, gain_db: 2, q: 0.7})],\r\n        sends: {hall: -15}\r\n    })],\r\n    buses: [bus(\"hall\", [fx(\"reverb\", {mix: 1})])],\r\n    tail: 3\r\n})\r\n```\r\n\r\nSends follow the output fader by default: `sends:{hall:-18}`. Use\r\n`sends:{hall:{gain:-18,pre:true}}` to tap before that fader. Both taps include\r\ninserts and pan. Output-fader automation therefore changes post-fader sends.\r\nA solo audition keeps muted sidechain sources processing.\r\n\r\nBus feedback loops and sidechain dependency cycles are errors. For intentional\r\nfeedback, use a delay processor's bounded internal feedback.\r\n\r\n## Native effects\r\n\r\nThe engine supplies EQ, lowpass, highpass, compressor, limiter, delay, reverb,\r\nchorus, gate, bitcrusher, drive, gain, and stereo effects. Inspect a device for\r\nits current controls and ranges:\r\n\r\n```sh\r\nmuz devices list\r\nmuz devices inspect eq\r\n```\r\n\r\n### Delay timing\r\n\r\nNative `delay` accepts `time_ms` for fixed clock timing, for example\r\n`fx(\"delay\", {time_ms:11.7, feedback:0.2, mix:0.15})`. Positive values up to\r\n48000 ms select clock timing and remain fixed across tempo changes. Durations\r\nround to the nearest sample, with a minimum of one sample. `time_ms:0` (the\r\ndefault) selects `time_beats`, whose range is 0.03125–16 beats and default\r\nis 0.5. A positive `time_ms` takes precedence when both controls are present;\r\nsetting it back to zero also switches live playback/automation back to beat timing.\r\nBoth modes share a 48-second buffer; changing modes allocates no memory\r\nin the audio callback. Short body resonances and doubling can be composed with\r\nordinary inserts, racks or sends:\r\n\r\n```muz\r\nfn body(ms) = fx(\"delay\", {time_ms:ms, feedback:0.15, mix:0.12});\r\nlet resonances = [body(11.7), body(17.3)];\r\n// Use {chain:resonances} on a track, regardless of the song's tempo.\r\n```\r\n\r\n### Amplitude quantization and sample-rate reduction\r\n\r\n`fx(\"bitcrusher\",{bits:10,rate_hz:16000,mix:0.5})` combines two independent\r\noperations. `bits` ranges from 0 to 24 (default 0, quantization off); positive\r\nvalues round to amplitude steps of `2^(1-bits)`, referenced to full scale ±1.\r\nFractional values allow gradual resolution changes. Quantization does not clip\r\nsignals above full scale or add dither. `rate_hz` ranges from 0 to 192000\r\n(default 0, sample-and-hold off); rates at or above the engine rate also capture\r\neach sample. Lower rates capture both stereo channels on one shared clock and\r\nhold their individual values until the next capture. Noninteger ratios alternate\r\ncapture intervals deterministically, independent of render block size.\r\n\r\n`mix` is 0–1 (default 1); 0 is exact dry bypass while the internal clock continues.\r\nParameter updates preserve hold state and normalized clock position; transport\r\nreset clears it and captures the first new sample immediately. This zero-latency\r\neffect intentionally adds quantization noise and aliasing, with no implicit\r\nfiltering or console emulation. Put an explicit lowpass before/after it to shape\r\nthe result; choose resolution and filtering per sound in source.\r\n\r\n## Sidechains\r\n\r\nA sidechain uses one track's audio to control another processor. For example,\r\nthis insert fragment uses the physical kick lane as a compressor detector:\r\n\r\n```muz\r\nfx(\"compressor\", {\r\n    id: \"duck\", sidechain: \"drums.kick\", threshold_db: -25,\r\n    ratio: 5, attack_ms: 3, release_ms: 130\r\n})\r\n```\r\n\r\nAn external `sidechain:\"kick\"` reads the source track **after all inserts and\r\ntrack pan, before its output fader, sends, and downstream bus/master processing**.\r\nThis is the same signal boundary as `render --tap kick` or a dry track stem;\r\n\"dry\" here still includes inserts and pan. The detector is latency-aligned with\r\nthe receiving processor. A sidechain names a physical track (`kit.voice` for a\r\nkit lane), and the same tap feeds compressors and rack followers on tracks,\r\nbuses, or master.\r\n\r\nChanging `kick.out` (the track's `gain`, including automation) changes its audible\r\noutput and post-fader sends, but leaves the detector unchanged. Instrument gain,\r\ninsert effects/gain, and pan affect both the detector and routed audio. The\r\ncompressor and rack follower detect `max(abs(left), abs(right))`, then apply\r\ntheir attack/release smoothing: pan can therefore change detector level even\r\nwhen stereo power is preserved. Soloing the receiving track keeps the sidechain\r\nsource processing while muting that source's output and sends.\r\n\r\nUse an ordinary gain insert to set detector level, and the output fader to set\r\naudible level. For example:\r\n\r\n```muz\r\ntrack(\"kick\", phrase(\"C2:q\").repeat(12), synth(\"kick\"), {\r\n    chain: [fx(\"gain\", {id:\"key_level\", gain_db:0})],\r\n    gain: -12\r\n})\r\n```\r\n\r\nLowering `kick.out` to −30 dB makes the kick quieter with the same ducking.\r\nSetting `kick.key_level.gain_db` to −12 dB and `kick.out` to 0 dB instead keeps\r\nthe original audible kick level while reducing detector level by 12 dB. This\r\ncompensation assumes no other gain-dependent processing between the insert and\r\noutput; sends still obey their own pre/post-fader rules. The runnable\r\n[sidechain level example](../examples/sidechain-levels.muz) automates these three\r\nstates over a held bass. Render `--tap kick` to measure the detector source,\r\n`--tap bass` to measure ducking, or `--solo bass` to hear it through production.\r\n\r\n## Parallel racks and modulation\r\n\r\nA rack runs serial effect branches in parallel, aligns their latencies, sums them,\r\nand mixes the result with an equally delayed dry input. This fragment uses two\r\nbranches:\r\n\r\n```muz\r\nrack([\r\n    [fx(\"lowpass\", {cutoff_hz: 800}), fx(\"gain\", {gain_db: -6})],\r\n    [fx(\"highpass\", {cutoff_hz: 800}), fx(\"gain\", {gain_db: -6})]\r\n], {id: \"parallel\", mix: 0.4, gain_db: 0})\r\n```\r\n\r\nAn empty branch is a dry path. Set branch gains explicitly when summing several\r\nfull-level branches. A rack has at most eight branches and 32 devices. Build\r\nreusable racks with ordinary functions and compose branch arrays in source.\r\n\r\n`expose:{tone:\"0.0.cutoff_hz\"},tone:1200` exposes a control by branch index,\r\ndevice index, and parameter name. On a track named `lead` with rack ID `parallel`,\r\nthat control is addressed as `lead.parallel.tone`.\r\n\r\nRack `modulate` entries name an internal target and calculate:\r\n\r\n```text\r\nbase + depth*sin(2π*rate_hz*t) + follower*envelope\r\n```\r\n\r\nThe result is clamped to explicit `min`/`max`. The envelope follows the rack input\r\nor its external `sidechain` track, using `attack_ms`/`release_ms`. Exposed setters\r\nand modulators cannot compete for one target. Latency-changing controls cannot\r\nbe exposed or modulated this way.\r\n\r\nSee [std/mix](../std/mix.muz) and the [rack example](../examples/racks.muz)\r\nfor tremolo, envelope filters, ducking, gated spaces, and split-band processing.\r\n\r\n## Automation\r\n\r\nAn automation lane connects a target to a curve. Device targets use explicit IDs\r\nand parameter names, such as `lead.instrument.cutoff_hz`. Route targets include\r\n`lead.out` and `lead.send.echo`. Put lanes in the song's `automation` list:\r\n\r\n```muz\r\nautomation(\"lead.instrument.cutoff_hz\", curve([[0b, 500], [16b, 3500]], \"smooth\"))\r\n```\r\n\r\nCurve positions use beats or seconds; values use the target parameter's units.\r\nShapes are `linear`, `smooth`, and `step`. Points must be nonnegative and strictly\r\nincreasing. One lane owns each target. Lookahead and other latency controls\r\nrequire a prepared source edit.\r\n\r\nCurve sampling preserves value dimensions: interpolation between `1kHz` and\r\n`2000Hz` returns Hz. All values must have compatible dimensions; beat/bar values\r\nnormalize to beats. Native parameter descriptors declare units and whether a\r\nchange updates a control or requires structural preparation.\r\n\r\n### Curves and combinations\r\n\r\n`lfo(period,duration,low=0,high=1,phase=0)` constructs a cosine curve with 64 points\r\nper cycle. `curve_at(curve,offset)` places a local envelope. `curve_map(curve,fn(x)=>...)`,\r\n`curve_add(a,b)`, and `curve_mul(a,b)` combine curves before audio processing.\r\nTheir default sampling resolution is 1/64 beat, or 1/64 second for clock curves;\r\nsupply `resolution` for sharper shapes. Playback interpolates the prepared\r\npoints at audio sample positions.\r\n\r\n`curve_value(curve,position)` evaluates one position or a list of positions.\r\n`unit(quantity)` returns one in its dimension. Source curve-combination helpers\r\nretain original knots and guard points at step edges. Their sampling policy can\r\nbe changed in source without changing the interpolation kernel.\r\n\r\n### Kit insert automation\r\n\r\nAn insert in a kit track's `chain` can use the logical track ID. Compilation\r\nbroadcasts its lane to every voice with hits in that track:\r\n\r\n```muz\r\nsong({\r\n    tracks: [track(\"drums\", drums({kick:\"X...\", hat:\"x.x.\"}), kit(), {\r\n        chain: [fx(\"lowpass\", {id:\"tone\", cutoff_hz:16000})]\r\n    })],\r\n    automation: [automation(\"drums.tone.cutoff_hz\", curve([[0b,500],[4b,16000]]))]\r\n})\r\n```\r\n\r\nEach voice keeps its own insert, so the sweep also affects its sends. This does\r\nnot create a shared bus processor. Voice-specific inserts stay independently\r\naddressable, for example `drums.kick.tone.cutoff_hz`. An unnamed track insert uses\r\nits logical chain index (`drums.fx0.cutoff_hz`), even when voice-specific inserts\r\nprecede its physical copy. `muz inspect song.muz --view automation` shows bounded\r\nsummaries of the expanded physical lanes; `--view automation_points --track TARGET`\r\npages one lane's points. A logical lane and a physical lane cannot own the same\r\ntarget; merge the curves or use separate physical lanes. A logical insert lane\r\non a kit with no hits is an error.\r\n\r\n### Deriving automation from notes\r\n\r\nComposers derive automation from musical data using ordinary source functions.\r\n`pattern.select(\"tag:answer\").notes` yields note records that can be filtered,\r\nsorted and folded into a `curve`, then passed to `automation(target,curve)`.\r\nThe target can be send gain, a bus level, filter cutoff, effect mix, or any other\r\nsupported parameter. Tags supply a selection; the function decides the shape,\r\nvalues and overlap policy. For example, this custom function raises a send from\r\n−120 dB to a velocity-dependent amount at each tagged attack:\r\n\r\n```muz\r\nfn accents(material, timing) {\r\n    let notes = sort_by(material.select(\"answer\").notes, fn(n) => n.at);\r\n    let points = fold(notes, [[0s, -120]], fn(ps, n) => ps + [\r\n        [seconds_at(n.at, timing) + n.offset, -24 + n.velocity * 12],\r\n        [seconds_at(n.at, timing) + n.offset + 100ms, -120]\r\n    ]);\r\n    automation(\"lead.send.echo\", curve(points, \"step\"))\r\n}\r\n```\r\n\r\nThis particular recipe assumes attacks after zero with more than 100 ms between\r\nthem. For overlapping gestures, choose how to combine them in source before\r\nsubmitting one lane per target. Points must be nonnegative and strictly increasing.\r\nUse beats for score-aligned curves or `seconds_at` and note offsets for performed\r\ntiming; share the song's tempo settings as described in\r\n[score and performed time](performance.md#score-and-performed-time).\r\nGenerated curves remain visible with `muz inspect song.muz --view automation_points --track TARGET`.\r\n\r\n`std/mix.muz` includes editable examples: `note_start`/`note_end` calculate performed\r\ntimes, `gate_windows` merges constant-level windows, and `mix.throws(material,\r\nselector,target,level=-12,tail=120ms,timing={})` returns an ordinary automation lane\r\nusing those helpers. Put it in the song's `automation` list. Its send-volume recipe\r\nreturns to −120 dB after key release plus tail, and empty selections leave the\r\nsend closed. Its policy is editable in `.muz`.\r\nThe automated send carries the track's sounding audio; the receiving effect keeps\r\nprocessing its tails after the send closes. [The example](../examples/tagged-send.muz)\r\ncombines this recipe with a composer-written velocity-shaped filter gesture.\r\n\r\n### Passage and arrangement gestures\r\n\r\n`std/arrange` evaluates passage gestures after final placement with the full tempo\r\nmap. Its `build(form,settings,gestures=[])` also accepts functions over the whole\r\narrangement context. Use that wider scope when a policy spans passage boundaries:\r\nfor example, derive send windows from all placed lead notes and union them once\r\nwith `std/mix.throws`. A tail may then cross into the next passage without being\r\nclipped or competing with a second lane. Local and whole-arrangement callbacks\r\nreceive the same fields: `name`, `start`, `span`, `parts`, and `timing`.\r\n\r\n`mix.throws(...,start=0s)` and `mix.gate_windows(...,start=0s)` accept an explicit\r\nstart for a local automation fragment. Joining fragments requires compatible\r\nnonoverlapping curves; overlapping policies belong in an explicit source\r\ncombination.\r\n\r\n## Resource limits\r\n\r\nAudio blocks are bounded to 1024 frames, with 256 scheduled note/control events\r\nper physical track per block. Dense expression can reach that event budget; use\r\na smaller block size or fewer simultaneous controls. Native synths and voice\r\npatches have 16 voices, and samplers have 32; they steal voices when necessary.\r\nPiano feasibility checks are independent of these playback limits.\r\n\r\n### Graph preparation budget\r\n\r\n`muz check` reports expanded physical tracks, devices, buses (including master),\r\nroutes, sample zones, total resource units and the five largest contributing lanes/buses. JSON\r\noutput exposes this under `graph` and `graph_budget`. Kit expansion is included.\r\nThere are no separate 32-track, 128-device, 15-bus, 128-route or 128-zone limits.\r\n\r\nThe process-wide `MUZ_GRAPH_BUDGET` defaults to 4096 units. Each graph device, bus,\r\nroute or sample zone costs one unit; a track contributes its instrument, inserts,\r\nroutes and zones. Zone preparation is counted across the expanded graph, including\r\nevery kit voice and reused instrument instance. One sampler with 200 zones on a\r\nsingle track contributes 202 units (instrument, output route, zones), plus one\r\nfor the master bus. Its zones can be generated with ordinary source operations:\r\n\r\n```muz\r\nuse \"std/arrange\" as arrange;\r\nlet zones = arrange.flatten(map(range(25), fn(i) => map(range(8), fn(take) => {\r\n    path:format(\"recordings/root{}_take{}.wav\", [48+i, take]),\r\n    root:48+i, keys:[48+i,48+i]\r\n})));\r\nlet guitar = sample(zones, {attack_ms:2, release_ms:35});\r\n```\r\n\r\nMaps must contain at least one zone. Preparation fails with the required and\r\nallowed total plus contributing lanes, before sample file metadata or audio is read.\r\nSet the budget before starting muz, for example `MUZ_GRAPH_BUDGET=8192 muz check song.muz`.\r\nIt accepts integers from 1 through 65536 and stays fixed for the process lifetime.\r\nA failed preflight reports required/allowed units, expanded counts and contributors.\r\nThis counts graph and zone preparation, not CPU or decoded-sample memory. The\r\nsampler's independent cap of 64 × 1024 × 1024 decoded stereo frames\r\nper instrument remains; plugin, rack and per-block event budgets also still apply.\r\n\r\nEngine and transaction vectors are sized from the graph during preparation. Live\r\ntelemetry and its scratch space are allocated from the process budget before\r\nplayback, so edits can grow the graph within that budget without allocating in the\r\naudio callback. A larger budget permits larger preparations; shared bus processing\r\nremains useful for reducing actual work.\r\n\r\n## Next steps\r\n\r\nUse [workflow](workflow.md) to inspect automation, render taps, or compare mixes.\r\nSee [instruments](instruments.md) for samples and plugins, and\r\n[synthesis](synthesis.md) for native voice graphs.\r\n","docs/sfz-performance.md":"# Native SFZ performance qualification\r\n\r\nThe release acceptance target is unchanged: on declared reference workloads,\r\ncallback p99 must be below half the callback duration, with no callback deadline\r\noverruns, dropped regions or nonfinite output. Allocation tests are separate.\r\nSuccessful loading, bounded polyphony and deterministic output do not pass a\r\ntiming gate.\r\n\r\n## Reproduce a workload\r\n\r\nBuild `cargo build --release --bin sfz-audit`. The command accepts JSON-lines\r\nrequests with `path`, optional `defines` and `source_overlays`, and optional\r\n`profile_workload` (`four_held_notes` or `drum_pattern`), and optional\r\n`profile_switch` (a specific MIDI keyswitch). Use the complete installed\r\nmapping and bindings from its catalog, then run:\r\n\r\n```sh\r\ntaskset -c 8 target/release/sfz-audit --profile < requests.jsonl > results.jsonl\r\n```\r\n\r\nChoose an available CPU for the host. The report records actual affinity, CPU,\r\ncompiler, executable SHA-256, source revision/status and selected keys, controls\r\nand switch. Copy the executable before a long run so another build cannot change\r\nthe binary used by later requests. A failed timing gate returns nonzero after\r\nwriting its report; preserve that output.\r\n\r\nEach root prepares once at 44.1, 48 and 96 kHz, then reuses/reset its processor for\r\n64, 256 and 1024-frame callbacks. A held-note workload plays four simultaneous\r\nowned notes for two seconds, followed by one second of release. The drum workload\r\nplays 24 hits at eight steps per second, with short note gates and recorded\r\nvelocities. Keys map to the closest available source key. The derived predicate\r\nselects an articulation and any necessary controller gate; inspect those settings\r\nbefore interpreting the result as a particular factory or microphone preset.\r\n\r\nTiming surrounds `DeviceProcessor::process`; event construction, inspection and\r\noutput hashing are outside it. Nearest-rank p50/p99/max include note-start and\r\nrelease callbacks. Wall-clock overruns remain failures. Voice maxima are sampled\r\nat callback ends and can miss shorter peaks. Decoded stereo bytes are exact\r\n`frames * 8`; RSS includes allocator and other process state, and VmHWM is explicitly\r\ncumulative across earlier requests. A shallow compiled-DSP byte count excludes\r\ncurve/route heap allocations. Normalized-program hashes include resolved absolute\r\npaths and identify a run, rather than a relocatable publisher program.\r\n\r\n## Recorded baseline\r\n\r\n[Baseline measurements](../contrib/sfz-performance-baseline.json) contain the\r\nimmutable-executable results on an AMD Ryzen Threadripper 3990X, Linux x86_64,\r\nrustc 1.98.1, pinned to CPU 8 with competing reference jobs paused.\r\n\r\nThe initial seven roots cover Trumpet, basic/full Virtuosity, dense All Brass,\r\nOrgan Combinations, Standard KSOP and METAL Full. **60 of 63 combinations pass.**\r\nDense All Brass's four-note chord reaches 54 voices. Its three 96 kHz combinations\r\nfail the p99 target at roughly 1.8 times half the callback duration; 64 frames has\r\nfive actual overruns. An exact cutoff-conversion cache reduces that ratio to about\r\n1.7 with two overruns, so the gate remains unmet.\r\n\r\nThe Virtuosity pattern reaches 33 voices and passes both program grids; its shared\r\ndrum keys produce identical audio in those settings. This does not measure every\r\nextra instrument, microphone control or maximum stack. Full kit decoding is about\r\n4.9 GiB and takes 35–36 seconds per preparation in this run. Organ uses a selected\r\nregistration. The METAL measurement selects switch 5, a slide-effects articulation;\r\na separate normal factory articulation profile explicitly selects switch 17,\r\nreaches 16 voices and passes all nine combinations. Neither filename size\r\nnor complete decoding establishes worst-case synthesis coverage.\r\n\r\nSubsequent controller-generation and extended LFO/filter/EQ control caches\r\nretain exact PCM. Pitch caches still miss the Brass 96 kHz half-callback target\r\nat ratios 1.065/1.049/1.050. Exact masks that bypass disabled EQ and zero-depth\r\nLFO destinations then make all nine targeted Brass cases pass, with zero\r\noverruns/drops and 96 kHz ratios 0.981/0.968/0.971 for 64/256/1024-frame blocks.\r\nThe complete eight-workload grid subsequently passes **71/72** cases: Brass at\r\n96 kHz/64 frames misses the half-callback target by 1.8%; its other two block\r\nsizes only narrowly pass (ratios about 0.998). All 72 have zero overruns/drops.\r\nThat complete-grid failure remains recorded; isolated nine-case success was\r\ninsufficient release evidence. Immutable binary hashes and timing distributions\r\nstay beside the initial failed baseline.\r\n\r\n## Final complete qualification\r\n\r\nThe subsequent immutable executable\r\n`5b8c69706023c9cbcdde1288d930f2e4cff40a824a9f20a907823879f248ec99`\r\npasses **72/72** cases across all eight declared workloads, three sample rates\r\nand three callback sizes. All have zero deadline overruns, dropped regions and\r\nnonfinite samples. Dense Brass is the tightest workload: its 96 kHz p99 ratios\r\nare 0.868539/0.855368/0.860149 for 64/256/1024 frames, leaving at least **13.1%**\r\nheadroom below the half-callback limit. Exact static-filter and shape caches,\r\na cold controller-refresh path and the original contiguous voice scan preserve\r\nPCM and mixing order; the attempted active-index scan was removed after it failed\r\nto improve the measured workload.\r\n\r\nThe recorded CPU 8 governor is `powersave`; frequency snapshots, affinity,\r\npreparation time, decoded memory and every p50/p99/max are in the final report.\r\nNo OS power settings changed. Snapshots are outside callback timing and do not\r\nprove a fixed clock throughout the run; older reports without snapshots cannot\r\nbe retrospectively assigned one. Reference rendering and builds were paused.\r\n\r\nThis closes the original declared-workload timing gate. The earlier fixed\r\n256-layer synthetic stress result still exceeds realtime and is retained as a\r\ncapacity limitation: configured voice capacity does not guarantee arbitrary\r\n256-voice realtime playback. These measurements do not qualify every microphone,\r\nregistration, controller combination or all-stop worst case. Allocation,\r\nblock-partition determinism and host/state tests remain separate evidence.\r\n","docs/sfz-reference.md":"# SFZ reference verification\r\n\r\nThe reference harness uses synthetic samples, explicit MIDI events and existing\r\nlocal players. It is diagnostic evidence for individual behaviors, not proof\r\nthat every patch in the supported libraries sounds identical. Generated WAVs,\r\nplayer binaries and third-party sample libraries are not repository assets.\r\n\r\n## Reproduce\r\n\r\n```sh\r\npython3 tools/test-sfz-reference.py\r\npython3 tools/sfz-reference.py \\\r\n  --player /usr/bin/sfizz_render --library /usr/lib/libsfizz.so.1.2.3 \\\r\n  --muz target/debug/muz --output /tmp/muz-sfz-reference\r\npython3 tools/sfz-reference-frequency.py \\\r\n  --library /usr/lib/libsfizz.so.1.2.3 --muz target/debug/muz \\\r\n  --output /tmp/muz-sfz-frequency\r\n```\r\n\r\nSelect trusted, installed executables explicitly. The scripts do not install or\r\ndownload players. `report.json` is the canonical output: the reference library\r\nalso writes parser diagnostics to stdout/stderr. Reports identify binary hashes,\r\nsettings, unknown opcodes, exit status and measured output. A successful load or\r\nan empty unknown-opcode list does not establish audible equivalence.\r\n\r\nThe measured reference in this work was Arch's sfizz **1.2.3-15**, using\r\n`libsfizz.so.1.2.3`. API renders use 48 kHz, 48-frame callbacks, note-on at frame\r\n6000, note-off at frame 30000, explicit master gain 0 dB and CC7/CC11=127.\r\nNative renders use the same sample, note, velocity, sample rate and unity track\r\ngain. sfizz's default host volume is -7.35 dB; implicit CC7 defaults to 100 and\r\nuses a squared gain. Comparing uncalibrated hosts gives a misleading gain error.\r\n\r\n## Interpret comparisons\r\n\r\nUse gain within 0.1 dB, pitch within one cent, envelope event timing within the\r\nlarger of 1 ms or 1% of the segment duration, and dry filter response within 1 dB\r\nas separate gates. Measure resonance and dynamic modulation separately. Compare\r\nrandom selection through traces and distributions with a fixed native seed;\r\ndifferent players' random generators need not produce identical PCM.\r\n\r\nThe harness retains unaligned, gain-preserved differences. Its explicitly named\r\n`sfizz_first_callback_repeat_diagnostic` removes a single observed repeated\r\nsample at the first callback boundary. This helps identify a reference artifact;\r\nit is not a universal alignment rule and is unsuitable for arbitrary modulated\r\npitch. Never normalize away an unexplained amplitude or timing difference.\r\n\r\nsfizz inserts at least 1 ms loop crossfade even when no crossfade was requested.\r\nNative inclusive hard loop wrapping therefore need not null against sfizz.\r\nCompare intro samples, inclusive endpoints and authored crossfade separately.\r\nSee pinned [Defaults.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/Defaults.cpp)\r\nand [Voice.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/Voice.cpp).\r\nThe [published loop-crossfade opcode](https://sfzformat.com/opcodes/loop_crossfade/)\r\ndoes not establish that reference minimum as an authored default.\r\n\r\n## Behavior evidence and dialects\r\n\r\n| Behavior | Evidence and interpretation |\r\n| --- | --- |\r\n| Includes and sample path base | Synthetic conflicting nested targets select the root SFZ directory in sfizz. See [modular instrument documentation](https://sfzformat.com/tutorials/modular_instruments/). |\r\n| Lone slash, `volume-1`, `volume-2` | sfizz reports malformed tokens, loads successfully and produces exactly baseline PCM. This supports narrowly pinned token removal, not inventing a missing equals sign or changing gain. |\r\n| Case-insensitive sample fallback | Exact synthetic case variants resolve in sfizz. Native ambiguity rejection must remain explicit. |\r\n| Amplitude routes | Base amplitude zero remains silent with a CC route. Base 100 multiplied by normalized CC produces linear gain; multiple routes multiply. Explicit CC7 amplitude routing replaces its implicit gain. |\r\n| Note polyphony | sfizz counts group/key voices, clamps zero to one and releases sibling rings together. Limits 0/1/2/3/4 with two layers produce counts 1/1/2/2/4 on repeated hits. Default self-mask can protect a louder voice while allowing a quieter new voice beyond the soft limit. See [VoiceManager.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/VoiceManager.cpp). |\r\n| Virtual controllers | The MIDI event state stores shared snapshots, but audible CC131/133/135/140 modulation uses per-voice trigger velocity/key and captured random/key delta. CC131 is zero for note-off trigger voices in sfizz. See [Controller.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/modulations/sources/Controller.cpp). See [extension documentation](https://sfzformat.com/extensions/midi_ccs/) and [MidiState.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/MidiState.cpp). |\r\n| Curves | sfizz predefined curves are 0–6; curve4 is squared, curve5 square root, curve6 square root of one minus input. Corpus curves7/8/11/12 are authored custom curves, including point77. See [Curve.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/Curve.cpp). |\r\n| Numbered EG out-of-range levels | sfizz renders -100 and -1 identically by clamping. Approved Sforzando also renders -100 and -1 with identical PCM, confirming the clamp interpretation for the tested numbered EG. |\r\n| ARIA variables | sfizz rejects `var01_*`; native analytic tests establish the published multiplication/addition equations. Sforzando full/half CC92 multiplication fixtures audibly change cutoff; dry-normalized native response differs by -0.891/-0.646 dB, within the 1 dB filter gate for those two points. See [variable operators](https://sfzformat.com/opcodes/varNN_mod/) and [variable routing](https://sfzformat.com/opcodes/varNN_/). |\r\n| Cross-LFO routing | Short `lfo03_freq_lfo2_oncc117` is documented in [vibrato examples](https://sfzformat.com/tutorials/vibrato/), not a typo to silently correct. sfizz rejects it and the full/base variants. Sforzando short/full forms produce identical PCM. The direction is source N to target X: `lfo03_freq_lfo2` sends LFO3 to LFO2's frequency. Isolated DC volume clocks confirm unit-wave additive Hz. Triangle/sine sources, target base rates 2/4 Hz and depths 0/0.01/1 agree with analytic cycle times within 0.154 ms. Earlier apparent source-depth dependence came from reversing this direction and listening to the actually modulated oscillator's pitch depth. Native corresponding source2/target1 fixtures pass within 0.032 ms. Large depth 100 signed-rate probes remain diagnostics outside this monotonic gate. |\r\n| LFO waveforms | Triangle starts at zero, then positive peak. Native exact sine differs from sfizz's parabolic sine approximation; use modulation depth/frequency/phase metrics, not a global PCM error gate. See [LFO.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/LFO.cpp) and [wave indices](https://sfzformat.com/opcodes/lfoN_wave/). |\r\n| Envelope curves | sfizz legacy decay follows exponential coefficient9 and stops at sustain. Published ARIA release-shape defaults differ; the measured Sforzando/native thresholds below pass the2ms gate. |\r\n\r\nThe frequency script samples 100, 250, 500, 1000, 2000 and 4000 Hz for a dry\r\nbaseline, LP2, HP1, two filters and one +6 dB EQ band. It normalizes each engine's\r\nfilter response to that engine's dry output. The initial measured HP1 and EQ\r\nresponses agreed within 0.001 dB. LP2 and two-filter differences reached 3.010 dB\r\nat cutoff and exceeded 1 dB at 500/2000 Hz; that initial run failed the empirical gate,\r\nnot permission to choose whichever filter sounds preferable. Re-run after any\r\nfilter policy change; the report's binary hash identifies the tested build.\r\nAfter changing LP2 resonance zero to unity Q, the repeated 30-case sweep passed\r\nwith maximum absolute response difference 0.003831 dB.\r\nThis six-frequency sweep does not validate resonance, modulation or all filters.\r\n\r\nA DC fixture measured identical 100 ms attack-to-90% and 200 ms decay-to-50%\r\nthresholds. For a 200 ms release, native reached 10% 6.75 ms earlier and 1%\r\n14.208 ms earlier than sfizz, exceeding the 2 ms gate. The chosen published\r\nARIA shape versus sfizz coefficient9 explains a hypothesis, not a passed gate.\r\nThe approved Sforzando DC test reached 10% at 0.669458333 s and 1% at\r\n0.713750 s. Native reached those thresholds at 0.669395833/0.7133125 s:\r\ndifferences 0.0625/0.4375 ms, passing the 2 ms gate and supporting the published\r\nARIA release shape. This resolves the sfizz release discrepancy for this fixture.\r\n\r\n## Additional reference player\r\n\r\nPlogue's [official downloads](https://www.plogue.com/downloads.html) offer native\r\nLinux Sforzando **1.982**, dated April 14, 2026, including CLAP/VST3 and standalone\r\nx86_64/aarch64 builds. The x86_64 build requires SSE4.2 and kernel 5.4 or later;\r\nits packages list GTK3/gtkmm, GLib, Pango, Cairo, curl and libc dependencies.\r\nWine is unnecessary. No ARIA/Sforzando installation was initially found in the\r\nscoped personal plugin locations.\r\n\r\nThe official x86_64 archive was downloaded with explicit user authorization and\r\ninspected without running its installer or binaries. SHA256:\r\n`ee6b354fd375ff9d0ce30819683f44d3b712a1fe4ff53c77e44df036da82a900`.\r\nThe archive contains a proprietary installation-consent agreement in\r\n`opt/Plogue/sforzando/Licence.rtf`. The user separately accepted the actual agreement. Normal CLAP initialization\r\nand audio rendering succeeded in a narrow temporary sandbox containing runtime\r\nlibraries, the product, synthetic fixtures and isolated HOME/cache. The plugin\r\nself-reported version **2.1.2.4**. Its public `clap.preset-load/2` interface\r\nrejected direct SFZ and ARIA paths. Normal GUI Import worked once the host\r\nimplemented public timer/file-descriptor callbacks. The public state extension\r\nthen saved an opaque state and reloaded it without decoding or modifying it.\r\nUpdating our synthetic SFZ at that state’s known source path allowed reproducible\r\ncase replay. No proprietary binaries or opaque state are repository deliverables.\r\n\r\n`tools/sfz-reference-clap.py` provides the public CLAP host, embedded X11 GUI,\r\nopaque state save/load and deterministic MIDI/audio callbacks.\r\n`tools/sfz-reference-aria.py` replays a named case JSON through an approved saved\r\nstate. `tools/sfz-reference-aria-cases.json` contains synthetic probes. Use a clean\r\nsynthetic fixture path, import it through the normal GUI, then save with\r\n`--save-state`; pass the same path to the suite’s `--fixture`. The suite reports\r\nplugin/state hashes, exact fixture text, load/render failures and audio metrics.\r\nNever use a third-party library file as the mutable fixture.\r\n\r\nReference SFZ fixtures must avoid duplicate opcodes when comparing players:\r\nSforzando selected the first `sample` in an initial duplicate-sample diagnostic,\r\nwhile sfizz/native selected the later value. The reported DC and focused ARIA\r\nmeasurements use one sample opcode per region. The suite preserves only the\r\nfinal intended synthetic value before writing each fixture.\r\n\r\nPrioritize Sforzando black-box probes for numbered EG -100/-200 units, variable\r\nmultiplication/custom curves, cross-LFO rate routes, dynamic envelope modulation\r\nand release timing. Analytic tests plus published documentation are useful but\r\nmust be reported separately from original-player comparisons. Any reference\r\nunavailable or license-pending gate remains explicitly open; a successful\r\nsyntax/import audit alone cannot close it.\r\n\r\n## Additional reproducible gates\r\n\r\n`tools/sfz-reference-clock-cases.json` and `tools/sfz-reference-clock.py`\r\nmeasure DC loop volume clocks for 2.5-second held notes. Generate reference\r\naudio with `sfz-reference-aria.py --seconds 3 --note-off 2.625`, then run the\r\nclock analyzer against that output directory. It compares cycle crossing times\r\nwith the integrated additive-Hz model and reports interval mean frequencies.\r\nIt does not infer clock rates from the zero crossings of a pitched sample.\r\n\r\n`tools/sfz-reference-sequence.py` records four-hit sfizz voice traces for omitted,\r\nthree and four sequence lengths and positions 1–8. Omitted length keeps the\r\ncounter at 1: only position 1 plays. With length 3, positions 4–8 remain unreachable.\r\nThis confirms that the audited Virtuosity/Unreal out-of-cycle regions should\r\nproduce an authored-unreachable diagnostic, not an invented longer cycle.\r\n\r\nUse `sfz-reference-clap.py --stereo` to preserve per-channel measurements.\r\nRaw per-channel calibration covers mono and identical-channel stereo samples\r\nat pan -100, 0 and +100. Native and sfizz at explicit master 0 dB agree in total stereo RMS within\r\n0.02 dB (the centered channel asymmetry from integer CC10 stays below 0.07 dB); ARIA is consistently 3.0103 dB lower for both source types and all three\r\npan positions. This is a reference-engine normalization difference, not evidence\r\nfor a mono-specific sampler correction. ARIA center RMS is 0.122066 per channel\r\nand hard-pan RMS 0.172633; native values are 0.172633 and 0.244140 respectively.\r\nKeep this explicit gain ledger when comparing ARIA, rather than silently fitting\r\neach result. Dry-normalized filter comparisons remain valid. The sfizz oracle\r\npasses the 0.1 dB plain-gain gate; ARIA absolute gain remains uncalibrated until\r\nits independent engine/host normalization is identified.\r\n\r\nThe reference plugin exposes zero parameters through `clap.params` in this\r\ninstance, so that API did not reveal a separate master setting to explain its\r\nconstant normalization. This remains an explicit oracle difference.\r\n\r\nActual-library black-box trials cover one held articulation from each of the\r\nsix SFZ library families. Both outputs preserve two channels; comparing a stereo\r\nRMS with a mono downmix would confuse width/cancellation with gain. All six\r\nnative and ARIA runs loaded audibly, returned success, and produced finite PCM.\r\nThese are representative smoke tests and waveform diagnostics, not an assertion\r\nthat every patch has passed a sound-equivalence gate.\r\n\r\nThe native reference binary was the release build with SHA-256\r\n`146be03843455d9cde434ec1a846df686cd5d88f5b8eea07a8fc3093cb6e602d`.\r\nThe accepted official Sforzando archive and plugin descriptor versions are\r\nrecorded above. Runs used 48 kHz, a three-second render, note-on at 0.125 seconds,\r\nnote-off at 2.625 seconds, attack velocity 100, and stereo RMS measured from\r\n0.25–0.5 seconds. Native seed was 7, voice limit 256, and graph budget 32768.\r\nBoth hosts received the root's authored `set_cc` values rounded to 7-bit MIDI,\r\nthen CC7/11=127, CC10=64, and CC117=0. Fractional SFZ controller defaults remain\r\ncovered separately by analytic/native tests; these MIDI trials do not verify\r\nfractional-controller equivalence. Standard and METAL received explicit switch\r\nnotes 12 and 17 before their musical notes. Temporary mapping copies rebased\r\nsample paths to the approved installed assets and expanded Shinyguitar's\r\n`sample_dir=../Samples`; original mapping/sample bytes were unchanged.\r\n\r\n<!-- Generated by tools/sfz-reference-report.py from the final report. -->\r\n| Family | Original entry program | Musical key | Historical aggregate residual dB | Classification |\r\n|---|---|---:|---:|---|\r\n| Sonatina | `Trumpet Solo Sustain (looped).sfz` | 60 | +0.1034 | source gain passes; residual attributed to filter path |\r\n| Virtuosity | `01-basic-kit.sfz` | 36 | -0.2451 | source gain passes; measured ARIA curve-1 pitch dialect |\r\n| Shinyguitar | `main.sfz` | 60 | -0.2494 | forced-take gain passes; random selection/gain qualified |\r\n| Black and Blue bass | `03-babyblue_all.sfz` | 40 | +0.0124 | source gain passes; independently qualified variable/filter path |\r\n| Standard Guitar | `05-Guitar Chord Central.sfz` | 24 | +0.7479 | source gain passes; authored random gain/offset diagnostic |\r\n| METAL-GTX | `01-METAL-GTX Full.sfz` | 60 | -1.9294 | source gain and measured filter bands pass; random-gain diagnostic |\r\n\r\nThe largest valid absolute residual is 1.9294 dB (METAL-GTX).\r\nThe explicit ARIA ledger is 3.0102999566 dB; the isolated plain-gain bound is 0.1000 dB and does not classify whole patches.\r\nThis whole-patch table does not establish isolated gain, selected-sample parity, pitch,\r\nenvelope, release, filter or stochastic-distribution conformance. Differences require\r\nsource/selection attribution; an unexplained difference is an open gate, not a pass.\r\n\r\nGenerate this table and its maximum from the same report with\r\n`tools/sfz-reference-report.py --report docs/sfz-reference-evidence.json --ledger-db 3.010299956639812`.\r\nThe 1.9294 dB METAL result is the final baseline artifact; the earlier -0.2623 dB\r\ntrial used a different controller setup and must not replace it. These rows used\r\nthe baseline binary above; current-native and explicitly labeled random-neutral\r\nisolation measurements are classified by the followups below. The fixed-window helper\r\nfield called `release_rms` is not a release measurement for these longer notes;\r\nno release-conformance claim derives from it.\r\n\r\nOriginal entry-file SHA-256 values (copied mapping-subtree inventories were also\r\nrecorded; full sample dependency closure belongs to the separate catalog audit).\r\nNo third-party mapping/audio/state data is committed:\r\n\r\n- Sonatina: `6cb051a4ae1da3084fdfe8e0107d7dc544cac739aa9773ef680d9cc63abeccce`.\r\n- Virtuosity: `a04683d87ad820bcb6045b8accf199fbcf69cb7b151674a7fd6c3df5ec526906`.\r\n- Shinyguitar: `e78ba4363619ac242ab43adf646c558b33379c3c0199d77a72dec4752c062d1f`.\r\n- Black and Blue bass: `fd750c8f2204e70897ce446be021b3d6d0584412f1fd2eee9793b6b3ca2d2d6f`.\r\n- Standard Guitar: `97c833d0150a5bc72e8b3777953e86b8ab7ba8e8e86d7865c3065157eeb03183`.\r\n- METAL-GTX: `a7661be6657064013297bb77a0a8827279195914d27e1e2338c23f75ca7b112e`.\r\n\r\n`tools/sfz-reference-cc-trigger.py` supplies an additional deterministic CC\r\ntrigger probe. Installed sfizz 1.2.3-15 receives values 0, 64, 70, 70, 0, 70 for\r\n`on_locc1=50 on_hicc1=100` and produces active-voice counts 0, 1, 2, 2, 2, 3.\r\nAn in-range value change retriggers; an identical repeated value does not in\r\nthis reference. Requiring the previous value to lie outside the gate would miss\r\nthe second voice. The [opcode description](https://sfzformat.com/opcodes/on_loccN/)\r\nrequires an incoming in-range message; [sfizz Layer.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/Layer.cpp#L147)\r\nadds its observed unchanged-value suppression. Record that distinction rather\r\nthan claiming the documentation alone defines suppression.\r\n\r\nThe CC probe also uses sequence length 2 with distinct DC samples panned to\r\nopposite sides. Values 64, 64, 70 start positions 1, none, 1; active-voice counts\r\nare 1, 1, 2 and only the first sample's side accumulates audio. Thus the identical\r\nin-range message advances the sequence even though its voice is suppressed in\r\nsfizz; advancing only when a voice starts would incorrectly select position 2.\r\n\r\nIndependent one-voice amplitude and pitch probes establish the CC trigger's\r\nvoice context. With `amp_veltrack=100`, CC64/CC100 amplitude ratio is exactly 1,\r\nwhile ordinary note velocities 64/100 produce ratio 0.409568, approximately\r\n`(64/100)^2`. CC-triggered 440 Hz samples stay at 440 Hz with no explicit key,\r\n`key=64`, and `key=64 pitch_keycenter=60`; an ordinary note 60 at root 60 also\r\nplays at 440 Hz. The trigger key is the sample's `pitch_keycenter`, not the\r\nregion's low key, and ordinary note-velocity gain is bypassed. The controller\r\nvalue still feeds velocity-sensitive filter/envelope/pitch behavior.\r\n[sfizz Voice.cpp](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/Voice.cpp#L380)\r\nimplements that key substitution and gain bypass, with a separate\r\n`velocityOverride=previous` exception. These observations cover the tested\r\nsfizz reference; they do not turn unspecified behavior into an inferred\r\nall-player requirement.\r\n\r\n### Current METAL controlled attribution\r\n\r\nThe current release binary SHA-256 is\r\n`69fd14a6e9835f22696b91de9e253c8ab8bb9bc82f874796206e3f493c1bb215`.\r\nA repeat of the original METAL case produced exactly the baseline native PCM\r\nhash, while ARIA's newly drawn random gain changed its residual to -2.0290 dB.\r\nA paired diagnostic neutralized only `amp_random` in temporary mappings in both\r\nhosts: native/ARIA held RMS was 0.1641395106/0.1184062702 and the ledger residual\r\nwas -0.1735 dB. These are separate experiments, not replacements for the baseline.\r\n\r\nSix fresh ARIA processes per setting with an otherwise constant DC sample proved\r\nnegative `amp_random=-3` applies attenuation, rather than clamping to zero or\r\nusing the absolute value. Observed attenuation ranged from -2.9501 to -1.4776 dB;\r\nzero produced identical PCM and positive 3 produced +0.0637 to +1.5816 dB.\r\nSome processes repeat the same draw, so these are not six independent seeds and\r\nare not a distribution-coverage claim. The original source uses negative random\r\ngain; a single whole-patch gain residual cannot qualify its stochastic behavior.\r\nNo compensating gain or source correction was applied.\r\n\r\nA second paired diagnostic kept random gain at zero and removed only cutoff,\r\nresonance, `fil*`, and `eq1`–`eq3` opcodes from temporary mappings. With identical\r\ncontrols, switch, notes and original samples, native/ARIA RMS was\r\n0.1825739903/0.1288217926, residual +0.0187 dB. Thus the source/selection plain-gain\r\ncomparison passes 0.1 dB, and the remaining -0.1922 dB change is attributable to\r\nthe active filter/EQ path, not unexplained master gain.\r\n\r\nThe four outputs were also compared using summed-stereo power spectra of the\r\n0.25–0.5-second window: 2048-frame Hann segments, 50% overlap and segment-mean\r\nremoval. Each host's filtered/unfiltered transfer was compared, without gain\r\nfitting. Difference by band was -0.0094 dB (160–320 Hz), -0.0352 (320–640),\r\n-0.1333 (640–1280), -0.3620 (1280–2560), -0.5858 (2560–5120), and -0.1305\r\n(5120–10240): within the 1 dB component gate. The 80–160 Hz band differed by\r\n-4.0941 dB, but contained only 0.000003806 of unfiltered power (-54.2 dB of total),\r\nwhere finite-window leakage and PCM16 precision make the actual-window ratio\r\nunreliable. The energetic 100 Hz component check below resolves the low-frequency\r\nfilter/EQ conformance gate without suppressing this historical diagnostic.\r\nThis qualifies the measured energetic bands; it does not establish an unrestricted\r\nfull-spectrum result or qualify every METAL articulation.\r\n\r\nLocal evidence is `metal-isolation-current/report.json`,\r\n`metal-filter-isolation/report.json`, `metal-filter-isolation/spectral-report.json`,\r\nand `amp-random-reference/report.json` under the isolated reference workspace.\r\nReports contain original source hashes, controller/switch recipes, public host\r\noutput, binary hash, and WAV hashes. Third-party assets and opaque player state\r\nremain outside Git. An initial native diagnostic omitted the explicit graph\r\nbudget and was rejected; the successful retry used the unchanged source and\r\nestablished budget 32768. Subsequent paired diagnostics below provide the remaining family attribution;\r\nthe standalone synthetic component gates above remain independent evidence.\r\n\r\n### Five-family controlled diagnostics\r\n\r\nA second current-binary series used the same authored controllers, switches,\r\nnotes, paths and samples. Temporary copies removed only random amplitude, pitch,\r\noffset, delay and pan parameters and filter/EQ opcodes. Random region selection\r\nwas retained at this stage. Residuals were Sonatina +0.0105 dB, Virtuosity\r\n-0.2451 dB, Shinyguitar +0.7046 dB, bass +0.0105 dB and Standard +0.0184 dB.\r\nSonatina, bass and Standard pass the isolated source-gain bound in these copies;\r\nthis attributes their original aggregate differences to removed processing,\r\nwithout establishing all processing details from RMS alone. Sonatina's active\r\nfilter contribution was +0.0928 dB; bass's was +0.0018 dB. Standard has authored\r\nnegative random gain and random offsets, so its original single draw remains a\r\nstochastic diagnostic rather than deterministic gain evidence.\r\n\r\nThe actual include graphs contained 2, 123, 15, 25 and 110 files respectively,\r\nwith no missing includes. Virtuosity's unchanged intermediate result isolated its tune path for the next\r\nprobe; Shinyguitar's intermediate result retained different random takes. These intermediate residuals are not conformance passes; the subsequent\r\nsingle-cause diagnostics below resolve their attribution. Raw source inventories, measurements and host diagnostics\r\nare recorded in the local `five-family-neutral/report.json` artifact.\r\n\r\nSubsequent single-cause diagnostics resolved the remaining source-gain paths:\r\nforcing Shinyguitar's first random interval in both temporary mapping copies gave\r\n+0.0003 dB, while the native PCM stayed unchanged. The prior +0.7046 dB therefore\r\ncompared different random takes. Removing only Virtuosity's tune and tune-controller\r\nparameters gave +0.0106 dB, with microphone layers and sample selection preserved.\r\n\r\nA synthetic 440 Hz tone isolated the latter difference. Two 1200-cent routes with\r\nbuilt-in curve 1, CC72=64 and CC90=64, produced 444.829187 Hz in native muz and\r\n444.828940 Hz in sfizz (difference approximately 0.001 cent), but 440.000041 Hz in\r\nARIA. Native/sfizz center normalized bipolar curve 1 at 63.5; ARIA centers integer\r\n64. This is an observed controller-dialect difference, not a decoder or gain bug.\r\nThe actual library authors `set_cc72=63.5` and `set_cc90=63.5`; preserving those\r\nfractional defaults in native import retains neutral tuning. The common rounded\r\nMIDI recipe intentionally turns both into 64 and therefore produces the explicitly documented 18.9-cent ARIA dialect difference. The common\r\nsfizz/native pitch gate passes at 0.000962 cent; this does not relabel the ARIA\r\nrounded-controller result as a pitch pass. Do not adjust master gain or pretend\r\nthat passing source-gain diagnostics establishes universal player equivalence.\r\n\r\nThe additional artifacts are `selection-tune-isolation/report.json` and\r\n`tune-probe-report.json`. The latter records the exact synthetic SFZ. An initial\r\nscratch sfizz call omitted synth cleanup and tripped its leak assertion; the\r\nreported retry called `sfizz_free` and exited successfully with zero buffers.\r\n`tools/sfz-reference-spectrum.py` reproduces paired transfer diagnostics from four\r\nPCM16 WAVs and explicitly marks low-energy bands; its energy label is diagnostic,\r\nnot an automatic exemption from a declared conformance gate.\r\n\r\n### Continuous-instance stochastic gates\r\n\r\n`tools/sfz-reference-stochastic.py` uses 1000 isolated 15 ms notes at 20 ms spacing\r\nwithin each continuous player instance. A constant DC source separates gain from\r\nsample timbre. Two half-probability regions panned left/right yielded ARIA counts\r\n521/479 and native counts 467/533, both within the predeclared four-sigma binomial\r\nbound of 63.25 around 500. The positive 3 dB unipolar random-gain mean/variance was\r\n1.508215/0.767898 in ARIA and 1.538262/0.736892 in native; negative 3 yielded\r\n-1.499136/0.729153 and -1.538265/0.736892 respectively. All measured ranges stayed\r\ninside the signed 0–3 dB interval with 0.005 dB PCM16 allowance, means within\r\n0.109545 dB of ±1.5, and variances within 0.084853 dB² of 0.75. The bounds use\r\nuniform/binomial theory with four sigma to avoid frequent stochastic-test false\r\nfailures; no seed matching or gain fitting is required. Native seed was 7.\r\nThese pass the tested selection/gain distribution gates, not every upstream\r\nrandom-layer/controller cross-product. Reports retain each fixture and public\r\nhost diagnostic; repeated notes avoid the coarse process-seed correlation in the\r\nearlier six-process probe.\r\n\r\nThe low-energy METAL actual band was separately checked with an energetic 100 Hz\r\nsine at 44.1 kHz source/output and note-on zero, using the actual CC-driven LP2\r\nand three-EQ opcode forms. Native filter/EQ transfer was -6.303073 dB, ARIA\r\n-6.301600 dB: difference -0.001474 dB, passing 1 dB without an energy-floor\r\nexemption. The original low-energy actual-window discrepancy remains recorded;\r\nit does not describe this nondegenerate low-frequency component behavior.\r\nThe host's `--sample-rate 44100`, `--note-on 0`, and `--midi-events` paths were\r\nexecuted successfully through the accepted public plugin interface.\r\n\r\n### Final evidence and scope\r\n\r\n[Metadata-only final evidence](sfz-reference-evidence.json) merges the original\r\nsix baseline metrics unchanged with controlled followups, source/WAV hashes,\r\nplayer versions/hashes, MIDI/controller recipes, distribution gates and explicit\r\nARIA dialect classification. No audio, library mapping text, plugin binaries or\r\nopaque player state is included. The baseline table and its maximum are generated\r\nfrom this one artifact; its classifications reference the subsequent experiments.\r\nRebuild it from the local measured reports with\r\n`tools/build-sfz-reference-evidence.py --workspace REFERENCE_WORKSPACE --output docs/sfz-reference-evidence.json`,\r\nthen render with\r\n`tools/sfz-reference-report.py --report docs/sfz-reference-evidence.json --ledger-db 3.010299956639812`.\r\n\r\nAll six isolated source-gain paths pass 0.1 dB; common native/sfizz pitch, tested\r\nfilter/EQ, envelope/release and cross-LFO components, and continuous-instance\r\nselection/gain distributions pass their declared gates. The ARIA integer-center\r\ncurve 1 difference remains an intentional measured dialect policy. Qualification\r\ncovers those exact representative events and isolated families, not waveform-null\r\nequivalence across all 588 programs or every controller/articulation cross-product.\r\nNo remaining sound blocker was found within that declared evidence scope;\r\nperformance qualification is tracked independently and must retain its actual\r\nfailed/pending results.\r\n\r\nScientific reference helpers (`sfz-reference-spectrum.py`,\r\n`sfz-reference-stochastic.py`, and their spectrum tests) require NumPy. The\r\nverified interpreter on this host is `/usr/bin/python` (Python 3.14, NumPy 2.5.3 at\r\n`/usr/lib/python3.14/site-packages/numpy`). The default `python3` resolves to\r\n`/home/linuxbrew/.linuxbrew/bin/python3`, which lacks NumPy here; use the verified\r\ninterpreter explicitly, for example\r\n`/usr/bin/python tools/test-sfz-reference-spectrum.py` and\r\n`/usr/bin/python tools/sfz-reference-spectrum.py --help`.\r\nThis dependency belongs to offline scientific reference tooling, not native muz.\r\nNo additional package installation is required on this host.\r\n","docs/sfz-state-qualification.md":"# Linked SFZ state qualification\r\n\r\n[contrib/sfz-state-qualification.json](../contrib/sfz-state-qualification.json)\r\nrecords eight actual roots across the six SFZ families. Each probe loads and\r\nnormalizes its mapping, builds a linked `DeviceState`, encodes version 4, decodes\r\nthrough an explicitly supplied resolver, and compares the restored `SfzConfig`\r\nwith the original. It hashes sample bytes for the dependency table but does not\r\ndecode PCM, prepare an audio processor, or render audio. No publisher contents,\r\nencoded states or binaries are committed.\r\n\r\n| Root | Regions | Normalized bytes | Encoded state bytes |\r\n| --- | ---: | ---: | ---: |\r\n| Sonatina Trumpet Sustain | 13 | 38,309 | 11,543 |\r\n| Sonatina All Brass KS | 664 | 3,175,237 | 62,299 |\r\n| Sonatina Organ Combinations | 1,590 | 6,242,719 | 69,910 |\r\n| Virtuosity Full Kit | 8,902 | 29,677,434 | 1,186,438 |\r\n| Standard Guitar KSOP | 12,427 | 138,537,458 | 689,215 |\r\n| METAL-GTX Full | 14,235 | 129,172,503 | 754,037 |\r\n| Shinyguitar main | 6,798 | 43,468,938 | 214,738 |\r\n| Black and Blue Darkblack 01 | 8,448 | 112,481,180 | 405,066 |\r\n\r\nEvery recorded roundtrip preserved the normalized program, constructor defines,\r\nsource overlays, voice/sample budget, seed, and linked asset policy. Shinyguitar\r\nrequires `sample_dir=\"../Samples\"`; the other recorded roots use no constructor\r\ndefines or source overlays. This representative host-state gate does not claim\r\nthat every upstream root or every opcode is audio-qualified.\r\n\r\nThe JSON identifies the exact executable SHA256. Provenance was captured before\r\nthe Darkblack run; the preceding seven successful rows used the same executable\r\nand were captured retrospectively. That executable includes compact version 4\r\nstate and predates final resolver authorization hardening. Current authorization\r\nis covered by permanent device-state, scoped asset, and CLAP tests. Byte counts\r\ninclude machine-specific absolute paths and can change when installations move.\r\n\r\n## Reproduce with current source\r\n\r\nThe standalone [public API helper](../tools/sfz-state-qualify.rs) accepts one JSON\r\nrequest per line on stdin. Each request contains `path` (the absolute SFZ root),\r\n`defines`, and `source_overlays`. The helper runs loading, state creation, and\r\nrestoration under the native `ScopedFileAssets::configured_sfz()` grant. Normal\r\ninstalled contrib discovery authorizes the five SFZ asset directories; custom\r\nlibrary locations require `MUZ_SFZ_ASSET_ROOTS`. Serialized descriptors never\r\ncreate filesystem grants. See [embedding](embedding.md#sfz-assets-and-saved-state).\r\n\r\nBuild the helper from exact Cargo JSON artifacts, with its executable inside the\r\ncheckout's `target/release` directory so ordinary contrib discovery works:\r\n\r\n```sh\r\npython3 tools/build-sfz-state-qualify.py\r\ntarget/release/sfz-state-qualify < requests.jsonl\r\n```\r\n\r\nThe builder uses `cargo build --locked --release --lib --no-default-features\r\n--message-format=json` and selects the exact `muz` and `serde_json` rlib artifact\r\npaths from Cargo messages. It does not choose between ambiguous filename globs.\r\nThe earlier retained observations used an explicitly granted `FileAssets`\r\nresolver before final authorization hardening; their binary/source hashes remain\r\nunchanged in the qualification JSON. The current reproduction helper exercises\r\nthe final native scoped workflow.\r\n\r\nGenerate requests from the retained qualification rows, using the local contrib\r\ninstallation rather than copying this machine's absolute roots:\r\n\r\n```python\r\nimport json\r\nfrom pathlib import Path\r\n\r\ncontrib = Path(\"/your/authorized/muz/contrib\").resolve()\r\nproof = json.loads(Path(\"contrib/sfz-state-qualification.json\").read_text())\r\nfor row in proof[\"rows\"]:\r\n    print(json.dumps({\r\n        \"path\": str(contrib / row[\"root\"].removeprefix(\"contrib/\")),\r\n        \"defines\": row[\"defines\"],\r\n        \"source_overlays\": row[\"source_overlays\"],\r\n    }))\r\n```\r\n\r\nRequire every result's `roundtrip` to be true, `decode_error` to be null, and\r\n`encoded_state_bytes` to remain below 67,108,864. The original source descriptor\r\nlimit is 33,554,432 bytes; inherited region size exceeding that is intentionally\r\nhandled by the compact linked descriptor rather than a larger cap. Hash and\r\nmetadata fences assume stable host-controlled library files during preparation;\r\ncanonical confinement is not an OS sandbox against hostile concurrent filesystem\r\nmutation.\r\n\r\nThe current scoped-helper smoke check also records ordinary checkout contrib\r\ndiscovery for Darkblack 11 without extra grants (216 regions; 19,597 state bytes),\r\ndefault denial for a temporary custom library, and successful exact roundtrip\r\nafter explicitly setting `MUZ_SFZ_ASSET_ROOTS` for that directory. Its executable\r\nidentity and engine base/dirty-source provenance are separate from the historical\r\neight-root qualification and do not replace those observations.\r\n","docs/sfz.md":"# Native SFZ instruments\r\n\r\n[Instrument guide](instruments.md) · [Complete contrib assets](../contrib/SFZ.md) ·\r\n[Embedding](embedding.md) · [DAWProject](dawproject.md)\r\n\r\nmuz imports SFZ into its Rust engine. `sfz(path, options)` is an instrument;\r\noriginal mappings choose all matching regions instead of choosing a single native\r\nsample zone. Existing curated sample-map presets remain available. The supported\r\ncontrib corpus consists of Sonatina 4.0, Virtuosity Drums 0.925, Shinyguitar, Black\r\nAnd Blue Basses, Standard Guitar and METAL-GTX. Their 588 public roots are listed\r\nin per-pack `sfz-catalog.json` files. VSCO's pinned repository contains no SFZ\r\nmappings, so its existing native builders remain its interface.\r\n\r\n```muz\r\nlet instrument = sfz(\"Programs/main.sfz\", {\r\n  defines: {sample_dir: \"../Samples\"},\r\n  cc1: 104,\r\n  cc7: 127,\r\n  cc11: 127,\r\n  seed: 7,\r\n  max_voices: 256,\r\n  sample_budget_frames: 268435456\r\n});\r\n```\r\n\r\nPaths are relative to the module declaring the instrument. The `defines` record\r\nsupplies declarative bank context without running an upstream bank GUI. Named\r\ncontrib builders provide their required bindings and provenance overlays. Physical\r\ncontrollers use `cc0` through `cc127`, with values in MIDI units 0–127; constructor\r\ncontrol values override mapping defaults and are restored on instrument reset.\r\nNames outside `cc0`–`cc127`, nonfinite values, and values outside 0–127 are rejected\r\nduring song validation, before audio preparation. Fractional values such as\r\n`cc90: 63.5` are preserved. Use constructor controls for initial instrument setup\r\nand the existing parameter automation or MIDI CC events for later musical changes.\r\nMIDI bend and note-ID expression use the same native performance paths. Numeric\r\n`sample_zone` annotations are rejected for SFZ instruments because they bypass authored selection semantics.\r\n\r\n## Import and preparation\r\n\r\n`src/sfz` preprocesses ordered source text and produces a serializable `Program`.\r\nIt expands includes/macros, flattens global/master/group/region inheritance, keeps\r\nopcode source locations and resolved dependency identities, and\r\nretains control defaults, labels and curves. Last assignment in a scope wins.\r\nOriginal opcode values remain available; typed compilation converts note names.\r\nHeaders reset their subordinate scopes. Includes first resolve relative to the\r\nprogram root, as measured in sfizz; fragment-relative fallback reports a diagnostic.\r\nSample paths follow the root/default-path mapping context. Both includes and samples\r\nuse exact filenames first, then SFZ-specific case-insensitive fallback; ambiguous\r\nfallbacks fail. Other native asset formats retain their existing path semantics.\r\n\r\nUndefined macros, include cycles, size/depth limits, malformed numeric values and\r\nunrecognized opcodes produce errors. Recognizing source syntax does not\r\nprove playback support: preparation separately compiles every effective region's\r\nselection and DSP behavior, rejecting unsupported behavior. Source errors retain\r\npath and line information. `Program::validate` also checks deserialized structure and value semantics. Import\r\nlimits are 16 MiB cumulative source bytes, 32 include levels and 100,000 regions;\r\nthese source limits are distinct from saved-state and embedded-asset limits.\r\n\r\nAn opt-in `SourceOverlay` records a relative mapping path, original SHA-256, exact\r\nsingle-occurrence token removals and a reason. The original installed source is\r\nnever rewritten. The importer rejects changed hashes, ambiguous removals and unused\r\ndescriptors. Sonatina builders use these descriptors only for malformed tokens\r\nmeasured to be ignored by sfizz; they never invent a missing volume value.\r\n\r\nPrepared instruments decode each unique WAV/FLAC recording once into stereo frame\r\nbuffers, compile region predicates/DSP and preallocate bounded voice/note state.\r\n`*silence` is an explicit internal silent source. Missing samples fail preparation.\r\nParsing, hashing, decoding and allocation happen before callback processing.\r\nCancellation is checked during preparation. Independent instruments own their\r\ncontroller, performance-history, random and voice state.\r\n\r\n## Selection and expression\r\n\r\nThe dedicated processor evaluates layered key/velocity/controller/bend gates,\r\nkeyswitches, first/legato triggers, sequence position and one shared random draw\r\nper triggering event. Release and release-key layers retain their originating note\r\nidentity. Sustain, one-shot and sustain/continuous loops, delayed attacks, group\r\nchokes and note polyphony have separate state; choking audio does not erase the\r\nheld-key history used by legato or keyswitch selection.\r\n\r\nFor `off_mode=time`, muz deliberately follows sfizz 1.2.3's timed amplitude\r\nrelease: the current envelope level decays by `exp(-9 * elapsed / off_time)`,\r\nthen finishes with a 50 ms linear fade below an envelope amplitude of `1e-4`.\r\nPositive times shorter than 6 ms use 6 ms; zero enters the final linear fade\r\ndirectly. The coefficient is prepared off-thread. Choking during attack stops\r\nthe attack at its current level; repeated group chokes and subsequent key\r\nreleases do not restart the timed fade. Pitch/filter envelopes enter their\r\nordinary release stages.\r\n\r\nThis is a compatibility policy, not a universal SFZ conformance requirement.\r\n[`off_mode=time`](https://sfzformat.com/opcodes/off_mode/) and\r\n[`off_time`](https://sfzformat.com/opcodes/off_time/) are ARIA extensions; the\r\ndocumented default [`off_curve=10`](https://sfzformat.com/opcodes/off_curve/) is\r\nvendor-specific, while `off_curve=-1` explicitly denotes linear fading.\r\nExplicit `off_curve`/`off_shape` opcodes remain unsupported and are rejected\r\nrather than silently substituted. The reference algorithm is sfizz 1.2.3's\r\n[`ADSREnvelope`](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/ADSREnvelope.cpp)\r\nand [voice off handling](https://github.com/sfztools/sfizz/blob/1.2.3/src/sfizz/Voice.cpp).\r\n\r\n\r\nController-trigger regions (`on_loccN`/`on_hiccN`) respond to changed in-range\r\nmessages. Repeated identical messages advance sequence state without starting a\r\nvoice, matching the measured sfizz behavior. These voices use the region pitch\r\ncenter and retain controller velocity for tracking, while bypassing ordinary\r\nattack-velocity amplitude gain. Each trigger owns independent layers. The present\r\ncontrib corpus has no controller-trigger regions; synthetic probes cover this\r\nadditional recognized behavior.\r\n\r\nPhysical CCs are channel-scoped. Virtual modulation inputs include velocity, key,\r\nrandom and previous-key distance and follow their documented note-time lifetimes.\r\nCC131/133/135/140 modulation is captured per voice, so a later note cannot change\r\nan earlier voice's velocity, key, random value or key distance. CC131 is zero for\r\nrelease-trigger voices. Event-time envelope depths and LFO phases latch before\r\nlater events at the same sample offset; live controller routes remain live.\r\nNote-ID volume, expression, pan and tuning affect every layer owned by that note,\r\nincluding releasable layers. Authored SFZ gain and tuning combine with those values.\r\nImplicit CC7/11 gain applies only where the mapping does not explicitly author the\r\ncorresponding amplitude routes. Controllers initialize from mapping defaults, then\r\nconstructor overrides; resets restore those values and the configured seed.\r\n\r\n`note_polyphony=0` is retained in source diagnostics and played as a minimum of one,\r\nmatching the measured sfizz behavior. Polyphony counts audible region voices and\r\nchokes their sisters. Velocity self-masking protects louder earlier voices.\r\nSelection and voice stealing are deterministic for a fixed seed and event order.\r\nThe last effective `sw_default` initializes switch state. Only explicitly named\r\n`sw_last` keys are registered switches; broad listener ranges do not consume\r\nordinary musical keys. Registered switches can also select playable regions.\r\nSwitch history and previous musical-key distance are independent. An authored\r\nsequence position beyond its sequence length stays unreachable and inspectable.\r\nImport diagnostics identify its effective length and inherited source. Reference\r\ntests confirm that an absent `seq_length` defaults to one; muz does not infer a\r\nlarger cycle from other regions' positions.\r\n\r\n## DSP model and reference evidence\r\n\r\nPrepared DSP covers gains/velocity curves/key tracking, fades, pan/width,\r\nAHDSR envelopes, numbered EGs, legacy and numbered LFOs, dual filters and three EQ\r\nbands, variables and acyclic cross-LFO modulation. Sparse compiled routes avoid\r\nsource string lookups in the sample loop. Voice DSP uses fixed arrays; cyclic\r\nmodulation fails compilation instead of recursing in the callback. Runtime and DSP\r\nunit tests specify equations, update timing and release behavior.\r\nCross-LFO `lfoN_freq_lfoX` routes source N into target X's frequency as additive\r\nHz from the source oscillator. Asymmetric DC probes against Sforzando verify the\r\ndirection and measured clock. Per-voice controllers are read through a borrowed\r\nview, avoiding a controller-array copy per voice per sample. Channel generation\r\ntokens invalidate physical-controller coefficient caches only when normalized\r\nvalues change. Waveforms, phases and envelopes still advance sample by sample;\r\ncache/bypass regressions preserve exact PCM through controller changes, release\r\nand checkpoints.\r\n\r\n`tools/sfz-reference.py` generates synthetic recordings and events, runs the native\r\nengine and a local sfizz reference, and saves measured comparisons plus exact\r\nbinary hashes. Its report distinguishes measured behavior, normative documentation\r\nand unsupported reference opcodes. Reference renders are external evidence, not\r\nredistributed upstream assets. Different interpolation/envelope/filter equations\r\nare compared with relevant gain, pitch, timing and response metrics rather than a\r\nblanket waveform equality claim.\r\n\r\nKnown reference dialect differences include sfizz's forced minimum 1 ms loop\r\ncrossfade despite the SFZ opcode documentation giving no such default. muz uses\r\nexplicit authored loop smoothing and otherwise wraps at the inclusive loop endpoint.\r\nThe harness also records a reproducible first-callback repeated sample in the tested\r\nsfizz build; raw measurements remain present beside a separately named diagnostic.\r\nARIA-specific variables and cross-LFO routes have normative and synthetic validation;\r\nsfizz does not implement those routes, so its renders cannot establish their empirical\r\nagreement. Full corpus/reference qualification is tracked in the remaining plan.\r\n\r\n## Resource limits and inspection\r\n\r\n`max_voices` defaults to 256 and accepts 1–4096. Note ownership is independently\r\nbounded. `sample_budget_frames` defaults to 64 Mi stereo frames (512 MiB decoded),\r\nwith a maximum of 1024 Mi frames (8 GiB decoded). Unique sample metadata is counted\r\nbefore decoding; an oversized program fails with its required footprint. Large\r\noriginal programs deliberately need an explicit larger budget: Shinyguitar needs\r\nabout 1.17 GiB decoded, Darkblack keyswitch about 1.75 GiB, and METAL Full about\r\n3.64 GiB; Virtuosity's full kit needs about 4.9 GiB. Those estimates describe stereo\r\nruntime buffers, not download size. Choose a budget the host can actually allocate;\r\nthe hard ceiling does not promise that every platform can hold a full library.\r\nLikewise, voice capacity is a memory/selection limit, not a realtime guarantee.\r\nAn earlier fixed 256-layer synthetic release benchmark took about 0.704 s for\r\n0.501 s of audio on the qualification host. Coefficient, gain and pitch caches and\r\nan absolute note-age clock preserve exact PCM, but that result does not qualify arbitrary 256-layer realtime playback. The\r\n[final declared-workload grid](sfz-performance.md) passes all 72 timing cases with\r\nzero overruns/drops and at least 13.1% headroom below the half-callback target.\r\nMeasure the actual instrument and host before choosing polyphony.\r\n\r\nThe existing graph budget additionally accounts for exact SFZ region/sample counts,\r\nmodulation declarations and voice slots. Region/sample costs are one unit each;\r\nmodulation and voice costs group 32 declarations/slots per unit. Large mappings can\r\nexceed the default 4096 graph units; choose a sufficient explicit host graph budget\r\nor `MUZ_GRAPH_BUDGET` after inspecting the diagnostic. Counts remain exposed rather\r\nthan silently weakening validation. See [embedding](embedding.md).\r\n\r\n`AudioEngine::device_sfz_statistics()` returns per-device decoded frames, configured\r\nlimits, active notes/voices, matched/started regions, stolen voices/notes and dropped\r\nregions. Stolen-note counters record note-owner capacity pressure; stolen-voice\r\ncounters record voice/polyphony pressure. It allocates an inspection result and\r\nbelongs outside the callback.\r\nExact effective opcode maps share immutable compiled DSP programs during\r\npreparation. Statistics expose their unique count and shallow struct bytes; the\r\nshallow count excludes separately allocated curve/route tables and is not total\r\nresident memory. Region identity and selection remain independent of DSP sharing.\r\nProcessor counters and audio processing use preallocated storage. The callback\r\nallocation regression exercises layered attacks, releases and loops and verifies\r\nidentical PCM under different block partitions.\r\n\r\n## Hosts, assets and state\r\n\r\nSFZ is part of the native model and instrument state, including normalized programs,\r\nsource overlays, seed, limits and controls. Version 4 linked wire state stores a\r\ncompact descriptor and normalized-program fingerprint instead of duplicating all\r\nregions. Restoration verifies the complete dependency SHA-256 closure before\r\nreparsing offthread; version 3 states remain readable. Native restoration scopes\r\naccess to the existing trusted contrib discovery and its five SFZ asset directories.\r\nCustom libraries require `MUZ_SFZ_ASSET_ROOTS` or a host-supplied authorized resolver;\r\ndescriptor paths never grant access. Missing, modified or unlisted dependencies\r\nfail restoration. Files must remain stable during restoration/preparation: native\r\nsize/mtime fences and canonical path checks are not an OS sandbox against hostile\r\nconcurrent filesystem mutation. Byte-identical\r\nreinstallations remain valid when timestamps change. Opt-in embedded state preserves\r\nits own bounded asset package; the instrument-state ceiling is 64 MiB and embedded\r\nassets are limited to 32 MiB. Full libraries ordinarily use linked installation. SFZ reports an unknown/infinite\r\nCLAP tail conservatively; offline rendering still uses the configured session tail.\r\nMemory-backed `AssetResolver` supplies the same paths and bytes to embedded/WASM\r\nhosts. Compile the core with `--no-default-features` for those hosts.\r\n\r\nCLAP uses the instrument state and common MIDI/expression paths. DAWProject packages\r\nactual SFZ mapping/sample dependencies according to its existing asset policy.\r\nEffect racks reject SFZ instrument state before asset reads. Unreal's restricted\r\ncontrib builders reject `embed_assets: true`; installing a library does not grant\r\npermission to redistribute its recordings or publisher mappings. Generic embedding\r\nremains available for a caller's appropriately licensed material.\r\n\r\nFor corpus reproduction, build `cargo build --bin sfz-audit` and run the commands in\r\n[contrib/SFZ.md](../contrib/SFZ.md). Normalization, dependency verification, runtime\r\npreparation and audible comparison are distinct stages in the reports. A successful\r\nparse alone does not qualify a program as fully supported.\r\n","docs/synthesis.md":"# Native synthesis and voice patches\r\n\r\nUse a preset for a ready-made sound or a `voice_patch` to define its signal flow.\r\nA patch is an ordinary source value: functions, imports, arrays, and records\r\nprovide reuse. Read [instruments](instruments.md) for track setup and\r\n[per-note expression](performance.md#per-note-expression) for the note-side syntax.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs synthesis`\r\n\r\n## Contents\r\n\r\n- [Preset controls](#preset-controls)\r\n- [A minimal voice patch](#a-minimal-voice-patch)\r\n- [Constructing signals in source](#constructing-signals-in-source)\r\n- [Editing and inspecting controls](#editing-and-inspecting-controls)\r\n- [Expression](#expression)\r\n- [Envelopes and voice lifetime](#envelopes-and-voice-lifetime)\r\n- [Stereo output](#stereo-output)\r\n- [Continuing a mono voice](#continuing-a-mono-voice)\r\n- [Zone readers and sampled instruments](#zone-readers-and-sampled-instruments)\r\n- [Node reference and limits](#node-reference-and-limits)\r\n- [Reusable instruments](#reusable-instruments)\r\n\r\n## Preset controls\r\n\r\nStart with `synth(\"pulse-bass\")`, `synth(\"bell\")`, or another entry in\r\n[std/catalogs](../std/catalogs.muz). Override controls with the second argument:\r\n\r\n```muz\r\nsynth(\"init\", {mode: \"pulse\", cutoff_hz: 700})\r\n```\r\n\r\n| Controls | Purpose |\r\n| --- | --- |\r\n| `mode` | `saw`, `pulse`, `fm`, `kick`, `snare`, `cymbal`, `fm_percussion`, or `noise` |\r\n| `filter_env`, `resonance` | Filter-envelope depth in octaves and resonance |\r\n| `sub`, `unison`, `detune_cents`, `width` | Sub oscillator, 1–5 unison voices, detuning, and stereo spread |\r\n| `fm_ratio`, `fm_index` | FM oscillator settings |\r\n| `drive_db` | Saturation drive |\r\n| `vibrato_cents`, `vibrato_hz` | Delayed vibrato |\r\n\r\n`muz devices inspect studio_synth` lists ranges and defaults. Pitched/noise modes\r\nuse gate-controlled envelopes. Percussion modes finish their decays after note-off\r\nand respond to choke; the named kick/snare/cymbal recipes are source voice patches.\r\n\r\nIn the preset synth, `width` controls **stereo spread of unison voices**; its pulse\r\noscillator has a fixed 50% duty cycle. In a voice-patch `osc` node, `width` instead\r\ncontrols **pulse duty cycle**. Use an explicit pulse node for 25% or 12.5% shapes.\r\n\r\n## A minimal voice patch\r\n\r\nA voice is one sounding note and its processing state. This complete song uses\r\nan oscillator, filter, and amplitude envelope for each voice:\r\n\r\n```muz\r\nlet simple = voice_patch(\"simple\", {\r\n    gain_db: -16,\r\n    nodes: [\r\n        {id: \"cutoff\", op: \"param\", value: 2400, min: 80, max: 10000},\r\n        {id: \"osc\", op: \"osc\", wave: \"saw\", detune: 3},\r\n        {id: \"filter\", op: \"filter\", input: \"osc\", cutoff: \"cutoff\", q: 0.7},\r\n        {id: \"env\", op: \"adsr\", attack: 0.01, decay: 0.2, sustain: 0.6, release: 0.3},\r\n        {id: \"out\", op: \"mul\", inputs: [\"filter\", \"env\"]}\r\n    ],\r\n    output: \"out\"\r\n});\r\nsong({tracks: [track(\"lead\", phrase(\"C4:q E4:q G4:h\"), simple)], tail: 1})\r\n```\r\n\r\nNodes appear after their dependencies. A signal input is a number or an earlier\r\nnode ID. Internal signals run at audio rate. `param` nodes expose named device\r\ncontrols; for example, `lead.instrument.cutoff` targets the parameter above.\r\nThe `adsr` node is an attack/decay/sustain/release envelope in seconds.\r\n\r\nConnections preserve signal magnitudes and units: frequency and cutoff signals\r\nare not audio amplitudes. Each consuming node bounds its controls; nonfinite\r\nintermediate values become zero. Explicit dimensional literals are checked on\r\nnode controls, but connected signals do not undergo full dimensional inference.\r\n\r\n## Constructing signals in source\r\n\r\n`use \"std/signal\" as s;` supplies ordinary record constructors. A patch may omit\r\n`nodes` and use nested signals directly:\r\n\r\n```muz\r\nuse \"std/signal\" as s;\r\nlet e = s.adsr(20ms, 200ms, 0.5, 300ms);\r\nlet o = s.saw();\r\nvoice_patch(\"nested\", {output:s.mul([o,e]), lifetime:{envelope:e,tail:0s}})\r\n```\r\n\r\nReusing a bound record shares one node's state. Calling a constructor twice makes\r\ntwo independent nodes even when their fields are equal. Record merges create a\r\nnew outer node while retaining any shared child records. Public parameter IDs\r\nare explicit; internal IDs are generated deterministically. Dependencies are\r\nordered during compilation, with the existing 64-node limit and bounded nesting.\r\nFlat patches remain supported. Explicit dimensional literals are checked on node\r\ncontrols (seconds for times, Hz for frequency controls); bare scalar values remain\r\naccepted. Full dimensional inference across connected signals is not performed.\r\n\r\n## Editing and inspecting controls\r\n\r\nInline `param.value` defaults, top-level exposed overrides, and `gain_db` are\r\nmutable controls, including in legacy flat patches and serialized sessions.\r\nA top-level override takes precedence over the node default; the device parameter\r\nmap takes precedence over embedded values in imported sessions. Value-only source\r\nedits preserve the prepared instrument through parameter updates. Changing a node,\r\nconnection, parameter range, or asset still prepares a replacement. Automation\r\ncontinues to address the same parameter names.\r\n\r\n`muz inspect song.muz --view patches --track lead` shows a bounded patch summary\r\nwith effective controls, node counts and asset paths. Request `--view patch_nodes`\r\nfor paged lowered nodes and `--view patch_detail` for non-node configuration.\r\nSee [nested-patch.muz](../examples/nested-patch.muz). Constructors have no runtime language cost.\r\n\r\nPlain parameters hold their value between changes. Note expressions use a separate\r\n128-frame control clock, addressed by sounding-note identity. No per-sample language\r\ncallbacks or runtime compilation occur. For an expression example, see\r\n[voice-expression.muz](../examples/voice-expression.muz).\r\n\r\n## Expression\r\n\r\nNative patches apply volume, expression, pan, and tuning automatically. Wire\r\nbrightness, vibrato, and pressure into graph inputs where you want them to act.\r\nFractional pitch and attack intensity stay precise through native rendering.\r\nMIDI file export quantizes notes and does not encode per-note curves.\r\n\r\n### Presets and standalone samplers\r\n\r\nPreset synths accept per-note `volume` (0–4), `expression` (0–1), `pan`\r\n(0–1, center 0.5), and `tuning` (semitones, −120–120), using the same\r\n`.express({...})` curves and 128-frame control clock as voice patches. Volume\r\nand expression multiply each voice after synthesis; tuning affects its pitched\r\noscillators, including the sub oscillator. Pan balances the existing stereo\r\nvoice with square-root gains, preserving its sound at center. The last control\r\nvalue before note-off remains in force during release. Instrument gain and\r\nCC 11 remain shared controls. Brightness, pressure and vibrato expression need\r\nan explicit voice graph mapping or CLAP; presets reject them instead of ignoring\r\nthem. See [independent preset swells](../examples/preset-expression.muz).\r\n\r\nSamplers accept the same per-note volume, expression, pan and tuning controls,\r\nincluding instruments built from zone lists. Volume and expression multiply each\r\nsample voice independently; pan balances its existing stereo channels with the\r\nsame square-root gains as presets, preserving the recording at center. Tuning\r\nchanges playback speed relative to the selected zone's calibrated root, without\r\nselecting a different zone or restarting playback. Curves use the existing\r\n128-frame clock and retain their last scheduled value through release or the\r\nremainder of a one-shot sample. Brightness, pressure and vibrato require a voice\r\npatch mapping or CLAP; unsupported sampler expression reports the track and\r\ninstrument kind. Instrument gain remains shared.\r\n\r\nWith a local recording at `tone.wav`, independent bow/breath swells use ordinary\r\nsource values, even when a new note overlaps the previous release tail:\r\n\r\n```muz\r\nlet swell = {volume:[[0,0.7],[0.3,1],[1,0.6]]};\r\nsong({tracks:[track(\"strings\",stack([\r\n    phrase(\"C4:q\").gate(1).express(swell),\r\n    phrase(\"E4:q\").gate(1).at(1b).express(swell)\r\n]),sample([{path:\"tone.wav\",root:60}],{release_ms:300}))],tail:0.3})\r\n```\r\n\r\n### Custom patch controls\r\n\r\nNative patches declare custom per-note lanes with `note_controls`:\r\n\r\n```muz\r\nuse \"std/signal\" as s;\r\nlet pluck = voice_patch(\"pluck\", {\r\n    note_controls: {mute: 0, pick_position: 0.5},\r\n    output: s.mul([s.saw(), s.expression(\"pick_position\")])\r\n});\r\nlet notes = phrase(\"C4:q E4:q\").express({\r\n    mute: 1, pick_position: [[0, 0.2], [1, 0.8]]\r\n});\r\n```\r\n\r\nNames must be nonempty and cannot reuse standard expression names. Defaults and\r\nvalues are finite scalars in 0..1; graph arithmetic supplies musical mapping.\r\nAt most 25 custom lanes share the existing aggregate 32-point note budget with\r\nthe seven standard expressions. Custom slots are assigned by sorted name,\r\nindependently of declaration order. Graph readers and note writes must refer to\r\nthe destination patch's declarations. Patch parameter IDs remain separate.\r\nDefaults initialize fresh voices and reset on mono ownership transfer; overlapping\r\nnotes retain independent values, including through release. Curves use the first\r\npoint before its phase and hold their last delivered value through release, on\r\nthe existing 128-frame expression clock. Changing names or\r\ndefaults changes patch structure and replaces the device on reload.\r\n\r\n### Stable variation\r\n\r\n`std/instrument.variation(pattern,seed,stream)` uses existing source `keyed_noise`\r\nand writes a stable `variation` value per source-note key; `stream` distinguishes\r\nseed streams, not expression destinations. Existing other expression fields,\r\nincluding actual pressure, remain. Declare `note_controls: {variation: 0}` on the\r\nnative patch and read `s.expression(\"variation\")`. Pin variation before transformations\r\nthat change note keys if those transformations should retain a chosen realization.\r\nVariation is computed in source before audio processing.\r\n\r\n## Envelopes and voice lifetime\r\n\r\nAn amplitude envelope shapes a note; voice lifetime determines when its processing\r\nstate can be reclaimed. By default, a patch with ADSRs retires released voices\r\nwhen all envelopes finish. If every ADSR is one-shot, it can also retire held\r\nvoices after their envelopes finish. Patches without an explicit lifetime or\r\nADSR use a short default release. Voice stealing chooses the quietest current voice.\r\n\r\nPut delays before the final envelope to gate them with the note. Use a track effect\r\nfor tails that must outlive the voice, or declare an explicit patch lifetime.\r\n\r\n### ADSR response\r\n\r\nGraph `adsr` and the preset synth use different response conventions. For fixed\r\nparameters, let `t` be seconds since note-on, `A` attack time, `D` decay time,\r\n`S` sustain level, and `R` release time. Graph times are already in seconds;\r\ndivide the preset's `attack_ms`, `decay_ms` and `release_ms` by 1000 first.\r\nThese formulas describe the envelope amplitude before velocity, gain, and other\r\nsignal processing:\r\n\r\n| Stage | Graph `adsr` | Preset `saw`, `pulse`, `fm`, `noise` |\r\n| --- | --- | --- |\r\n| Held, `t < A` | `t / A` | `t / max(A, 1/sample_rate)` |\r\n| Held, `t >= A` | `S + (1-S) * exp(-5*(t-A)/D)` | `S + (1-S) * exp(-(t-A)/D)` |\r\n| Released, after `m` samples | `E0 * exp(-9.21*m/(R*sample_rate))` | `E0 * exp(-6.9078*m/(R*sample_rate))` |\r\n\r\nAttack is linear; zero attack starts at 1 on the first sample. After one decay\r\ntime **following the attack**, the graph retains about 0.674% of the distance\r\nfrom peak to sustain (−43.43 dB), while the preset retains about 36.8%\r\n(−8.69 dB). Those dB values describe the residual above sustain, not the total\r\nlevel when `S > 0`. Sustain is an amplitude level, approached asymptotically\r\nwhile the key is held; decay has no hard endpoint. With `S = 0`, a held note\r\nkeeps decaying toward silence.\r\n\r\nNote-off, including a short `.gate(...)`, starts release from the **last computed\r\nenvelope level** `E0`, even during attack or decay. The note-off sample is the\r\nfirst multiplication (`m = 1`). One release time reduces that level by about\r\n80 dB in the graph and 60 dB in the preset; it is not a fixed time to silence.\r\nA released graph voice retires once **all** its ADSR levels are below `0.00001`;\r\na released preset voice retires below the same envelope threshold (−100 dB\r\nrelative to unity). From `E0 = 1`, this takes about `1.25*R` and `1.67*R`\r\nrespectively. Held graph and pitched/noise preset voices do not retire solely\r\nbecause their envelope has decayed below that threshold. Rendering also needs\r\nenough song `tail` to include the desired release.\r\n\r\nGraph attack is clamped to 0–30 seconds, decay to 0.0001–60 seconds, release to 0.0001–30 seconds,\r\nand sustain to 0–1. Signal-connected parameters are read each sample: held\r\nattack/decay is recomputed from note age, while release multiplies the previous\r\nlevel using the current release input. The formulas above assume those inputs\r\nstay constant. Preset ranges are listed by `muz devices inspect studio_synth`.\r\n\r\nTo translate a pitched/noise preset envelope into a graph envelope, keep attack\r\nand sustain, use `graph_decay = 5 * preset_decay_seconds`, and use\r\n`graph_release = (9.21 / 6.9078) * preset_release_seconds` (about 4/3).\r\nFor example, a 200 ms preset decay matches a 1 second graph decay; a 300 ms\r\npreset release matches about 0.4 seconds in the graph. This matches envelope\r\nrates within supported ranges and sample precision; timbre depends on the rest\r\nof each instrument. [The source example](../examples/envelope-timing.muz)\r\nimplements the conversion with an ordinary function.\r\n\r\nAdditional pitch/noise/FM/filter motion can change audible tail length. In the\r\nnative pitched/noise preset, the filter offset is `filter_env * exp(-t/D)` octaves,\r\nstarting at note-on independently of amplitude sustain/note-off.\r\n\r\n### One-shot envelopes and percussion\r\n\r\nA graph ADSR with `one_shot:true` follows its held attack/decay/sustain even after\r\nnote-off. Use sustain zero for a finite envelope. CC 120 chokes graph envelopes\r\nwith an 8 ms release (80 dB reduction); CC 123 supplies ordinary note-off.\r\nA patch whose ADSRs are all one-shot retires once all levels fall below 0.00001,\r\nafter at least two samples. Mixed patches retire after note-off once every ADSR\r\nfinishes. The 60 second graph decay bound accommodates slow source envelopes,\r\nincluding conversion of the full preset decay range.\r\n\r\n`synth` resolves `kick`, `snare` and `cymbal` to source voice patches in\r\n`std/catalogs.muz` (including the kick, snare, hat and crash presets). Their\r\noscillators, pitch sweeps, noise mix and saturation are editable source recipes.\r\n`decay_ms` remains an automatable patch parameter, 1–10000 ms; `gain_db` remains\r\na device control. Drive is selected when building the patch. These recipes ignore\r\n`attack_ms`, `sustain`, `release_ms`, and ordinary note-off. Numeric\r\nnative modes 3–5 fail with a migration diagnostic: use `synth` with the named\r\nmode instead. Saw, pulse, FM, noise and FM-percussion remain native modes.\r\n\r\nThe source percussion amplitude uses a 0.7 ms linear attack followed by\r\n`exp(-(t-0.0007)/D)`, with `graph_decay = 5*D`. Native FM-percussion retains\r\n`exp(-t/D) * min(t/0.0007,1)`. Patches preserve the gate/choke contract but are\r\nnot sample-identical to the former native recipes: the general highpass replaces\r\nthe old noise filter, the snare transient decays smoothly instead of in fixed\r\nsteps, and the patch pans its mono output at center. See\r\n[the source example](../examples/percussion-patches.muz) for stock voices and a\r\ncustom one-shot resonator.\r\n\r\n### Explicit lifetime\r\n\r\n`lifetime:{envelope:\"exciter\",tail:0.4}` selects an ADSR whose completion owns the\r\nvoice, followed by a fixed tail allowance in seconds (0–60). Other envelopes no\r\nlonger decide retirement. A one-shot envelope must finish its attack before it can\r\ncomplete; an ordinary ADSR completes after note-off. The tail starts once the\r\nselected envelope falls below 0.00001. Choke fades the complete output by 80 dB in\r\n8 ms and reclaims the voice after 10 ms. Legacy patches without `lifetime` retain\r\ntheir previous envelope-based retirement. This explicit contract lets a delay\r\ncontinue after its excitation without a dummy envelope or shared track effect.\r\n\r\n### Multisegment envelopes\r\n\r\n`mseg` accepts 1–16 `attack` segments and 1–8 `release` segments. Each is\r\n`{time:seconds,to:value,curve:\"linear\"|\"smooth\"|\"exp\"}`. Times are 0..60 seconds;\r\ntargets are -100..100. Exponential interpolation is normalized\r\n`(1-exp(-5*p))/(1-exp(-5))`, with exact endpoints. `sustain` optionally names a\r\nzero-based attack endpoint to hold. Release starts from the current value and\r\nmust end at zero. `one_shot:true` ignores note-off and requires an attack sequence\r\nending at zero. Segment completion works with explicit `lifetime`; initial zero\r\nis not completion. A segment advances on each sample, including its first.\r\n\r\n## Stereo output\r\n\r\n`output:{left:\"l\",right:\"r\"}` retains two scalar graph outputs. Mono output keeps\r\nits existing equal-power pan. Stereo uses gains `sqrt(2*(1-pan))` and\r\n`sqrt(2*pan)`: center preserves both channels and either endpoint boosts its own\r\nchannel by sqrt(2), silencing the other. Graph sample nodes accept\r\n`channel:\"left\"`, `\"right\"`, or the legacy `\"mono\"` downmix. Readers of the same\r\ncanonical file share decoded stereo storage within the patch, with independent\r\nplayheads. Equal playback settings retain stereo synchronization.\r\n\r\n## Continuing a mono voice\r\n\r\n`std/instrument.mono(patch,glide=70ms,retrigger=false)` configures a programmable\r\npatch's `voice_mode` as `legato` or `retrigger`. The default is `poly`. In mono\r\nmodes the last overlapping attack takes ownership of the current held voice;\r\nearlier note-offs and expression events cannot release or modify its new owner.\r\nLegato retains oscillator and envelope state. Retrigger resets the graph on the\r\nnew attack. Both can glide linearly in semitones over mutable `glide_ms` (0–10000).\r\nThe first note starts at its own pitch. Source score notes remain separate.\r\n\r\nThis policy does not return to an older held key when the newest key releases;\r\nsource can schedule an explicit return attack where desired. New notes following\r\nnote-off start new voices while old release tails can finish. Initial expression\r\nvalues reset on ownership transfer and subsequent expression addresses the new\r\nnote. Choke still terminates the voice. A seek reconstructs overlapping attacks\r\nin scheduled order; exact oscillator/filter history requires a contextual bounce.\r\nSee [modulated-lead.muz](../examples/modulated-lead.muz) for source variation, an MSEG, drift and glide.\r\n\r\n## Zone readers and sampled instruments\r\n\r\nA reader places a [sample map](instruments.md#samples-and-zones) inside a voice\r\ngraph so that you can add per-note filters, modulation, and custom envelopes.\r\nThe examples in this section require local recordings.\r\n\r\n### Maps, selection, and storage\r\n\r\n`s.reader(sample(zones,options),channel=\"mono\",speed=1,options={})` places an existing\r\nrecording map inside a programmable voice. It preserves roots, key/velocity ranges,\r\nzone gain, offset, loops, and note-addressed recording choices. Selection happens at\r\nattack; tuning and filtering do not reselect. Every reader rotates its own alternates\r\nin attack order, and paired left/right readers with the same map stay aligned.\r\n`sample_zone` explicitly selects that index in every reader; it must be valid in each\r\nmap. Graph preparation checks every map's coverage, and graph budgets count its zones.\r\nDecoded files share one per-patch budget across legacy `sample` and zone `reader`\r\nnodes. Canonical paths are counted once, including separate left/right readers.\r\n`sample_budget_frames` is an optional unitless integer on `voice_patch`: default\r\n8,388,608 frames (64 MiB), configurable from 1 through 134,217,728 frames (1 GiB).\r\nEach decoded frame stores two float32 channels, even for mono recordings. This is a\r\nceiling on retained sample storage, not preallocation, a process-wide memory limit,\r\nor a limit on decoder scratch space, delay buffers, or other active patches.\r\n\r\n```muz\r\nuse \"std/signal\" as s;\r\nlet recording = sample(\"strings.wav\");\r\nlet envelope = s.adsr();\r\nlet strings = voice_patch(\"strings\", {\r\n    sample_budget_frames: 33554432, // allow up to 256 MiB of decoded recordings\r\n    output: s.stereo_mul(s.stereo(s.reader(recording, \"left\"),\r\n                                s.reader(recording, \"right\")), envelope),\r\n    lifetime: {envelope: envelope, tail: 0s}\r\n});\r\n```\r\n\r\nPreparation sums unique file frame counts from metadata before decoding and reports\r\nrequired/allowed frames and bytes if they exceed the budget. Files whose metadata\r\nomits a frame count are still bounded during decoding; a failure identifies the\r\nfile, total allowance and already-decoded frames. No decoding, allocation or budget\r\nchecks are added to the audio callback. Raising the budget admits larger recording\r\nmaps without changing resampling, selection or DSP behavior. Changing this setting\r\nis structural and prepares a replacement; it is not an automatable patch control.\r\n`inspect --view patch_detail` includes the effective frame budget.\r\n\r\n### Amplitude and envelopes\r\n\r\nReaders output zone-calibrated recordings. They do not inherit the sampler device's\r\namplitude envelope, shared gain, or velocity curve. The patch applies note expression\r\nonce, with mutable `velocity_track` (0–2, default 1) controlling its velocity exponent.\r\nSet it to zero when the graph itself implements velocity amplitude. The source helper\r\n`std/instrument.sampled(source,tone,options)` explicitly builds a stereo filtered\r\ninstrument using the source's attack/release times, gain and velocity response. Its\r\nlinear segment envelope is a source policy; it does not promise identical sustain-loop\r\nor one-shot behavior to every standalone sampler configuration.\r\n\r\n### Regions, looping, and playback speed\r\n\r\nReader options add `offset` (region start in seconds, added to each zone's initial playback offset), `end` (absolute file\r\nseconds), and `loop_crossfade` (seconds, less than half each loop). Signal `speed` ranges\r\nfrom -64 to 64; negative initial speed starts at the region's last frame and reverses.\r\nZero holds the playhead. Direction changes preserve its position; pitch and speed both\r\nchange playback duration. Interpolation taps wrap inside active loops. Crossfades\r\nconsume the overlapped beginning/end, shortening the repeated period by their length;\r\nthey are for clean sustained recordings, not pitch calibration of single-cycle waves.\r\nA zone's initial playback offset may lie inside its loop; the loop may wrap before\r\nthat initial position, while remaining inside the reader region. Note-off exits a\r\nnon-one-shot loop and continues toward the region end. One-shot zones\r\nkeep looping until the patch's own lifetime/choke contract completes.\r\n\r\nA reader can itself be the explicit `lifetime.envelope`: it completes at the region\r\nend. An indefinitely looped reader needs a separate envelope-based completion contract.\r\nUse `s.reader` signals with `std/instrument.crossfade(a,b,control)` for independently\r\ncontrolled dynamic layers; alternates inside each layer retain round-robin semantics.\r\n`std/instrument.releases(pattern,duration,timing)` builds a separate release-recording\r\nlane at performed note ends, including gate and release offsets. Keep recording\r\nselection for that release lane independent of the attack map.\r\n\r\n## Node reference and limits\r\n\r\n| Operation | Inputs |\r\n| --- | --- |\r\n| `param` | `value`, `min`, `max`; node ID becomes the parameter name |\r\n| `frequency`, `velocity` | Current voice's frequency in Hz / attack intensity |\r\n| `expression` | `kind`: volume, pan, tuning, vibrato, expression, brightness, pressure, or a declared custom note control |\r\n| `osc` | `wave`: sine/saw/pulse/triangle; `ratio`, `detune` in cents, optional `hz`, `fm` in Hz, pulse `width`, `phase` in cycles |\r\n| `noise` | Deterministic bipolar white noise |\r\n| `adsr` | `attack`, `decay`, `release` in seconds; `sustain` 0..1; optional `one_shot:true` |\r\n| `sum`, `mul` | `inputs` array of signals |\r\n| `drive` | `input`, linear drive `amount`; tanh saturation |\r\n| `filter` | `input`, `cutoff` Hz, `q`; `mode`: lowpass/highpass/bandpass/notch |\r\n| `delay` | `input`, `seconds`, `feedback`; fixed `max_seconds` allocation; optional feedback `damping` and `max_feedback` |\r\n| `mseg` | Bounded attack/release segment arrays; optional sustain endpoint and one-shot |\r\n| `map` | `input`, `kind`: clamp/abs/reciprocal/exp2/log2; clamp `min`/`max` |\r\n| `hold`, `slew` | `input`; hold `rate_hz`, or slew `rise`/`fall` seconds |\r\n| `shape` | `input`, static `points`, `quality`: adaa/raw |\r\n| `resonator` | `input`, `frequency` Hz, `decay` amplitude T60 seconds |\r\n| `reader` | Sample `source` (lowered to `zones`), channel, speed, region/loop options |\r\n| `sample` | WAV/FLAC `path`, `root` pitch, optional `loop:true`; `channel`: mono/left/right |\r\n\r\nA patch has 16 voices, at most 64 nodes, and at most 16 inputs to a sum/product.\r\nDelay memory is limited to two seconds per voice, with at most one second per\r\ndelay. Feedback defaults to a bound of ±0.98; `max_feedback` can explicitly raise\r\nthat bound as described below. Sample storage defaults to 8,388,608 decoded stereo\r\nframes and is configurable through `sample_budget_frames`.\r\n\r\nAn explicit scalar or stereo-pair output is required. Graphs are acyclic;\r\nfeedback belongs inside delay nodes. Cycles, forward references, and unknown\r\nfields fail preparation. Dynamic frequency, filter, and envelope inputs have\r\nbounded ranges. Native sample resampling and nonlinear saturation are not\r\noversampled mastering processors.\r\n\r\n### Mapping and smoothing\r\n\r\n`map` consumes `input` and a `kind`: `clamp` (with signal `min`/`max`), `abs`,\r\n`reciprocal`, `exp2`, or `log2`. Reciprocal returns zero within ±1e-20 of zero;\r\nexp2 bounds its exponent to ±100; log2 floors its argument at 1e-20. These explicit\r\noperations retain tuning precision without baking pitch policy into each processor.\r\n`std/signal.octaves(base,amount)` and `period(frequency)` compose them.\r\n\r\n`hold` captures its input immediately, then at `rate_hz` (bounded 0..sample rate).\r\n`slew` starts at its first input and smooths with separate `rise`/`fall` time\r\nconstants in seconds (0..60; zero is immediate). After one time constant the\r\nremaining difference is about 36.8%. `s.drift()` composes noise, hold and slew.\r\nThese states reset per voice; shared score motion uses ordinary automation.\r\nNoise uses a patch-wide deterministic stream, so changing graph/voice\r\nevaluation order may change a drift realization.\r\n\r\n### Filters and oscillator phase\r\n\r\nGraph filters expose `bandpass` (the SVF band state, gain Q at its center) and\r\n`notch` (input minus the damped band), alongside lowpass and highpass modes.\r\nOscillator `phase` is an offset in cycles. Sine accepts a signal for phase modulation;\r\nother waves currently accept a constant phase only. This is neither hard sync nor a\r\npromise of alias-free arbitrary modulation. In particular, changing a discontinuous\r\nwave's phase requires more than its ordinary base-frequency BLEP correction.\r\n\r\n### Transfer curves\r\n\r\n`shape` prepares 2–64 increasing `[input,output]` points into a 2049-entry linear\r\ntransfer table. Values outside its domain hold the endpoint output. Default\r\n`quality:\"adaa\"` evaluates the exact integral of that prepared interpolant between\r\nsuccessive inputs (first-order antiderivative antialiasing). `quality:\"raw\"` performs\r\nordinary lookup, useful for control mappings or deliberate nonlinear artifacts.\r\nADAA reduces aliasing but has a small averaging/phase effect and does not eliminate\r\nall aliases; raw and ADAA need not null.\r\n\r\n### Damped delays\r\n\r\nDelays optionally take signal `damping` in Hz for a one-pole feedback lowpass, and\r\nstatic `max_feedback` (0–0.99999). The default is 0.98 with no damping.\r\n`s.damped_delay` opts into the expanded bound. Seconds remain actual delay time;\r\n`s.period(frequency)` produces a nominal comb period. Loop-filter phase and fractional\r\ninterpolation alter ringing pitch and decay, so this is not a calibrated string model.\r\n\r\n### Resonators\r\n\r\n`resonator` accepts `input`, `frequency` in Hz and amplitude-T60 `decay` in seconds.\r\nIt is a damped quadrature oscillator driven on its real component. Frequency is\r\nbounded to 1..0.45*sample_rate and decay to 0.001..60 seconds. Pole magnitude is\r\n`exp(-3*ln(10)/(decay*sample_rate))`; constant controls prepare coefficients once.\r\nDynamic controls rotate and shrink the same two-state vector, avoiding unstable\r\ncoefficient interpolation. Output is the real component, with no hidden gain\r\nnormalization. Source chooses modal gains and bank size.\r\n\r\nConstant oscillator detune, filter coefficients, and resonator coefficients are\r\nprepared once when their operands are literals. Signal-connected controls retain\r\nsample-rate evaluation; this optimization does not introduce a separate control\r\nclock or alter arithmetic ordering for the existing oscillator/filter operations.\r\n\r\n## Reusable instruments\r\n\r\n`std/synthesis` supplies `pad`, `lead`, `struck`, `pluck`, `texture`, and\r\n`layered(soft,loud)` as ordinary editable instrument recipes. Their suggested ranges,\r\ncontrols and gain choices are documented next to their source definitions. The legacy\r\n`choir` preset remains an unchanged alias of `pad`; the recipes use distinct\r\nsignal structures rather than silently changing those presets.\r\n\r\n`std/instrument.sound` packages an instrument, insert chain, suggested range and\r\nsource macro mappings. `play` constructs its track; `automate` turns a normalized\r\nmacro curve into ordinary target automation lanes. Existing one-owner-per-target\r\nrules still apply. [instrument-design.muz](../examples/instrument-design.muz) exercises the combined workflow.\r\nSampled layers accept existing sample devices, for example:\r\n\r\n```muz\r\nuse \"std/synthesis\" as native;\r\nlet strings = native.layered(sample(\"soft.wav\"), sample(\"loud.wav\"));\r\n// Pressure expression now controls the crossfade independently for each note.\r\n```\r\n\r\n### Preset catalogs\r\n\r\n`synth(name,params={},presets=catalog.synth_presets)` accepts an alternative\r\nsource preset table. A raw `{type:\"synth\",name:\"my-patch\",...}` device record can\r\nalso describe a custom device; fill in its actual fields before use.\r\n\r\nSynth overrides use checked names for modes. Unknown names and numeric mode\r\noverrides are rejected by the source helper. `synth_mode_codes` translates names\r\nto integer device codes; raw device records and numeric parameter inspection are\r\nthe lower-level engine interface.\r\n\r\nThe current palette has no wavetable morphing, granular synthesis, convolution,\r\ntime stretching, or general feedback graphs.\r\n\r\n## Next steps\r\n\r\nRoute the instrument through [production effects](production.md), shape its notes\r\nwith [performance](performance.md), and [audition or render](workflow.md) the result.\r\n","docs/workflow.md":"# Checking, auditioning, and delivering a piece\r\n\r\nUse this guide after [getting started](getting-started.md). Unless shown otherwise,\r\ncommands use a `song.muz` in the current directory. Substitute your project path\r\nwhen working from the engine checkout. Output paths are relative to the command's\r\nworking directory; source asset paths follow their declaring modules.\r\n\r\n[Documentation index](README.md) · Offline: `muz docs workflow`\r\n\r\n## Contents\r\n\r\n- [Evaluate, format, and check](#evaluate-format-and-check)\r\n- [Inspect a song](#inspect-a-song)\r\n- [Live sessions](#live-sessions)\r\n- [Rendering and delivery](#rendering-and-delivery)\r\n- [Named comparisons and delivery collections](#named-comparisons-and-delivery-collections)\r\n\r\n## Evaluate, format, and check\r\n\r\n| Command | Purpose |\r\n| --- | --- |\r\n| `muz eval material.muz` | Evaluate an ordinary source value without preparing audio. Useful for inspecting generated patterns or alternatives. |\r\n| `muz fmt song.muz` | Format source in place. |\r\n| `muz fmt --check song.muz` | Check formatting without rewriting. |\r\n| `muz check song.muz` | Validate source, musical constraints, available assets/plugins, and the prepared graph. |\r\n| `muz check song.muz --json` | Return machine-readable check results and diagnostics. |\r\n\r\nA successful check reports note/track counts, expanded graph resources, and\r\nremaining policy diagnostics. Error messages identify the declaring source;\r\nsee [diagnostics](language.md#diagnostics-and-limits). Plugin checks require the\r\nactual plugin and any needed license/assets on this machine.\r\n\r\n## Inspect a song\r\n\r\nInspection reads structure and events without playing audio:\r\n\r\n```sh\r\nmuz inspect song.muz\r\nmuz inspect song.muz --view sections\r\nmuz inspect song.muz --view score --track lead --limit 100\r\nmuz inspect song.muz --view performance --track lead --section opening\r\nmuz inspect song.muz --view automation\r\n```\r\n\r\nThe default view is a bounded summary. `score` shows authored notes and metadata;\r\n`performance` shows scheduled notes and controls. A note key is its exact identity;\r\na display label is not a lookup key. Kits expose physical tracks such as `drums.kick`.\r\n\r\nMost views return `{revision, view, rows, total, next}`. Pass `next` as\r\n`--offset NEXT` to continue. Pages allow 1–1,000 rows and at most 1 MiB of serialized\r\nrow data. `--start-tick`/`--end-tick` select a score range; `--section` resolves the\r\nsection to that range. For dense material, use `performance_overview` before\r\nrequesting detailed ranges. The [embedding reference](embedding.md#paged-inspection)\r\nlists views, filter semantics, and the legacy unfiltered `graph` exception.\r\n\r\nTo inspect an automation lane's points, use\r\n`--view automation_points --track TARGET`. Native patches have separate\r\n`patches`, `patch_nodes`, and `patch_detail` views.\r\n\r\n## Live sessions\r\n\r\n### Start and control playback\r\n\r\nIn one terminal:\r\n\r\n```sh\r\nmuz serve song.muz --stopped\r\n```\r\n\r\nLeave it running. In another terminal, use:\r\n\r\n| Command | Action |\r\n| --- | --- |\r\n| `muz status` | Read transport, revision, and device telemetry. |\r\n| `muz play` / `muz stop` | Start or pause playback without rewinding. |\r\n| `muz restart` | Seek to the audition-loop start or beginning, preserving playing state. |\r\n| `muz seek --section opening` | Seek to a named section; `--beat` and `--tick` also work. |\r\n| `muz audition opening` | Loop a named section and start playback. |\r\n| `muz loop --off` | Disable looping. |\r\n| `muz panic` | Silence active voices and effects without treating it as a rewind. |\r\n| `muz shutdown` | Stop the server and cancel its jobs. |\r\n\r\nWithout `--stopped`, the server starts playing immediately. `--headless` provides\r\na silent transport clock, session controls, and rendering without PipeWire output.\r\nSource and selected assets are watched. A failed edit leaves the last accepted\r\nsession running; fix the reported error and save again. Compatible changes can\r\nretain sounding voices and processors; structural changes require prepared\r\nreplacements. See [embedding](embedding.md#live-revisions) for the host contract.\r\n\r\nThe applied revision starts at zero and advances only after the audio callback\r\naccepts an edit. Source/watch generations track observations separately; a plugin\r\nrestart can advance revision without a source edit. While one revision is pending,\r\nonly the latest queued source candidate is retained. A rejected candidate does not\r\nreplace accepted source or processors, and a later receipt for an older valid edit\r\ndoes not erase a newer source error.\r\n\r\nNative output, plugin main-thread servicing/restarts, SFZ replay, and processor\r\nretirement share the [native coordinator](embedding.md#native-output-coordinator).\r\nPlugin restart requests rebuild accepted state without rereading an invalid file.\r\nNormal startup reports unavailable audio instead of silently choosing headless.\r\nUse `--headless` explicitly when a silent clock is intended.\r\n\r\nLive seeks and loops restore overlapping notes and prior controllers. SFZ\r\ntransport additionally prepares bounded history/checkpoints off the audio thread.\r\nAn audition range is half-open; enabling it seeks its start, disabling preserves\r\nposition, and seeking outside it returns to its start. Non-SFZ transport cannot\r\nrecreate arbitrary prior oscillator or effect history; use a section bounce when\r\nthat history matters.\r\n\r\n### Socket clients\r\n\r\nThe default Unix socket is `/tmp/muz.sock`. For multiple sessions, give each\r\nserver a distinct `--socket PATH` and pass the same path to its client commands.\r\n`muz call` sends a newline JSON request through this interface:\r\n\r\n```sh\r\nmuz call '{\"command\":\"status\"}'\r\nmuz call '{\"command\":\"inspect\",\"view\":\"performance\",\"track\":\"lead\",\"revision\":7,\"offset\":0,\"limit\":100}'\r\n```\r\n\r\nReplace `7` with the revision you intend to inspect. Supplying a revision prevents\r\naccidentally paging across edits; a mismatched revision fails. Successful responses\r\nwrap the result as `{\"ok\":true,\"result\":...}`. Use the returned page's `next` for\r\ncontinuation. [src/control.rs](../src/control.rs) defines the request variants.\r\n\r\nTransport success keeps the existing `{\"ok\":true,\"result\":{\"queued\":true}}`\r\nshape: it acknowledges admission, not callback application. Read status to observe\r\nthe applied transport; async callback rejection appears in `last_error` and the\r\nserver's rejected-event diagnostics. Output health fields report real backend\r\ncounters. `runtime_mapping_pending` suppresses device IDs while a newer callback\r\nrevision awaits coordinator promotion.\r\n\r\n### Queued renders\r\n\r\n```sh\r\nmuz render --socket /tmp/muz.sock --section opening -o opening.wav\r\nmuz jobs\r\nmuz cancel 1\r\n```\r\n\r\nUse the job ID returned by the submission instead of the illustrative `1` above.\r\n\r\nSubmission returns a job immediately. The server runs two renders concurrently\r\nand queues up to 32 more in submission order. `muz jobs` reports `queued`,\r\n`running`, `finished`, `failed`, or `cancelled`, with the source and accepted\r\nrevision captured at submission.\r\n\r\nLater source edits do not change a queued job's musical/graph data. External\r\nassets remain ordinary files, so changing their contents can still affect a job.\r\nDuplicate active output paths and a full waiting queue are rejected.\r\n\r\nCancellation works for waiting and running jobs and preserves an existing output\r\nfile. Failed or cancelled workers release their slots. Shutdown cancels workers\r\nand discards waiting jobs; the in-memory queue does not survive a server restart.\r\n\r\n## Rendering and delivery\r\n\r\n### Choose a render scope\r\n\r\n```sh\r\nmuz render song.muz -o master.wav --format pcm24\r\nmuz render song.muz --section opening -o opening.wav\r\nmuz render song.muz --start 10 --seconds 5 -o excerpt.wav\r\n```\r\n\r\nDisk rendering reads the source on disk. To capture the live server's applied\r\nrevision, use `render --socket PATH` without a source argument; that queues a job.\r\n\r\n| Option | Meaning |\r\n| --- | --- |\r\n| `--section NAME` | Render the named section with preceding context from song start. |\r\n| `--start SECONDS` | Set the clock-time output start; overrides the selected section's start. |\r\n| `--seconds LENGTH` | Set the entire output duration, including any release audio; `--tail` does not extend it. |\r\n| `--tail SECONDS` | Set release/effect time after the score or section end when `--seconds` is omitted; defaults to the song's `tail`. |\r\n| `--solo TRACK` | Audition a physical track through its routing and master. Repeat to select more tracks. |\r\n| `--tap TRACK_OR_BUS` | Capture the specified graph output boundary. |\r\n| `--format float32` / `--format pcm24` | Choose WAV sample format; float32 is default, pcm24 uses TPDF dither. |\r\n| `--sample-rate RATE` | Output sample rate; default 48000 Hz. |\r\n| `--block-size FRAMES` | Processing block size; default 256, maximum 1024. |\r\n\r\nSection renders and dry stems process preceding context from song start and\r\ndiscard that audio, retaining instrument/effect history. Score timestamps are\r\nnot rebased: tempo changes through the section end (including a change exactly\r\nat its end) remain active, while later changes and material are excluded.\r\nParallel routes are latency-aligned and export latency is trimmed. Keep enough\r\ntail for the intended releases.\r\n\r\nWithout `--seconds`, output ends at the score or selected section end plus the\r\ntail, measured from the selected start. With `--seconds`, the output length is\r\nexactly that many seconds: `--start 10 --seconds 5 --tail 2` still writes five\r\nseconds, not seven. Include any desired release audio within that length. A\r\nclock-time window alone does not cut musical events at an earlier excerpt\r\nboundary to create a separate release segment. These scope rules also apply to\r\nstems, queued renders, and render-recipe options.\r\n\r\n### Track stems and bus taps\r\n\r\n```sh\r\nmuz stems song.muz -o stems/\r\nmuz stems song.muz --wet -o solo-auditions/\r\nmuz render song.muz --tap hall -o hall-return.wav\r\n```\r\n\r\nOrdinary stems capture each physical track **after inserts and pan, before output\r\ngain, sends, and master**. A shared return can be exported by bus name with `--tap`.\r\nWet stems are solo auditions through effect returns and the nonlinear master;\r\nthey do not sum back to the mix. Solo keeps detector sources processing.\r\nSee [signal flow](production.md#signal-flow) for the boundaries.\r\n\r\n### Plugin render behavior\r\n\r\nDisk exports, including stems and queued bounces, initialize VST3 processors in\r\noffline mode and use that mode for every audio block. Live playback uses realtime\r\nmode. This lets plugins complete streaming or other required work when rendering\r\nfaster than wall clock; plugins may also choose different offline quality, so live\r\nand exported audio need not null exactly.\r\n\r\n### Analyze a rendered file\r\n\r\n```sh\r\nmuz analyze master.wav\r\n```\r\n\r\nAnalysis reports integrated LUFS, loudness range, true peak, sample peak, RMS,\r\nDC, and stereo correlation. Use it when a delivery requirement or a listening\r\nquestion needs measurements. Routine renders need no extra analysis after a\r\nsuccessful command exit; see the [verification budget](../AGENTS.md#verification-budget).\r\n\r\n### MIDI and DAW handoff\r\n\r\nUse [MIDI interchange](language.md#midi-interchange) for musical MIDI files, or\r\n[DAWProject export](dawproject.md) for an editable DAW archive. Read the fidelity\r\nreport before relying on a DAWProject handoff.\r\n\r\n## Named comparisons and delivery collections\r\n\r\nA source module can export named lists of `{name, song, options}` records. `song`\r\nis an ordinary evaluated song, so candidates can come from different arguments\r\nto the same composer function. The following fragment assumes `version` and `chosen` are already defined:\r\n\r\n```muz\r\nlet compare = [\r\n    {name:\"held\", song:version(0), options:{section:\"final-chorus\",tail:2}},\r\n    {name:\"lifted\", song:version(7), options:{section:\"final-chorus\",tail:2}}\r\n];\r\nlet delivery = [\r\n    {name:\"master\",song:chosen,options:{format:\"pcm24\",tail:3}},\r\n    {name:\"lead-tap\",song:chosen,options:{tap:\"lead\",tail:3}},\r\n    {name:\"hall-return\",song:chosen,options:{tap:\"hall\",tail:3}}\r\n];\r\n```\r\n\r\nRun `muz batch revisions.muz compare -o out/compare --match-levels` or\r\n`muz batch revisions.muz delivery -o out/delivery`. Names use letters, numbers,\r\nhyphens and underscores. Options use the renderer fields:\r\n`section`, `start`, `seconds`, `tail`, `solo`, `tap`, `format`, `sample_rate`,\r\nand `block_size`. `start`, `seconds` and `tail` are seconds; section names resolve\r\nagainst each candidate. Omitted options retain ordinary render defaults.\r\n\r\nThe module and all candidate songs are evaluated before starting the collection.\r\nThe two-worker queue accepts up to 34 captured outputs, which run in isolated\r\nchild processes. Ctrl-C cancels outstanding work; failed outputs preserve existing files.\r\n`renders.json` records each result or failure and its exact render scope. Batch\r\nrenders are disk-source captures, so they have no live-server revision number.\r\n\r\n`listen.html` plays the results and switches candidates at the same playback\r\nposition. With `--match-levels`, measured integrated loudness determines listening\r\nattenuation to the quietest measurable candidate. The WAVs and their production\r\nprocessing are unchanged. Very short or silent candidates without measurable\r\nintegrated loudness remain unmatched. Keep arrangement, preceding context, render\r\nscope and controllable randomness consistent when comparing one musical choice.\r\n\r\nFor draggable loop selection, synchronized A/B/X switching, or repeated blind\r\npreference trials with deferred statistical reports, use the\r\n[muz-ab comparator skill](../.agents/skills/muz-ab/SKILL.md). Its local player\r\nconsumes the matched batch manifest directly and preserves the original bounces.\r\n\r\nName output boundaries explicitly in delivery recipes: a track tap, shared\r\nreturn, and wet solo audition have different uses. See\r\n[stems and taps](#track-stems-and-bus-taps) before combining exported layers.\r\n\r\nSee [revision-workflow.muz](../examples/revision-workflow.muz) for a complete source example.\r\n\r\n## Next steps\r\n\r\nRevise musical material with the [language guide](language.md), adjust the graph\r\nwith [production](production.md), or use the\r\n[blind comparator](../.agents/skills/muz-ab/SKILL.md) for controlled listening trials.\r\n","examples/envelope-timing.muz":"// Translate the amplitude envelope of a pitched/noise preset into graph seconds.\r\n// Decay approaches sustain; release starts from the level reached at key release.\r\nfn graph_adsr(p) = {\r\n    id: \"env\",\r\n    op: \"adsr\",\r\n    attack: p.attack_ms / 1000,\r\n    decay: 5 * p.decay_ms / 1000,\r\n    sustain: p.sustain,\r\n    release: (9.21 / 6.9078) * p.release_ms / 1000\r\n};\r\nlet timing = {attack_ms: 10, decay_ms: 200, sustain: 0.2, release_ms: 300};\r\nlet graph = voice_patch(\"translated-envelope\", {\r\n    gain_db: -18,\r\n    nodes: [\r\n        graph_adsr(timing),\r\n        {id: \"osc\", op: \"osc\", wave: \"saw\"},\r\n        {id: \"out\", op: \"mul\", inputs: [\"osc\", \"env\"]}\r\n    ],\r\n    output: \"out\"\r\n});\r\n// A short key hold enters release during decay. Timbres remain independently editable.\r\nlet notes = note(\"C3\", 1b).gate(0.5);\r\nsong({\r\n    tempo: 120,\r\n    tracks: [track(\"graph\", notes, graph), track(\"preset\", notes.at(2b), synth(\"init\", timing))],\r\n    tail: 0.6\r\n})\r\n","examples/instrument-design.muz":"// Small engine example; complete pieces belong in muz-projects.\r\nuse \"std/synthesis\" as synths;\r\nuse \"std/instrument\" as instrument;\r\nlet pad = instrument.sound(\r\n    synths.pad(),\r\n    [fx(\"chorus\", {mix: 0.1})],\r\n    macros = {brightness: [{target: \"instrument.tone\", offset: 200, scale: 4000}]}\r\n);\r\nlet notes = phrase(\"C3:q E3:q G3:q B3:q\");\r\nsong({\r\n    tempo: 120,\r\n    tracks: [\r\n        instrument.play(\"pad\", phrase(\"[C3 E3 G3]:w\"), pad),\r\n        track(\"lead\", instrument.variation(notes.gate(1.1), 3), synths.lead()),\r\n        track(\"body\", notes.at(4b), synths.struck(500ms)),\r\n        track(\"pluck\", notes.at(8b), synths.pluck()),\r\n        track(\"texture\", note(\"C4\", 4b, at = 12b), synths.texture())\r\n    ],\r\n    automation: instrument.automate(\"pad\", pad, \"brightness\", curve([[0b, 0], [4b, 1]])),\r\n    tail: 4\r\n})\r\n","examples/midi-messages.muz":"// Export directly: muz midi export examples/midi-messages.muz -o out/messages.mid\r\n// A pattern root needs no instrument and can preserve meta, SysEx and opaque messages.\r\nstack([\r\n    meta(3, [109, 117, 122]),\r\n    bank(0),\r\n    program(0),\r\n    cc(64, 0),\r\n    note_on(\"C4\", 0.7),\r\n    bend(0.15, at = 1b),\r\n    pressure(0.3, at = 1b),\r\n    poly_pressure(60, 0.4, at = 2b),\r\n    note_off(\"C4\", at = 3b),\r\n    bend(0, at = 3b),\r\n    sysex([126, 127, 9, 1], at = 4b)\r\n])\r\n","examples/modulated-lead.muz":"use \"std/signal\" as s;\r\nuse \"std/instrument\" as instrument;\r\nlet env = s.mseg(\r\n    [{time: 10ms, to: 1}, {time: 200ms, to: 0.6}],\r\n    [{time: 160ms, to: 0}],\r\n    sustain = 1\r\n);\r\nlet motion = s.add([s.mul([s.drift(), 0.1]), s.expression(\"variation\")]);\r\nlet tone = s.filter(s.saw(), s.octaves(800Hz, motion));\r\nlet voice = instrument.mono(\r\n    voice_patch(\"lead\", {\r\n        note_controls: {variation: 0},\r\n        gain_db: -16,\r\n        output: s.mul([tone, env]),\r\n        lifetime: {envelope: env, tail: 0s}\r\n    }),\r\n    glide = 70ms\r\n);\r\nlet notes = instrument.variation(phrase(\"C4:q E4:q G4:q B4:q\").gate(1.1), seed = 7);\r\nsong({tracks: [track(\"lead\", notes, voice)], tail: 0.5})\r\n","examples/nested-patch.muz":"use \"std/signal\" as s;\r\nlet env = s.adsr(20ms, 400ms, 0.5, 300ms);\r\nlet tone = s.param(\"tone\", 1800Hz, 80Hz, 12000Hz);\r\nfn voice(detune) = s.filter(s.saw({detune: detune}), tone);\r\nlet instrument = voice_patch(\"stereo\", {\r\n    gain_db: -16,\r\n    output: s.stereo_mul(s.stereo(voice(-8), voice(8)), env),\r\n    lifetime: {envelope: env, tail: 0s}\r\n});\r\nsong({tracks: [track(\"lead\", phrase(\"[C4 E4 G4]:h [D4 F4 A4]:h\"), instrument)], tail: 1})\r\n","examples/percussion-patches.muz":"// Stock percussion recipes live in std/catalogs. This additional resonator uses\r\n// the same general one-shot ADSR capability; note-off does not truncate its decay.\r\nlet wood = voice_patch(\"wood\", {\r\n    gain_db: -14,\r\n    nodes: [\r\n        {id: \"a\", op: \"osc\", wave: \"sine\", hz: 920},\r\n        {id: \"b\", op: \"osc\", wave: \"sine\", hz: 1460},\r\n        {id: \"body\", op: \"sum\", inputs: [\"a\", \"b\"]},\r\n        {\r\n            id: \"env\",\r\n            op: \"adsr\",\r\n            attack: 0.0007,\r\n            decay: 0.18,\r\n            sustain: 0,\r\n            release: 0.008,\r\n            one_shot: true\r\n        },\r\n        {id: \"out\", op: \"mul\", inputs: [\"body\", \"env\"]}\r\n    ],\r\n    output: \"out\"\r\n});\r\nsong({\r\n    tempo: 110,\r\n    tracks: [\r\n        track(\"kick\", phrase(\"C2:q r:q C2:q r:q\"), synth(\"kick\")),\r\n        track(\"snare\", phrase(\"r:q D2:q r:q D2:q\"), synth(\"snare\")),\r\n        track(\"hat\", note(42, 1/2b).repeat(8), synth(\"hat\")),\r\n        track(\"wood\", phrase(\"r:e C4:e r:q C4:e r:e C4:q\").gate(0.1), wood)\r\n    ],\r\n    tail: 0.4\r\n})\r\n","examples/preset-expression.muz":"// Overlapping chords keep independent swells, including their release tails.\r\nlet swell = {volume: [[0, 0.58], [0.38, 1], [1, 0.55]]};\r\nsong({\r\n    title: \"Independent preset swells\",\r\n    tempo: 80,\r\n    tracks: [\r\n        track(\r\n            \"halo\",\r\n            stack([\r\n                phrase(\"[C4 E4 G4]:w\").gate(1).express(swell),\r\n                phrase(\"[D4 F4 A4]:w\").gate(1).at(2b).express(swell)\r\n            ]),\r\n            synth(\"pad\")\r\n        )\r\n    ],\r\n    tail: 3\r\n})\r\n","examples/racks.muz":"use \"std/mix\" as mix;\r\nfn tone(cutoff = 1400) = rack(\r\n    [[fx(\"lowpass\")]],\r\n    {id: \"tone\", expose: {cutoff: \"0.0.cutoff_hz\"}, cutoff: cutoff}\r\n);\r\nlet motion = lfo(2b, 8b, low = 450, high = 3200);\r\nsong({\r\n    tracks: [\r\n        track(\"pulse\", phrase(\"[C4 E4 G4]:q r:q [D4 F4 A4]:q r:q\").repeat(2), synth(\"pad\"), {\r\n            chain: [tone(), mix.parallel_compression(0.2)],\r\n            sends: {room: {gain: -20, pre: false}}\r\n        })\r\n    ],\r\n    buses: [bus(\"room\", [fx(\"reverb\", {mix: 1, decay_s: 1.3})])],\r\n    automation: [automation(\"pulse.tone.cutoff\", motion)],\r\n    master: [fx(\"limiter\", {ceiling_db: -3})],\r\n    tail: 2\r\n})\r\n","examples/revision-workflow.muz":"use \"std/arrange\" as a;\r\nuse \"std/mix\" as mix;\r\n\r\nlet meter = [3, 4];\r\nlet two_measures = a.bars(2, meter);\r\nlet melody = phrase(\"E5:q G5:e B5:e A5:q | G5:q E5:q@bloom r:q\");\r\nlet bass = phrase(\"E2:h r:q | C3:h r:q\");\r\n\r\n// This gesture is deliberately project source: a tag and velocity drive an\r\n// arbitrary filter contour. Its timing is resolved after final placement.\r\nfn bloom(context) {\r\n    let notes = a.material(context, \"lead\").select(\"bloom\").notes;\r\n    let n = notes[0];\r\n    let onset = mix.note_start(n, context.timing);\r\n    let finish = mix.note_end(n, context.timing);\r\n    [\r\n        automation(\r\n            \"lead.instrument.cutoff_hz\",\r\n            curve([\r\n                [seconds_at(context.start, context.timing), 1200],\r\n                [onset, 1200],\r\n                [onset + 20ms, 1800 + 4200 * n.velocity],\r\n                [finish, 1200]\r\n            ])\r\n        ),\r\n        mix.throws(\r\n            a.material(context, \"lead\"),\r\n            \"bloom\",\r\n            \"lead.send.echo\",\r\n            -12,\r\n            120ms,\r\n            context.timing,\r\n            start = seconds_at(context.start, context.timing)\r\n        )\r\n    ]\r\n}\r\nlet chorus = a.passage(two_measures, [a.part(\"lead\", melody), a.part(\"bass\", bass)], [bloom]);\r\nlet bridge = a.passage(\r\n    two_measures,\r\n    [a.part(\"lead\", melody.transpose(-5)), a.part(\"bass\", bass.transpose(3))],\r\n    [bloom],\r\n    [[0b, 100]]\r\n);\r\n\r\nfn version(extra_measures = 0, final_interval = 0) {\r\n    let last = a.edit(\r\n        chorus,\r\n        \"lead\",\r\n        fn(p) => a\r\n            .require(p, \"bloom\")\r\n            .refine(\"bloom\", fn(n) => {\r\n                pitch: n.pitch + final_interval,\r\n                duration: n.duration * 1.5\r\n            })\r\n    );\r\n    let form = a.sequence([\r\n        a.occurrence(\r\n            \"opening\",\r\n            a.passage(two_measures + a.bars(extra_measures, meter), [a.part(\"bass\", bass)])\r\n        ),\r\n        a.occurrence(\"chorus\", chorus),\r\n        a.occurrence(\"bridge\", bridge),\r\n        a.occurrence(\"final-chorus\", last)\r\n    ]);\r\n    a.build(form, {\r\n        title: \"Revision study\",\r\n        meter: meter,\r\n        tempo: 120,\r\n        tracks: [\r\n            track(\"lead\", rest(0b), synth(\"glass-lead\"), {gain: -6, sends: {echo: -120}}),\r\n            track(\"bass\", rest(0b), synth(\"pulse-bass\"), {gain: -6})\r\n        ],\r\n        buses: [bus(\"echo\", [fx(\"delay\", {mix: 1, time_beats: 0.75, feedback: 0.25})])],\r\n        master: mix.master(),\r\n        tail: 1\r\n    })\r\n}\r\n\r\n// Both candidates have the same arrangement, seed, context and render boundary.\r\nlet compare = [\r\n    {name: \"held\", song: version(2, 0), options: {section: \"final-chorus\", tail: 1}},\r\n    {name: \"lifted\", song: version(2, 7), options: {section: \"final-chorus\", tail: 1}}\r\n];\r\nlet chosen = version(2, 0);\r\nlet delivery = [\r\n    {name: \"master\", song: chosen, options: {format: \"pcm24\", tail: 1}},\r\n    {name: \"lead-tap\", song: chosen, options: {tap: \"lead\", tail: 1}},\r\n    {name: \"echo-return\", song: chosen, options: {tap: \"echo\", tail: 1}}\r\n];\r\nchosen\r\n","examples/sidechain-levels.muz":"// 0-4b: audible kick and ducking reference.\r\n// 4-8b: kick output 18 dB quieter; detector and ducking remain unchanged.\r\n// 8-12b: restore the original audible kick level, with detector 12 dB quieter.\r\nsong({\r\n    tempo: 120,\r\n    tracks: [\r\n        track(\"kick\", phrase(\"C2:q\").repeat(12), synth(\"kick\", {decay_ms: 120}), {\r\n            chain: [fx(\"gain\", {id: \"key_level\", gain_db: 0})],\r\n            gain: -12\r\n        }),\r\n        track(\"bass\", note(\"C2\", 12b).gate(1), synth(\"pulse-bass\", {sustain: 0.8}), {\r\n            chain: [\r\n                fx(\"compressor\", {\r\n                    id: \"duck\",\r\n                    sidechain: \"kick\",\r\n                    threshold_db: -30,\r\n                    ratio: 6,\r\n                    attack_ms: 1,\r\n                    release_ms: 130\r\n                })\r\n            ]\r\n        })\r\n    ],\r\n    automation: [\r\n        automation(\"kick.out\", curve([[0b, -12], [4b, -30], [8b, 0]], \"step\")),\r\n        automation(\"kick.key_level.gain_db\", curve([[0b, 0], [8b, -12]], \"step\"))\r\n    ],\r\n    tail: 0.5\r\n})\r\n","examples/stereo-body.muz":"// The one-shot excitation finishes before its independent stereo echoes.\r\nlet body = voice_patch(\"body\", {\r\n    gain_db: -12,\r\n    nodes: [\r\n        {id: \"e\", op: \"adsr\", attack: 0, decay: 0.05, sustain: 0, one_shot: true},\r\n        {id: \"o\", op: \"osc\", wave: \"sine\"},\r\n        {id: \"hit\", op: \"mul\", inputs: [\"e\", \"o\"]},\r\n        {id: \"l\", op: \"delay\", input: \"hit\", seconds: 0.031, feedback: 0.65},\r\n        {id: \"r\", op: \"delay\", input: \"hit\", seconds: 0.043, feedback: 0.65}\r\n    ],\r\n    output: {left: \"l\", right: \"r\"},\r\n    lifetime: {envelope: \"e\", tail: 0.8}\r\n});\r\nsong({tracks: [track(\"body\", phrase(\"C4:q E4:q G4:q C5:q\"), body)], tail: 1})\r\n","examples/tagged-send.muz":"use \"std/mix\" as mix;\r\nlet timing = {tempo: 120, tempos: [[2bars, 100]]};\r\nlet material = phrase(\"C4:q E4:q G4:q B4:q\").tag(\"last\", \"answer\").repeat(4);\r\n// Custom policy: a velocity-shaped filter gesture for each tagged note.\r\nfn brighten(material) {\r\n    let notes = sort_by(material.select(\"answer\").notes, fn(n) => n.at);\r\n    let points = fold(\r\n        notes,\r\n        [[0s, 700]],\r\n        fn(points, n) =>\r\n            points\r\n            + [\r\n                [mix.note_start(n, timing), 700],\r\n                [mix.note_start(n, timing) + 60ms, 700 + n.velocity * 6000],\r\n                [mix.note_end(n, timing), 700]\r\n            ]\r\n    );\r\n    automation(\"lead.tone.cutoff_hz\", curve(points, \"smooth\"))\r\n}\r\nsong(\r\n    merge(timing, {\r\n        tracks: [\r\n            track(\"lead\", material, synth(\"glass-lead\"), {\r\n                chain: [fx(\"lowpass\", {id: \"tone\", cutoff_hz: 700})],\r\n                sends: {echo: -120}\r\n            })\r\n        ],\r\n        buses: [bus(\"echo\", [fx(\"delay\", {time_beats: 0.5, mix: 1})])],\r\n        automation: [\r\n            brighten(material),\r\n            // A second policy, implemented entirely in std/mix.muz.\r\n            mix.throws(material, \"answer\", \"lead.send.echo\", -12, tail = 180ms, timing = timing)\r\n        ],\r\n        tail: 2\r\n    })\r\n)\r\n","examples/tonal-assistance.muz":"use \"std/tonal\" as tonal;\r\nlet key = scale(\"E\", \"harmonic_minor\", octave = 3);\r\nlet harmony = tonal.progression(key, [1, 6, 4, 5]).tag(\"last\", \"fixed\");\r\nlet melody = tonal.melody(key, [8, 10, 9, 8, 7, 6, 5, 7, 8, 6, 4, 6, 7, 9, 7, 5]);\r\nlet alternative = reharmonize(harmony, melody, [\"Em\", \"Cmaj7\", \"Am\", \"B7\"]);\r\nsong({\r\n    tracks: [\r\n        track(\"lead\", melody, synth(\"bell\")),\r\n        track(\"harmony\", voicelead(alternative, low = 48, high = 84), synth(\"pad\"), {gain: -8})\r\n    ]\r\n})\r\n","examples/voice-expression.muz":"// A bent, brightening note overlaps a steady harmony; expression stays on that note.\r\nlet voice = voice_patch(\"glass\", {\r\n    nodes: [\r\n        {id: \"env\", op: \"adsr\", attack: 0.02, decay: 0.3, sustain: 0.65, release: 0.2},\r\n        {id: \"bright\", op: \"expression\", kind: \"brightness\"},\r\n        {id: \"range\", op: \"mul\", inputs: [\"bright\", 6500]},\r\n        {id: \"cutoff\", op: \"sum\", inputs: [\"range\", 500]},\r\n        {id: \"osc\", op: \"osc\", wave: \"saw\"},\r\n        {id: \"filter\", op: \"filter\", input: \"osc\", cutoff: \"cutoff\"},\r\n        {id: \"out\", op: \"mul\", inputs: [\"env\", \"filter\"]}\r\n    ],\r\n    output: \"out\"\r\n});\r\nlet harmony = phrase(\"[C4 E4 G4]:w\").velocity(0.4);\r\nlet answer = note(\"B4\", 3b, at = 1b).express({\r\n    tuning: [[0, -0.2], [0.3, 0], [0.8, 0], [1, 1]],\r\n    brightness: [[0, 0.2], [1, 0.8]],\r\n    pan: 0.7\r\n});\r\nsong({tracks: [track(\"glass\", stack([harmony, answer]), voice)], tail: 0.5})\r\n"},"packages":[{"directory":"contrib","readme":"contrib/README.md","requirements":["External samples","Native plugins"]},{"directory":"contrib/karoryfer","readme":"contrib/karoryfer/README.md","requirements":["External samples"]},{"directory":"contrib/plugins","readme":"contrib/plugins/README.md","requirements":["Native plugins"]},{"directory":"contrib/sonatina","readme":"contrib/sonatina/README.md","requirements":[]},{"directory":"contrib/unreal/metal-gtx","readme":"contrib/unreal/metal-gtx/README.md","requirements":["External samples"]},{"directory":"contrib/unreal/standard-guitar","readme":"contrib/unreal/standard-guitar/README.md","requirements":["External samples"]},{"directory":"contrib/virtuosity-drums","readme":"contrib/virtuosity-drums/README.md","requirements":["External samples"]},{"directory":"contrib/vsco-2-ce","readme":"contrib/vsco-2-ce/README.md","requirements":["External samples"]}],"gists":[],"engine":{"commit":"f648c86737f0b995e9c86181bab09075d2700d91","clean":false}}"""

